const handlers={},forms={},renderers={};
const el=id=>document.getElementById(id);
const save=()=>{window.CMReview?.scheduleSave?.();if(window.CM_SERVER_MODE)return state;try{localStorage.setItem(KEY,JSON.stringify(Auth.stripSession(state)));Auth.persist(localStorage,sessionStorage,state.session);}catch{if(!window.CM_REVIEW&&!UI.storageWarned){UI.storageWarned=true;toast('В этом режиме изменения хранятся только до закрытия страницы. Сохрани их через экспорт.',true);}}return state;};
const startSession=(id,remember=false)=>{if(window.CM_SERVER_MODE)throw Error("Вход подтверждается сервером.");state.session=Auth.begin(id,remember);save();return state.session;};
const endSession=()=>{state.session=null;try{Auth.clear(localStorage,sessionStorage);}catch{}save();};
const me=()=>state.players.find(p=>p.id===state.session?.id)||null;
const money=(n,c)=>`${Number(n||0).toLocaleString('ru-RU')} ${c==='CM'?'CM':c}`;
const date=(n,short=false)=>n?new Date(n).toLocaleString('ru-RU',short?{day:'2-digit',month:'short'}:{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Не определено';
const asset=p=>window.CM_ASSETS?.[p]||p;
const item=id=>state.catalog.find(p=>p.id===id);
const btn=(label,action,iconName='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${iconName?icon(iconName):''}${label}</button>`;
const link=(label,href,ic='',cls='')=>`<a class="btn ${cls}" href="${href}">${ic?icon(ic):''}${label}</a>`;
const iconBtn=(name,label,action,extra='')=>`<button type="button" class="icon-btn" aria-label="${label}" title="${label}" data-action="${action}" ${extra}>${icon(name)}</button>`;
const pill=(s,t='')=>`<span class="tag ${t}">${esc(s)}</span>`;
const STATUS={awaiting_delivery:['Ожидает выдачи','amber'],processing:['Выполняется','amber'],pending:['Ожидает подтверждения','amber'],completed:['Подтверждено','green'],paid:['Оплачен','green'],test_completed:['Тестовый платёж',''],failed:['Ошибка','danger'],partially_failed:['Частичный возврат','amber'],refunded:['Возвращено',''],queued:['Ожидает выдачи','amber'],delivered:['Получен','green'],cancelled:['Отменён',''],open:['Новое','amber'],review:['На проверке',''],closed:['Закрыто','green'],active:['Активен','green'],banned:['Заблокирован','danger']};
const status=(s)=>pill((STATUS[s]||[s])[0],(STATUS[s]||['',''])[1]);
const empty=(title,text,ic='package')=>`<div class="empty-state">${icon(ic)}<h3>${title}</h3><p>${text}</p></div>`;
const audit=(action,target,detail='')=>{const redact=window.CM5Domain?.redact||String;const row={id:'local-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),actor:UI.page==='admin'?'DemoAdmin':me()?.name||'Гость',action:redact(action),target:redact(target),detail:redact(detail),at:Date.now(),provenance:'local-demo'};state.audit.unshift(row);state.audit=state.audit.slice(0,200);save();window.CM5?.record?.({source:'Панель',action:'ADMIN_ACTION',player:row.actor,message:row.action+': '+row.target,raw:'[Panel/INFO] '+row.action+' target='+row.target+' '+row.detail});};
function toast(text,error=false){if(!el('toast-stack')){document.addEventListener('DOMContentLoaded',()=>toast(text,error),{once:true});return;}const t=document.createElement('div');t.className='toast'+(error?' error':'');t.setAttribute('role','status');t.textContent=text;el('toast-stack').append(t);setTimeout(()=>t.remove(),5500);}
function openModal(title,body,cls=''){UI.backFocus=document.activeElement;const d=el('modal');d.className=cls;d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${iconBtn('x','Закрыть окно','close')}</div><div class="dialog-content">${body}</div>`;if(!d.open)d.showModal();}
function closeModal(){const d=el('modal');if(d.open)d.close();if(UI.backFocus?.isConnected)UI.backFocus.focus();}
function downloadFile(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function header(active){const p=me();return `<div class="container"><header class="site-header"><a class="brand" href="#home" aria-label="CopiMine — главная"><img class="brand-mark" src="${asset('assets/img/icon.webp')}" alt=""><img class="wordmark" src="${asset('assets/img/logo.webp')}" alt="CopiMine" width="162" height="33"></a><nav class="site-nav" aria-label="Основная навигация"><a href="#home" class="${active==='home'?'active':''}">Главная</a><a href="#shop" class="${active==='shop'?'active':''}">Магазин</a><a href="#map" class="${active==='map'?'active':''}">Карта</a><a href="#mapart" class="${active==='mapart'?'active':''}">Картины</a><a href="#rules" data-nav="rules">Правила</a></nav><div class="header-actions">${p?`<a class="btn ghost" href="#account">${icon('user')}<span class="account-label">${esc(p.name)}</span></a>`:`<a class="btn ghost login-link" href="#auth/login">Войти</a><a class="btn ghost registration-link" href="#auth/register">Регистрация</a>`}${btn('Играть','play','play','primary')}${iconBtn('menu','Открыть меню','menu','')}</div></header></div>`;}
function footer(){return `<footer class="site-footer"><div>CopiMine <span class="quiet">/ Minecraft-сервер</span></div><div class="links"><a href="#rules">Правила</a><button type="button" data-action="discord">Discord</button><a href="#account/support">Помощь</a><button type="button" data-action="sources">О прототипе</button></div><span>Не связан с Mojang и Microsoft.</span></footer>`;}
function dock(){return `<div class="demo-dock" aria-label="Панель проверки прототипа"><span>${icon('monitor')}Локальный прототип</span><button data-action="demo-player">Игрок</button><a href="#admin/overview" class="${UI.page==='admin'?'active':''}">Админка</a><button class="dock-extra" data-action="export">Экспорт</button><button data-action="reset">Сброс</button></div>`;}
function navTo(path){if(location.hash==='#'+path)render();else location.hash=path;}
function mountRoute(page,tab){if(page==='shop')bindShop();if(page==='map')CMMap.init(false);if(page==='admin')bindAdmin(tab||'overview');if(page==='settings')bindSettings(tab||'profile');window.CMV4?.afterRender?.(page,tab||'');}
function render(){if(window.CM_SERVER_MODE&&window.CMReview?.ready!==true)return;const sideScroll=document.querySelector('.v71-admin-nav')?.scrollTop||0;const prevRoute=UI.renderedRoute,scrollY=window.scrollY,focusId=document.activeElement?.id,focusStart=document.activeElement?.selectionStart;closeModal();const raw=(location.hash.slice(1)||'home');const [route,query='']=raw.split('?');let [page,tab]=route.split('/');UI.params=new URLSearchParams(query);window.CMV4?.beforeRender?.();if(!renderers[page]){const slug=page,visible=(state.pages||[]).some(item=>item?.slug===slug&&item.published);if(visible){tab=slug;page='page';}else{location.assign('/error.html?code=404');return;}}UI.page=page;UI.tab=tab||'';document.body.className=page==='admin'?'admin-body':'';document.documentElement.dataset.motion=state.preferences.motion?'on':'off';document.title=({home:'Главная',shop:'Магазин',map:'Карта',mapart:'Картины',account:'Личный кабинет',auth:'Аккаунт',settings:'Настройки',admin:'Управление',rules:'Правила',privacy:'Политика конфиденциальности',cart:'Корзина',donate:'Донат',payment:'Оплата',download:'Установка',order:'Заказ','launcher-link':'Вход в лаунчер','launcher-demo':'Проверка лаунчера',page:'Страница'}[page]||'CopiMine')+' · CopiMine';const html=renderers[page](tab);const bridge=window.CopimineReactBridge;if(bridge?.render){const same=prevRoute===raw;UI.renderedRoute=raw;bridge.render({page,tab:tab||'',raw,html,header:header(page),footer:page==='map'?'':footer(),dock:dock(),same,scrollY,sideScroll,focusId,focusStart,revision:(UI.reactRevision=(UI.reactRevision||0)+1)});return;}const app=el('app');app.removeAttribute('aria-busy');if(!el('persistent-header'))app.innerHTML='<div id="persistent-header"></div><div id="page-root"></div>';const h=el('persistent-header'),headerHtml=header(page);if(h.dataset.signature!==headerHtml){h.innerHTML=headerHtml;h.dataset.signature=headerHtml;}const root=el('page-root');if(page==='admin'&&root.querySelector('.admin-shell')&&root.querySelector('.admin-shell').className===new DOMParser().parseFromString(html,'text/html').querySelector('.admin-shell')?.className){const template=document.createElement('template');template.innerHTML=html;const fresh=template.content;root.querySelector('#view').replaceChildren(...fresh.querySelector('#view').childNodes);const breadcrumb=root.querySelector('.breadcrumb');if(breadcrumb)breadcrumb.innerHTML=fresh.querySelector('.breadcrumb').innerHTML;const side=root.querySelector('.admin-sidebar');if(side){side.innerHTML=fresh.querySelector('.admin-sidebar').innerHTML;const inner=side.querySelector('.v71-admin-nav');if(inner)inner.scrollTop=sideScroll;}}else root.innerHTML=page==='admin'?html:`<main id="view"${page==='map'?'':' class="container"'}>${html}</main>`+(page==='map'?'':`<div class="container">${footer()}</div>`);if(el('dock-root').innerHTML!==dock())el('dock-root').innerHTML=dock();const mt=document.querySelector('.header-actions button[aria-label="Открыть меню"]');if(mt)mt.classList.add('mobile-nav-toggle');if(page==='shop')bindShop();if(page==='map')CMMap.init(false);if(page==='admin')bindAdmin(tab||'overview');if(page==='settings')bindSettings(tab||'profile');window.CMV4?.afterRender?.(page,tab||'');const same=prevRoute===raw;UI.renderedRoute=raw;if(same){window.scrollTo({top:scrollY,behavior:'instant'});const focus=focusId?document.getElementById(focusId):null;if(focus){focus.focus({preventScroll:true});try{focus.setSelectionRange(focusStart,focusStart);}catch{}}}else window.scrollTo({top:0,behavior:'instant'});}
function productCard(p){return `<article class="product reveal"><div class="product-image"><span class="tag">${esc(p.category)}</span><img src="${asset(p.image)}" alt="${esc(p.name)}" width="86" height="86" loading="lazy">${iconBtn('arrow-up-right','Подробнее: '+esc(p.name),'product',`data-id="${p.id}"`)}</div><div class="product-body"><h3><button data-action="product" data-id="${p.id}" style="text-align:left;padding:0;font:inherit">${esc(p.name)}</button></h3><p>${esc(p.description)}</p><div class="product-bottom"><span class="price">${p.price.toLocaleString('ru-RU')} <small>${p.currency}</small></span>${btn('В корзину','add-cart','plus','',`data-id="${p.id}"`)}</div></div></article>`;}
renderers.home=()=>`<section class="hero"><img class="hero-photo" src="${asset('assets/img/world.webp')}" alt="Игровой пейзаж из материалов CopiMine" fetchpriority="high"><div class="hero-copy"><div class="kicker">Minecraft · CopiMine</div><h1>${esc(state.config.headline)}</h1><p>${esc(state.config.description)}</p><div class="actions">${btn('Начать играть','play','play','primary large')}${link('Посмотреть карту','#map','map','large')}</div></div><div class="hero-foot"><strong>ГОЛОСОВОЙ ЧАТ И ОБЩИЙ МИР</strong><span>Лаунчер — по желанию</span></div></section><div class="intro-rail"><a href="#shop">${icon('bag')}<div><strong>Игровые предметы</strong><small>Выбрать, купить, забрать в игре</small></div>${icon('arrow-up-right','push-right')}</a><a href="#map">${icon('map')}<div><strong>Карта мира</strong><small>Без позиций игроков</small></div>${icon('arrow-up-right','push-right')}</a><button data-action="discord">${icon('discord')}<div><strong>Наш Discord</strong><small>Общение, помощь и планы на вечер</small></div>${icon('arrow-up-right','push-right')}</button></div><section class="section"><div class="section-head"><div><div class="kicker">О сервере</div><h2>Карта миров.</h2></div><p>Карта помогает ориентироваться, но не следить за другими игроками.</p></div><div class="map-teaser map-teaser-unavailable"><div class="map-teaser-copy"><span class="tag green">${icon('map')}Статус карты</span><h3>Карта ещё не опубликована</h3><p>Снимок появится после проверки и публикации в настройках карты.</p>${link('Открыть карту','#map','arrow-right','primary')}</div></div><div class="protect-strip">${icon('shield')}<div><strong>Постройку сломали? Разберёмся по истории.</strong><p>Жалоба, проверка блоков, решение модератора.</p></div>${btn('Как это работает','protection','arrow-up-right','ghost small')}</div></section><section class="section" style="padding-top:0"><div class="section-head"><div><div class="kicker">Магазин CopiMine</div><h2>Полезное в дорогу.</h2></div><a class="text-link" href="#shop">Весь каталог ${icon('arrow-right')}</a></div><div class="product-grid four">${['return_stone','infinite_torch','pohuy_na_debaffy_amulet','berserker_heart'].map(id=>item(id)).filter(x=>x?.enabled).map(productCard).join('')}</div></section><section class="discord-band"><div class="discord-identity">${icon('discord')}<div><h2>Продолжим в Discord.</h2><p>Найди компанию, задай вопрос или покажи свою постройку.</p></div></div><div class="discord-actions">${btn('Открыть сервер','discord','arrow-up-right','primary')}<button class="text-link" data-action="discord-widget">Посмотреть баннер Discord ${icon('arrow-right')}</button></div></section>`;
renderers.shop=()=>`<div class="page-head"><div><h1>Магазин</h1><p>Игровые предметы с понятными свойствами. Все покупки — в твоём кабинете.</p></div>${btn(`Корзина <span class="badge-count" id="cart-count">${state.cart.reduce((s,x)=>s+x.qty,0)}</span>`,'cart','bag','')}</div><div class="shop-layout"><aside class="shop-side"><div class="label">Каталог</div><div class="filter-nav" id="category-nav">${['Все предметы','Инструменты','Снаряжение','Путешествия','Оружие'].map(x=>`<button data-action="category" data-value="${x}" class="${UI.category===x?'active':''}">${x}<small>${state.catalog.filter(p=>p.enabled&&(p.visibility||'public')==='public'&&(x==='Все предметы'||x===p.category)).length}</small></button>`).join('')}</div><div class="wallet-note">${me()?`<strong>На твоём счёте</strong><p class="mt12">${money(me().AR,'AR')}<br>${money(me().CM,'CM')}</p>${link('Открыть кабинет','#account','','small mt12')}`:`<strong>Сначала можно выбрать.</strong><p class="mt12">Войти понадобится перед покупкой.</p>${link('Войти','#auth/login','user','small mt12')}`}</div><div class="wallet-note"><strong>AR и CM не смешиваются</strong><p class="mt12">AR — игровая валюта. CM — донатные монеты. Корзина считает их отдельно.</p></div></aside><section><div class="shop-tools"><label class="input-wrap search-box">${icon('search')}<input id="shop-search" placeholder="Название, материал или способность" value="${esc(UI.search)}" aria-label="Поиск предметов"></label><div class="segmented" id="currency-nav">${[['ALL','Все'],['AR','За AR'],['CM','За CM']].map(([v,l])=>`<button data-action="currency" data-value="${v}" class="${UI.currency===v?'active':''}">${l}</button>`).join('')}</div><select id="shop-sort" aria-label="Сортировка"><option value="default">По умолчанию</option><option value="price">Сначала дешевле</option><option value="name">По названию</option></select></div><div class="row mb"><span id="result-count" class="hint"></span><span class="spacer"></span><button class="text-link" data-action="how-buy">Как получить покупку ${icon('info')}</button></div><div class="product-grid" id="products"></div></section></div>`;
function bindShop(){el('shop-sort').value=UI.sort;el('shop-search').addEventListener('input',e=>{UI.search=e.target.value;updateProducts();});el('shop-sort').onchange=e=>{UI.sort=e.target.value;updateProducts();};updateProducts();}
function updateProducts(){const query=UI.search.trim();let list=state.catalog.filter(p=>p.enabled&&(p.visibility||'public')==='public'&&(UI.category==='Все предметы'||p.category===UI.category)&&(UI.currency==='ALL'||p.currency===UI.currency)&&(!query||CM73Domain.rank(query,CM73Domain.productSearchTerms(p))<Infinity));if(query&&UI.sort==='default')list.sort((a,b)=>CM73Domain.rank(query,CM73Domain.productSearchTerms(a))-CM73Domain.rank(query,CM73Domain.productSearchTerms(b)));if(UI.sort==='price')list.sort((a,b)=>a.currency.localeCompare(b.currency)||a.price-b.price);if(UI.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ru'));el('products').innerHTML=list.length?list.map(productCard).join(''):empty('Ничего не найдено','Поищи по назначению, материалу или игровому названию.','search');el('result-count').textContent=`Показано ${list.length} из ${state.catalog.filter(p=>p.enabled&&(p.visibility||'public')==='public').length} предметов`;document.querySelectorAll('#category-nav button').forEach(b=>b.classList.toggle('active',b.dataset.value===UI.category));document.querySelectorAll('#currency-nav button').forEach(b=>b.classList.toggle('active',b.dataset.value===UI.currency));}
function accountTabs(tab){return `<nav class="tabs" aria-label="Разделы кабинета">${[['overview','Обзор','user'],['orders','Покупки','bag'],['payments','Платежи','wallet'],['support','Обращения','chat']].map(([v,l,i])=>`<a href="#account/${v}" class="${tab===v?'active':''}">${icon(i)}${l}</a>`).join('')}<a href="#settings/profile" class="push-right">${icon('settings')}Настройки</a></nav>`;}
function orderRows(orders){return orders.map(o=>`<div class="list-row"><img src="${asset(item(o.item)?.image||'assets/items/01.png')}" alt=""><div><strong>${esc(o.name)}</strong><small>${esc(o.id)} · ${date(o.at,true)} · ${money(o.total,o.currency)}</small></div>${status(o.status)}${iconBtn('chevron-right','Подробнее о заказе','order-detail',`data-id="${o.id}"`)}</div>`).join('');}
renderers.account=(tab)=>{const p=me();if(!p)return renderers.auth('login');tab=tab||'overview';let content='';const orders=state.orders.filter(o=>o.player===p.name);if(tab==='orders'){content=`<section class="panel mb"><div class="panel-head"><h3>История покупок</h3>${link('В магазин','#shop','arrow-up-right','small')}</div>${orders.length?orderRows(orders):empty('Покупок пока нет','Предметы из магазина появятся здесь после оформления.')}</section>`;}else if(tab==='support'){const list=state.tickets.filter(t=>t.player===p.name);content=`<section class="panel mb"><div class="panel-head"><h3>Мои обращения</h3>${btn('Написать','new-ticket','plus','primary small')}</div>${list.map(t=>`<div class="list-row">${icon('chat')}<div><strong>${esc(t.title)}</strong><small>${t.id} · ${date(t.at,true)}</small></div>${status(t.status)}${btn('Открыть','ticket-detail','','small',`data-id="${t.id}"`)}</div>`).join('')||empty('Обращений нет','Здесь будут ответы администрации.','chat')}</section>`;}else{content=`<div class="balance-pair"><section class="balance-cell"><div><div class="label">Игровая валюта</div><div class="value">${p.AR.toLocaleString('ru-RU')}<small>AR</small></div><small>Зарабатывай и торгуй в игре</small></div>${btn('Перевести','transfer','arrow-up-right','small')}</section><section class="balance-cell"><div><div class="label">Донатный баланс</div><div class="value">${p.CM.toLocaleString('ru-RU')}<small>CM</small></div><small>Для покупок в магазине</small></div>${btn('Пополнить','topup','plus','small')}</section></div><div class="account-columns account-single"><section class="panel"><div class="panel-head"><h3>Последние покупки</h3><a class="text-link" href="#account/orders">Все ${icon('arrow-right')}</a></div>${orders.length?orderRows(orders.slice(0,3)):empty('Здесь будут твои покупки','Посмотри предметы в магазине.')}</section></div>`;}return `<div class="page-head"><div class="account-identity"><div class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</div><div><h1 style="font-size:36px">Привет, ${esc(p.name)}.</h1><p>Покупки, баланс и ответы команды — здесь.</p></div></div>${btn('Выйти','logout','logout','ghost small')}</div>${accountTabs(tab)}${content}`;};
renderers.auth=(tab='login')=>{const reg=tab==='register';return `<div class="auth-layout"><div class="auth-art"><div><h2>Покупки, баланс<br>и поддержка</h2><p>Войди, чтобы проверить заказы, открыть настройки и написать администрации.</p></div></div><section class="auth-form"><h1>${reg?'Создать аккаунт':'Вход в аккаунт'}</h1><p class="muted">${reg?'Создай аккаунт для покупок и обращений на сайте.':'Войди, чтобы открыть покупки, баланс и обращения.'}</p><nav class="tabs"><a href="#auth/login" class="${reg?'':'active'}">Вход</a><a href="#auth/register" class="${reg?'active':''}">Регистрация</a></nav><form data-form="${reg?'register':'login'}"><label class="field">Никнейм<input name="username" autocomplete="username" pattern="[A-Za-z0-9_]{3,16}" minlength="3" maxlength="16" placeholder="Твой ник в игре" required><small>Латинские буквы, цифры и подчёркивание. От 3 до 16 символов.</small></label>${reg?`<label class="field">Почта для восстановления<input name="email" type="email" placeholder="name@example.test" autocomplete="email" required></label>`:''}<label class="field">Пароль<div class="password-wrap"><input name="password" type="password" autocomplete="${reg?'new-password':'current-password'}" minlength="8" maxlength="128" placeholder="Не меньше 8 символов" required>${iconBtn('eye','Показать пароль','toggle-password')}</div></label>${reg?`<label class="radio-line"><input name="terms" type="checkbox" required>Принимаю правила сервера</label>`:''}<div class="form-error" role="alert"></div><button class="btn primary wide" type="submit">${reg?'Создать аккаунт':'Войти'}${icon('arrow-right')}</button></form><div class="auth-demo"><small>Это локальный прототип. Используй вымышленные данные, не рабочий пароль.</small>${btn('Войти как DemoBuilder','demo-player','user','wide')}<small class="mt12">Тестовый вход: DemoBuilder / copimine-demo</small></div></section></div>`;};
renderers.settings=(tab='profile')=>{if(!me())return renderers.auth('login');const p=me();let content='';if(tab==='security'){content=`<h3>Пароль и устройства</h3><p class="help-copy mt12">В прототипе вход локальный. Настоящие сессии и защиту аккаунта подключит серверная часть.</p><div class="divider"></div><form data-form="password"><label class="field">Новый тестовый пароль<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><label class="field">Повтори пароль<input name="repeat" type="password" minlength="8" required autocomplete="new-password"></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Сохранить пароль</button></form><div class="divider"></div><div class="service-row"><div><strong>Этот браузер</strong><small>Локальная демонстрационная сессия</small></div>${btn('Завершить','logout','logout','small')}</div>`;}else if(tab==='interface'){content=`<h3>Интерфейс</h3><div class="toggle-row"><div><strong>Анимации</strong><small>Плавное появление страниц, окон и предметов</small></div><button class="switch" type="button" role="switch" aria-label="Анимации" aria-checked="${state.preferences.motion}" data-action="motion"></button></div><p class="hint mt">Системная настройка уменьшенного движения имеет приоритет.</p>`;}else{content=`<h3>Профиль</h3><div class="divider"></div><form data-form="profile"><label class="field">Никнейм<input value="${esc(p.name)}" disabled><small>В этом макете ник не меняется после регистрации.</small></label><label class="field">Почта<input type="email" name="email" placeholder="name@example.test" value="${esc(p.email||'')}"></label><label class="field">Как к тебе обращаться<input name="displayName" maxlength="32" value="${esc(p.displayName||p.name)}"></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Сохранить изменения</button></form>`;}return `<div class="page-head"><div><h1>Настройки</h1><p>Профиль, безопасность и вид интерфейса.</p></div>${link('В кабинет','#account','arrow-left','ghost small')}</div><div class="settings-layout"><nav class="filter-nav">${[['profile','Профиль'],['security','Безопасность'],['interface','Интерфейс']].map(([v,l])=>`<a href="#settings/${v}" class="btn ${tab===v?'primary':'ghost'}" style="justify-content:flex-start">${icon(v==='profile'?'user':v==='security'?'lock':'settings')}${l}</a>`).join('')}</nav><section class="panel">${content}</section></div>`;};
function bindSettings(){}
renderers.mapart=()=>'';
renderers.rules=()=>`<div class="page-head"><div><h1>Правила и помощь</h1><p>Краткая структура раздела. Окончательные правила задаются в админке.</p></div></div><div class="panel mb help-copy"><h3>Уважай чужое</h3><p>Не ломай постройки и не забирай чужие вещи без разрешения. О спорной ситуации напиши администрации.</p><h3>Играй без нечестного преимущества</h3><p>Не используй читы, дюпы и ошибки сервера. О найденной ошибке лучше сообщить в обращении.</p><h3>Как рассматривают жалобу</h3><p>Модератор проверяет историю действий, фиксирует решение и сообщает его участникам. Бан и откат — разные действия, каждое с подтверждением.</p><div class="notice mt">${icon('info')}Это редакционный проект правил для согласования, не опубликованная политика сервера.</div></div>`;
handlers.close=closeModal;
handlers.play=()=>openModal('Как тебе удобнее играть?',`<p>Для входа нужны CopiMineClient и голосовой чат. Лаунчер — по желанию.</p><div class="install-grid"><section class="install-option">${icon('package')}<h3>Скачать моды</h3><p>Для тех, у кого Minecraft уже установлен.</p><ul><li>${icon('check')}Наш мод CopiMineClient</li><li>${icon('check')}Simple Voice Chat</li><li>${icon('check')}Нужные зависимости и инструкция</li></ul>${btn('Скачать архив','download-mods','download','primary wide')}<small class="hint">${(state.config.modUrl||window.CM_RELEASE_FILES?.mods)?'Файл назначен администрацией.':'Архив для новой версии ещё не назначен.'}</small></section><section class="install-option">${icon('monitor')}<h3>Скачать лаунчер <small>(необязательно)</small></h3><p>Отдельная установка CopiMine без ручной замены файлов.</p><ul><li>${icon('check')}Автообновление сборки</li><li>${icon('check')}Проверка и восстановление файлов</li><li>${icon('check')}Готовые настройки подключения</li></ul>${btn('Скачать лаунчер','download-launcher','download','wide')}<small class="hint">${(state.config.launcherUrl||window.CM_RELEASE_FILES?.launcher)?'Файл назначен администрацией.':'Исполняемый файл ещё не назначен.'}</small></section></div><div class="divider"></div><div class="row"><span class="hint">Есть вопрос по установке?</span><button class="text-link" data-action="discord">Спросить в Discord ${icon('arrow-up-right')}</button></div>`);
function releaseDownload(type){const f=window.CM_RELEASE_FILES?.[type];if(f){const a=document.createElement('a');a.href=URL.createObjectURL(f);a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}const url=state.config[type==='mods'?'modUrl':'launcherUrl'];if(C.safeUrl(url)){window.open(url,'_blank','noopener,noreferrer');return;}toast('Файл релиза не подключён. В админке: Сайт и файлы → Загрузки. Игровые архивы здесь не подменяются макетами.',true);}
handlers['download-mods']=()=>releaseDownload('mods');handlers['download-launcher']=()=>releaseDownload('launcher');
handlers.menu=()=>openModal('CopiMine',`<div class="filter-nav" style="display:flex;flex-direction:column">${[['#home','Главная'],['#shop','Магазин'],['#map','Карта'],['#mapart','Картины'],['#rules','Правила'],['#auth/login','Войти'],['#auth/register','Регистрация'],['#account','Личный кабинет']].map(([h,l])=>link(l,h)).join('')}</div>`);
handlers.protection=()=>openModal('Как разбирают жалобы',`<p>Сигнал — это повод проверить историю, а не автоматический приговор.</p><div class="steps mt">${[['01','Жалоба','Сообщи место, время и что произошло.'],['02','Проверка','Модератор сравнит блоки и действия игроков.'],['03','Решение','При подтверждении — точечный откат и санкция.']].map(([n,t,p])=>`<div><span class="step-num">${n}</span><strong>${t}</strong><p>${p}</p></div>`).join('')}</div><div class="notice mt">${icon('shield')}Мы не обещаем «бан за минуту». Срок зависит от доказательств и проверки.</div><div class="actions mt">${link('Сообщить о проблеме','#account/support','chat','primary')}${link('Открыть пример расследования','#admin/moderation','arrow-right')}</div>`);
handlers.product=b=>{const p=item(b.dataset.id);if(!p)return;openModal(esc(p.name),`<div class="product-detail"><div class="product-detail-visual"><img src="${asset(p.image)}" alt="${esc(p.name)}"></div><div>${pill(p.category)}<p class="mt12">${esc(p.description)}</p><dl class="detail-specs"><div><dt>Стоимость</dt><dd>${money(p.price,p.currency)}</dd></div><div><dt>Перезарядка</dt><dd>${p.cooldown?p.cooldown+' сек.':'Не указана'}</dd></div><div><dt>Привязан к владельцу</dt><dd>${p.ownerBound?'Да':'Нет'}</dd></div><div><dt>Лимит в заказе</dt><dd>${p.limit}</dd></div></dl>${btn('Добавить в корзину','add-cart','plus','primary wide',`data-id="${p.id}"`)}<p class="hint mt12">Текстура, цена и свойства — из каталога проекта. Названия отредактированы для новой витрины.</p></div></div>`);};
handlers['add-cart']=b=>{const p=item(b.dataset.id);if(!p?.enabled)return;const row=state.cart.find(x=>x.id===p.id);if((row?.qty||0)>=p.limit)return toast('Достигнут лимит: '+p.limit+' шт.',true);if(row)row.qty++;else state.cart.push({id:p.id,qty:1});save();if(el('cart-count'))el('cart-count').textContent=state.cart.reduce((s,x)=>s+x.qty,0);toast(p.name+' — в корзине');};
handlers.category=b=>{UI.category=b.dataset.value;updateProducts();};handlers.currency=b=>{UI.currency=b.dataset.value;updateProducts();};
function cartModal(){let q;try{q=C.quote(state.cart,state.catalog);}catch(e){openModal('Корзина',`<div class="notice warn">${icon('alert')}${esc(e.message)}</div>${btn('Очистить корзину','clear-cart','trash','mt')}`);return;}openModal('Корзина'+(q.lines.length?' · '+q.lines.length:''),q.lines.length?`${q.lines.map(p=>`<div class="cart-line"><img src="${asset(p.image)}" alt=""><div class="cart-info"><strong>${esc(p.name)}</strong><small>${money(p.price,p.currency)} за штуку</small></div><div class="qty">${iconBtn('minus','Уменьшить количество','qty-minus',`data-id="${p.id}"`)}<span>${p.qty}</span>${iconBtn('plus','Увеличить количество','qty-plus',`data-id="${p.id}"`)}</div><span class="price">${money(p.total,p.currency)}</span>${iconBtn('trash','Убрать '+esc(p.name),'remove-cart',`data-id="${p.id}"`)}</div>`).join('')}<div class="checkout-total">${Object.entries(q.totals).filter(([,n])=>n).map(([c,n])=>`<div class="cart-total"><span>${c==='AR'?'Игровая валюта':'Донатные монеты'}</span><strong>${money(n,c)}</strong></div>`).join('')}</div><p class="hint mt12">${me()?'Получатель: '+esc(me().name)+'. ':'Для покупки войди в аккаунт. '}Выдача — после обработки заказа в игре.</p><div class="actions mt">${me()?btn('Оформить тестовую покупку','checkout','check','primary wide'):link('Войти и продолжить','#auth/login','user','primary wide')}</div><p class="hint mt12">Локальный прототип: настоящие деньги и игровые балансы не затрагиваются.</p>`:empty('Корзина пуста','Добавь предметы из каталога.','bag'));}
handlers.cart=cartModal;handlers['clear-cart']=()=>{state.cart=[];save();cartModal();};handlers['remove-cart']=b=>{state.cart=state.cart.filter(x=>x.id!==b.dataset.id);save();cartModal();};handlers['qty-minus']=b=>{const r=state.cart.find(x=>x.id===b.dataset.id);if(r&&r.qty>1)r.qty--;else state.cart=state.cart.filter(x=>x.id!==b.dataset.id);save();cartModal();};handlers['qty-plus']=b=>{const r=state.cart.find(x=>x.id===b.dataset.id);if(r.qty<item(r.id).limit)r.qty++;else toast('Больше нельзя: ограничение предмета.',true);save();cartModal();};
handlers.checkout=()=>{const p=me();if(!p)return navTo('auth/login');let q;try{q=C.quote(state.cart,state.catalog);}catch(e){toast(e.message,true);return;}if(!q.lines.length)return;for(const c of ['AR','CM'])if(p[c]<q.totals[c])return toast('Недостаточно '+c+'. Пополни тестовый баланс в кабинете.',true);const now=Date.now();p.AR-=q.totals.AR;p.CM-=q.totals.CM;for(const [i,l] of q.lines.entries()){const order={id:'LOCAL-'+now.toString().slice(-7)+'-'+i,player:p.name,item:l.id,name:l.name,qty:l.qty,total:l.total,currency:l.currency,status:'queued',at:now,provenance:'local-demo'};state.orders.unshift(order);state.ledger.unshift({id:order.id,player:p.name,amount:-l.total,currency:l.currency,reason:'Покупка '+l.name,at:now});}state.cart=[];audit('Покупка',p.name,'Локальный заказ: '+q.lines.length+' позиций');render();openModal('Заказ оформлен',`<div class="center"><div class="success-check">${icon('check')}</div><h3>Предметы ждут выдачи.</h3><p class="mt12">Заказ появился в кабинете и в очереди администратора.</p>${link('Открыть покупки','#account/orders','arrow-right','primary mt')}<p class="hint mt">Это тестовая покупка. Реальной выдачи и списания на сервере нет.</p></div>`);};
handlers['order-detail']=b=>{const o=state.orders.find(x=>x.id===b.dataset.id);if(!o)return;openModal('Заказ '+esc(o.id),`<div class="list-row"><img src="${asset(item(o.item)?.image||'assets/items/01.png')}" alt=""><div><strong>${esc(o.name)}</strong><small>${o.qty} шт. · ${money(o.total,o.currency)}</small></div>${status(o.status)}</div><dl class="detail-specs"><div><dt>Получатель</dt><dd>${esc(o.player)}</dd></div><div><dt>Дата</dt><dd>${date(o.at)}</dd></div></dl><p>${o.status==='delivered'?'Выдача отмечена в локальной истории.':'Предмет ожидает обработки. В рабочей версии выдача подтверждается игровым плагином.'}</p>`);};
handlers['how-buy']=()=>openModal('От выбора до инвентаря',`<div class="steps"><div><span class="step-num">01</span><strong>Выбери предмет</strong><p>Проверь описание и валюту.</p></div><div><span class="step-num">02</span><strong>Оформи покупку</strong><p>Получатель — твой игровой аккаунт.</p></div><div><span class="step-num">03</span><strong>Забери в игре</strong><p>Статус выдачи появится в кабинете.</p></div></div>`);
handlers.topup=()=>openModal('Пополнение тестового баланса',`<div class="notice">${icon('info')}Это проверка интерфейса, не оплата. Реальные деньги не списываются.</div><form data-form="topup" class="mt"><label class="field">Количество донатных монет<input type="number" min="1" max="10000" step="1" name="amount" value="500" required></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary wide">Добавить тестовые CM</button></form>`);
forms.topup=(f,d)=>{const n=Number(d.get('amount'));if(!Number.isSafeInteger(n)||n<1||n>10000)throw Error('Укажи от 1 до 10 000 CM.');const p=me();p.CM+=n;state.ledger.unshift({id:'TOP-'+Date.now(),player:p.name,amount:n,currency:'CM',reason:'Тестовое пополнение',at:Date.now()});audit('Пополнение',p.name,money(n,'CM'));render();toast('На тестовый баланс добавлено '+money(n,'CM'));};
handlers.transfer=()=>{const p=me();openModal('Перевести AR',`<p>Перевод между тестовыми счетами.</p><form data-form="transfer" class="mt"><label class="field">Получатель<select name="to">${state.players.filter(x=>x.id!==p.id&&x.id!=='demo-admin').map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label class="field">Сумма<input name="amount" type="number" min="1" step="1" max="${p.AR}" required></label><div class="form-error" role="alert"></div><button class="btn primary wide" type="submit">Подтвердить перевод</button></form>`);};
forms.transfer=(f,d)=>{const p=me(),to=state.players.find(x=>x.id===d.get('to')),n=Number(d.get('amount'));if(!to||p.id===to.id||!Number.isSafeInteger(n)||n<1||n>p.AR)throw Error('Проверь получателя и сумму.');p.AR-=n;to.AR+=n;state.ledger.unshift({id:'TR-'+Date.now(),player:p.name,amount:-n,currency:'AR',reason:'Перевод '+to.name,at:Date.now()});audit('Перевод',p.name,to.name+' '+money(n,'AR'));render();toast('Тестовый перевод выполнен.');};
handlers['new-ticket']=()=>openModal('Написать администрации',`<form data-form="ticket"><label class="field">О чём вопрос<select name="type"><option>Постройка</option><option>Покупка</option><option>Вход в игру</option><option>Другое</option></select></label><label class="field">Коротко о проблеме<input name="title" maxlength="90" minlength="4" required></label><label class="field">Что произошло<textarea name="body" minlength="10" maxlength="2000" required placeholder="Время, место и что нужно проверить"></textarea></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary wide">Отправить обращение</button></form>`);
forms.ticket=(f,d)=>{if(!me())throw Error('Сначала войди.');const title=String(d.get('title')).trim(),body=String(d.get('body')).trim();if(title.length<4||body.length<10)throw Error('Опиши проблему подробнее.');state.tickets.unshift({id:'LOCAL-'+Date.now().toString().slice(-6),player:me().name,type:d.get('type'),title,body,status:'open',priority:'normal',at:Date.now()});audit('Обращение',me().name,title);navTo('account/support');render();toast('Обращение добавлено в локальную очередь.');};
handlers['ticket-detail']=b=>{const t=state.tickets.find(x=>x.id===b.dataset.id);if(!t)return;openModal(esc(t.title),`${pill(t.id)} ${status(t.status)}<p class="mt">${esc(t.body)}</p><p class="hint mt12">${esc(t.player)} · ${date(t.at)}</p>${t.reply?`<div class="panel mt"><strong>Ответ команды</strong><p class="mt12">${esc(t.reply)}</p></div>`:''}${UI.page==='admin'?`<form data-form="reply" class="mt"><input type="hidden" name="id" value="${t.id}"><label class="field">Ответ<textarea name="reply" minlength="3" required></textarea></label><label class="field">Статус<select name="status"><option value="review">На проверке</option><option value="closed">Закрыто</option></select></label><button class="btn primary" type="submit">Сохранить ответ</button></form>`:''}`);};
forms.reply=(f,d)=>{const t=state.tickets.find(x=>x.id===d.get('id'));t.reply=String(d.get('reply')).trim();t.status=d.get('status');audit('Ответ на обращение',t.id,t.status);render();toast('Ответ сохранён в прототипе.');};
function newSalt(){const a=new Uint8Array(16);crypto.getRandomValues(a);return Array.from(a).map(x=>x.toString(16).padStart(2,'0')).join('');}
async function digest(password,salt){if(!window.crypto?.subtle)throw Error('Для проверки паролей открой прототип через START.bat.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const raw=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(raw)).map(x=>x.toString(16).padStart(2,'0')).join('');}
forms.register=async(f,d)=>{const name=String(d.get('username')).trim(),pass=String(d.get('password'));if(!/^[A-Za-z0-9_]{3,16}$/.test(name))throw Error('Используй ник от 3 до 16 латинских символов.');if(state.players.some(x=>x.name.toLowerCase()===name.toLowerCase()))throw Error('Этот ник уже есть в локальном прототипе.');const salt=newSalt();const hash=await digest(pass,salt);const p={id:'local-'+Date.now(),name,email:String(d.get('email')),role:'Игрок',status:'active',AR:1800,CM:1200,auth:{salt,hash},provenance:'local-demo'};state.players.push(p);startSession(p.id,!!d.get('remember'));navTo('account');toast('Демонстрационный аккаунт создан. Начислены тестовые балансы.');};
forms.login=async(f,d)=>{const name=String(d.get('username')).trim(),password=String(d.get('password'));const p=state.players.find(x=>x.name.toLowerCase()===name.toLowerCase());let ok=false;if(p?.auth)ok=(await digest(password,p.auth.salt))===p.auth.hash;else ok=!!p&&password==='copimine-demo';if(!ok)throw Error('Неверный тестовый ник или пароль. Используй DemoBuilder / copimine-demo.');if(p.status==='banned')throw Error('Этот тестовый аккаунт заблокирован. Проверь раздел модерации.');startSession(p.id,!!d.get('remember'));navTo('account');};
handlers['toggle-password']=b=>{const i=b.parentElement.querySelector('input');i.type=i.type==='password'?'text':'password';b.setAttribute('aria-label',i.type==='password'?'Показать пароль':'Скрыть пароль');};
forms.profile=(f,d)=>{me().email=String(d.get('email')||'');me().displayName=String(d.get('displayName')||'').slice(0,32);save();toast('Изменения сохранены в этом браузере.');};
forms.password=async(f,d)=>{if(d.get('password')!==d.get('repeat'))throw Error('Пароли не совпадают.');const salt=newSalt();me().auth={salt,hash:await digest(String(d.get('password')),salt)};save();f.reset();toast('Тестовый пароль изменён.');};
handlers.motion=()=>{state.preferences.motion=!state.preferences.motion;save();render();};handlers.logout=()=>{if(!me())return navTo('home');openModal('Выйти из аккаунта?',`<div class="logout-confirm"><p>Ты выйдешь из CopiMine на этом устройстве. Корзина и история покупок останутся.</p><div class="actions mt">${btn('Остаться','close','','ghost')}${btn('Да, выйти','logout-commit','log-out','primary')}</div></div>`);};handlers['logout-commit']=()=>{endSession();closeModal();navTo('home');toast('Выход из аккаунта выполнен.');};handlers['demo-player']=()=>{startSession('demo-001',false);navTo('account');};
handlers.discord=()=>{
 const invite=String(state.config.discordInvite||'').trim();
 if(/^https:\/\/(?:discord\.gg\/[A-Za-z0-9_-]+|discord\.com\/invite\/[A-Za-z0-9_-]+)$/i.test(invite)){
  window.open(invite,'_blank','noopener,noreferrer');
  return;
 }
 const guild=String(state.config.discordGuild||'').trim();
 if(/^\d{17,20}$/.test(guild)){
  window.open(`https://discord.com/channels/${guild}`,'_blank','noopener,noreferrer');
  toast('Для входа новым участникам нужна ссылка-приглашение Discord.');
  return;
 }
 openModal('Discord пока не настроен',`<p>Ссылку-приглашение ещё не добавили. Напиши администрации через обращения в личном кабинете.</p><div class="actions mt">${link('Написать администрации','#account/support','chat','primary')}</div>`);
};
handlers['discord-widget']=()=>{openModal('Discord CopiMine',`<p>Баннер загружается с Discord, а не рисуется вместо него. Для новых участников нужна ссылка-приглашение.</p><div id="discord-real-widget" class="mt"><p class="hint">Запрашиваем официальный баннер…</p></div><div class="actions mt">${btn('Открыть сервер','discord','arrow-up-right','primary')}</div>`);const img=new Image();img.alt='Официальный виджет Discord CopiMine';img.referrerPolicy='no-referrer';img.src=`https://discord.com/api/guilds/${state.config.discordGuild}/widget.png?style=banner2`;img.onload=()=>{if(el('discord-real-widget'))el('discord-real-widget').replaceChildren(img);};img.onerror=()=>{if(el('discord-real-widget'))el('discord-real-widget').innerHTML='<div class="notice">'+icon('info')+'Discord не отдал баннер. Возможно, виджет отключён или нет сети. Ссылка на сервер работает отдельно.</div>';};};
handlers.export=()=>{const data=clone(state);for(const p of data.players)delete p.auth;data.session=null;downloadFile('copimine-local-state.json',JSON.stringify(data,null,2));toast('Экспорт готов. Пароли и сессия исключены.');};
handlers.reset=()=>openModal('Сбросить прототип?',`<p>Удалятся только изменения в этом браузере: тестовые заказы, метки и настройки. Каталог восстановится из приложенного набора.</p><div class="actions mt">${btn('Отмена','close','','')}${btn('Сбросить','reset-confirm','refresh','danger-btn')}</div>`);
handlers['reset-confirm']=()=>{state=clone(CM_SEED);state.mapPublished={id:'reference-01',markers:clone(state.markers),zones:clone(state.zones),image:null,capturedAt:null,publishedAt:null};save();UI.category='Все предметы';UI.currency='ALL';UI.search='';render();toast('Исходный набор восстановлен.');};
handlers.sources=()=>openModal('Что здесь настоящее',`<div class="help-copy"><h3>Из твоего проекта</h3><p>Логотип и фон — из архива лаунчера. 12 предметов, их текстуры, валюты и цены — из каталога IliaZav/copimine. Публичные названия приведены к короткой форме.</p><h3>Для проверки сценариев</h3><p>Аккаунты DemoBuilder, DemoTrader и DemoExplorer, обращения, балансы и заказы — явно тестовые. Дампа рабочей базы в материалах нет. Копию структуры и каталога можно открыть в data/prototype.sqlite.</p><h3>Карта</h3><p>Подложка — фрагмент твоего скриншота Makoto, не карта CopiMine. Админ может загрузить собственный снимок. Публичная карта использует опубликованную копию, а не черновик редактора.</p><h3>Что не подключено</h3><p>Платежи, баны, выдача в Minecraft, настоящая авторизация, серверный рендер карты и скачивание новых релизов. Ни один экран не отправляет команды игровому серверу.</p></div>`);
async function copyText(s){try{await navigator.clipboard.writeText(s);}catch{const t=document.createElement('textarea');t.value=s;document.body.append(t);t.select();document.execCommand('copy');t.remove();}toast('Скопировано.');}
handlers.copy=b=>copyText(b.dataset.value||'copimine.ru');
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const fn=handlers[b.dataset.action];if(fn){e.preventDefault();Promise.resolve().then(()=>{const result=fn(b,e);if(result&&typeof result.then==='function'){b.disabled=true;b.setAttribute('aria-busy','true');b.classList.add('is-loading');return result.finally(()=>{if(b.isConnected){b.disabled=false;b.removeAttribute('aria-busy');b.classList.remove('is-loading');}});}return result;}).catch(err=>toast(err.message||'Не удалось выполнить действие.',true));}});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const err=f.querySelector('.form-error'),submit=f.querySelector('[type=submit]');if(err)err.textContent='';if(submit){submit.disabled=true;submit.setAttribute('aria-busy','true');submit.classList.add('is-loading');}try{if(forms[f.dataset.form])await forms[f.dataset.form](f,new FormData(f));}catch(error){if(err){err.textContent=error.message;err.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}else toast(error.message,true);}finally{if(submit?.isConnected){submit.disabled=false;submit.removeAttribute('aria-busy');submit.classList.remove('is-loading');}}});
window.addEventListener('hashchange',render);
window.addEventListener('DOMContentLoaded',()=>{document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();const main=document.querySelector('main');if(main){main.tabIndex=-1;main.focus();main.scrollIntoView({block:'start',behavior:'auto'});}});el('modal').addEventListener('click',e=>{if(e.target===el('modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});render();});
window.CM={get state(){return state;},UI,handlers,forms,renderers,render,mountRoute,navTo,save,me,audit,toast,openModal,closeModal,asset,item,esc,btn,link,iconBtn,pill,status,date,money,empty,copyText,downloadFile,orderRows,clone,productCard,accountTabs,updateProducts,startSession,endSession};
document.addEventListener("click",e=>{const a=e.target.closest("#modal a[href^=\"#\"]");if(a)closeModal();});
window.addEventListener("copimine:react-ready",()=>window.CM?.render?.());
// Broken screen: offer support once per session instead of failing silently.
(()=>{let shown=false;try{shown=sessionStorage.getItem('cm-client-error')==='1';}catch{}
function report(){if(shown||window.CM?.UI?.page==='admin'||document.getElementById('cm-client-error'))return;shown=true;try{sessionStorage.setItem('cm-client-error','1');}catch{}
 const box=document.createElement('div');box.id='cm-client-error';box.className='cm-client-error';box.setAttribute('role','alert');
 box.innerHTML='<span>Что-то сломалось на стороне браузера. Если это повторяется — расскажите нам.</span><a href="#account/support">Написать в поддержку</a><button type="button" aria-label="Закрыть уведомление">×</button>';
 box.querySelector('button').addEventListener('click',()=>box.remove());document.body.append(box);}
window.addEventListener('error',e=>{if(!e.target||e.target===window||e.target===document)report();},true);
window.addEventListener('unhandledrejection',()=>report());
})();

/* assets/js/map.js *//* World preview source: bundled assets/img/map-world.webp from Снимок мира day-cache.
   Future public map source: server-side snapshot renderer every 12h, >=12h delayed.
   Do not fetch live player locations, waypoints, fresh blocks or hidden sectors. */
/* Snapshot-only map prototype: edits never alter the published view directly. */
(function(){
'use strict';
const M=window.CM, C=window.CMCore, esc=M.esc, NS='http://www.w3.org/2000/svg';
const colors={green:'#b6ed82',blue:'#7cbdec',amber:'#edc779'};
let editor=false,tool='move',points=[],selected=null,view={x:-512,y:-512,w:1024,h:1024},drag=null,lastUndo=null;
const now=()=>Date.now()+(M.state.mapTimeOffset||0);
const model=()=>editor?{markers:M.state.markers,zones:M.state.zones,image:M.state.mapImage}:M.state.mapPublished;
const due=s=>Math.ceil((s.capturedAt+12*C.HOUR)/(12*C.HOUR))*(12*C.HOUR);
const collection=()=>({markers:M.state.markers,zones:M.state.zones});
function checkpoint(){lastUndo=M.clone(collection());}
function nextPublication(){return M.state.mapPending?M.date(due(M.state.mapPending)):'После подготовки снимка';}
function markup(edit=false){editor=edit;const p=M.state.mapPublished;return `<div class="map-layout"><aside class="map-sidebar"><h1>${edit?'Карта и зоны':'Карта мира'}</h1><p>${edit?'Редактирование черновика. Посетители его не видят.':'Ориентиры, города и общие территории.'}</p><div class="map-status"><div class="row">${icon('clock')}<strong>Снимок, не прямой эфир</strong></div><p>Публикация каждые 12 часов. Данные не моложе 12 часов. Позиции игроков отключены.</p></div><div class="tabs map-tabs"><button class="active" data-action="map-list-all">Метки и зоны</button>${edit?M.iconBtn('plus','Добавить метку','map-add'):''}</div><div id="map-list"></div><div id="map-inspector"></div><div class="map-options"><div class="toggle-row"><span>Показывать метки</span><button class="switch on" role="switch" aria-checked="true" aria-label="Показывать метки" data-action="map-toggle-markers"></button></div><div class="toggle-row"><span>Показывать зоны</span><button class="switch on" role="switch" aria-checked="true" aria-label="Показывать зоны" data-action="map-toggle-zones"></button></div></div>${edit?`<div class="publication-panel"><div class="label">Публикация</div><p id="publish-status" class="mt12">${M.state.mapPending?'Снимок ожидает: '+nextPublication():'Нет снимков в очереди'}</p><div class="actions mt12">${M.btn('В очередь','map-queue','clock','primary small')}${M.btn('Проверить','map-publish','refresh','small')}</div><button class="text-link mt12" data-action="map-advance">Проверить +12 ч · демо</button></div><div class="upload-tile mt"><label for="map-image-file">Загрузить свой снимок<br><small>PNG, JPEG или WebP, до 2 МБ</small></label><input id="map-image-file" type="file" accept="image/png,image/jpeg,image/webp" class="mt12"></div><div class="actions mt12">${M.btn('GeoJSON','map-export','download','small')}</div>`:`<p class="dev-note">${p.capturedAt?'Снят '+M.date(p.capturedAt)+'. Опубликован '+M.date(p.publishedAt)+'.':'Исследованный участок твоего тестового мира. Источник: Снимок мира, дневной слой. Не полный рендер сервера.'}</p>`}</aside><div class="map-canvas" id="map-canvas"><svg class="map-svg" id="map-svg" viewBox="-512 -512 1024 1024" tabindex="0" aria-label="Карта. Перемещение мышью, масштаб кнопками." role="img"><image id="map-backdrop" x="-512" y="-512" width="1024" height="1024" preserveAspectRatio="none"></image><g id="zone-layer"></g><g id="marker-layer"></g><g id="drawing-layer"></g></svg>${edit?`<div class="map-toolbar">${M.iconBtn('move','Перемещение','map-tool-move')}${M.iconBtn('pin','Добавить метку','map-tool-marker')}${M.iconBtn('polygon','Нарисовать зону','map-tool-zone')}${M.iconBtn('undo','Отменить последнее изменение','map-undo')}</div>`:''}<div class="map-controls">${M.iconBtn('plus','Приблизить','map-zoom-in')}${M.iconBtn('minus','Отдалить','map-zoom-out')}${M.iconBtn('crosshair','Показать всю карту','map-home')}${M.iconBtn('fullscreen','Полный экран','map-fullscreen')}</div><div class="map-instruction hidden" id="map-instruction"></div><div class="coords" id="map-coords">X — · Z — <span class="quiet">/ XZ мира</span></div><div class="map-credit" id="map-credit"></div></div></div>`;}
M.renderers.map=()=>`<div class="map-page">${markup(false)}</div>`;
let showMarkers=true,showZones=true;
function list(){const data=model(),root=document.getElementById('map-list');if(!root)return;const rows=[...data.markers.filter(x=>editor||x.visible).map(x=>({...x,kind:'marker'})),...data.zones.filter(x=>editor||x.visible).map(x=>({...x,kind:'zone'}))];root.innerHTML=rows.length?rows.map(x=>`<button class="map-marker-row ${selected?.id===x.id?'selected':''}" data-action="map-select" data-id="${esc(x.id)}" data-kind="${x.kind}">${icon(x.kind==='zone'?'polygon':x.type==='shop'?'bag':'pin')}<div><strong>${esc(x.name)}</strong><small>${x.kind==='zone'?'Территория':`X ${Math.round(x.x)} · Z ${Math.round(x.z)}`}${!x.visible?' · скрыта':''}</small></div></button>`).join(''):'<p class="hint">Опубликованных объектов пока нет.</p>';}
function svgEl(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;}
function paint(){const svg=document.getElementById('map-svg');if(!svg)return;const data=model();const im=document.getElementById('map-backdrop');im.setAttribute('href',data.image||M.asset('assets/img/map-world.webp'));document.getElementById('map-credit').textContent=data.image?'Загруженный снимок · проверь привязку координат':'Снимок мира · локальный тестовый мир CopiMine';svg.setAttribute('viewBox',`${view.x} ${view.y} ${view.w} ${view.h}`);const z=document.getElementById('zone-layer'),mk=document.getElementById('marker-layer'),dr=document.getElementById('drawing-layer');z.replaceChildren();mk.replaceChildren();dr.replaceChildren();const scale=view.w/Math.max(svg.clientWidth,300),font=12*scale;
if(showZones)for(const a of data.zones.filter(a=>editor||a.visible)){const color=colors[a.color]||colors.green;const poly=svgEl('polygon',{points:a.points.map(p=>p.join(',')).join(' '),fill:color,'fill-opacity':a.visible?'.17':'.06',stroke:color,'stroke-dasharray':a.visible?'none':'8 5',class:'map-zone','data-object':a.id,'data-kind':'zone','aria-label':a.name});z.append(poly);const c=a.points.reduce((s,p)=>[s[0]+p[0]/a.points.length,s[1]+p[1]/a.points.length],[0,0]);const t=svgEl('text',{x:c[0],y:c[1],'text-anchor':'middle',fill:'#f5fff2','font-size':font,'font-weight':650,'paint-order':'stroke',stroke:'#112c1a','stroke-width':5*scale,'data-object':a.id,'data-kind':'zone'},a.name);z.append(t);if(editor&&selected?.id===a.id)a.points.forEach((p,i)=>z.append(svgEl('circle',{cx:p[0],cy:p[1],r:7*scale,fill:color,stroke:'#09110b','stroke-width':2*scale,'data-vertex':i,'data-object':a.id,'data-kind':'zone',style:'cursor:move'})));}
if(showMarkers)for(const a of data.markers.filter(a=>editor||a.visible)){const color=colors[a.color]||colors.green;const g=svgEl('g',{'data-object':a.id,'data-kind':'marker',transform:`translate(${a.x} ${a.z})`,style:'cursor:pointer',opacity:a.visible?1:.5});g.append(svgEl('circle',{r:17*scale,fill:'#102118',stroke:color,'stroke-width':2*scale}));g.append(svgEl('circle',{r:5*scale,fill:color}));const name=svgEl('text',{x:24*scale,y:4*scale,fill:'#f5fff1','font-size':font,'font-weight':650,stroke:'#102118','stroke-width':5*scale,'paint-order':'stroke'},a.name);g.append(name);mk.append(g);}
if(points.length){dr.append(svgEl('polyline',{points:points.map(p=>p.join(',')).join(' '),fill:points.length>=3?colors.green:'none','fill-opacity':.16,stroke:colors.green,'stroke-width':2,'vector-effect':'non-scaling-stroke','stroke-dasharray':'6 4'}));for(const p of points)dr.append(svgEl('circle',{cx:p[0],cy:p[1],r:5*scale,fill:colors.green}));}
list();window.CMV4?.attachLocalTiles?.();}
function setTool(t){tool=t;points=[];selected=null;inspector();updateTool();paint();}
function updateTool(){const svg=document.getElementById('map-svg');if(!svg)return;svg.classList.toggle('drawing',tool!=='move');document.querySelectorAll('.map-toolbar button').forEach(b=>b.classList.toggle('active',b.dataset.action==='map-tool-'+tool));const hint=document.getElementById('map-instruction');hint.classList.toggle('hidden',tool==='move');hint.innerHTML=tool==='marker'?'Нажми на карту, чтобы поставить метку. Esc — отмена.':tool==='zone'?`Отметь границы территории. ${points.length} точек. ${points.length>=3?'<button class="text-link" data-action="map-finish">Завершить</button>':''} <span class="quiet">Enter — готово · Esc — отмена</span>`:'';}
function inspector(){const root=document.getElementById('map-inspector');if(!root)return;const a=selected?(selected.kind==='marker'?model().markers:model().zones).find(x=>x.id===selected.id):null;if(!a){root.innerHTML='';return;}if(!editor){root.innerHTML=`<div class="map-inspector"><h3>${esc(a.name)}</h3><p class="mt12">${esc(a.description||'Публичный ориентир на карте.')}</p></div>`;return;}root.innerHTML=`<form class="map-inspector" data-form="map-object"><input type="hidden" name="id" value="${esc(a.id)}"><input type="hidden" name="kind" value="${selected.kind}"><label class="field">Название<input name="name" value="${esc(a.name)}" maxlength="55" required></label><label class="field">Описание<textarea name="description" rows="2" maxlength="300">${esc(a.description||'')}</textarea></label>${selected.kind==='marker'?`<div class="field-row"><label class="field">X<input type="number" name="x" value="${a.x}" min="-512" max="511" required></label><label class="field">Z<input type="number" name="z" value="${a.z}" min="-512" max="511" required></label></div><label class="field">Тип<select name="type"><option value="pin" ${a.type==='pin'?'selected':''}>Место</option><option value="shop" ${a.type==='shop'?'selected':''}>Торговля</option></select></label>`:'<p class="hint mb">Тяни круглые точки на карте, чтобы изменить границы.</p>'}<label class="field">Цвет<select name="color">${Object.keys(colors).map(k=>`<option value="${k}" ${a.color===k?'selected':''}>${{green:'Зелёный',blue:'Голубой',amber:'Песочный'}[k]}</option>`).join('')}</select></label><label class="radio-line"><input type="checkbox" name="visible" ${a.visible?'checked':''}>Показывать после публикации</label><div class="form-error" role="alert"></div><div class="actions"><button type="submit" class="btn primary small">Сохранить</button>${M.iconBtn('trash','Удалить объект','map-delete')}</div></form>`;}
M.forms['map-object']=(f,d)=>{const list=d.get('kind')==='marker'?M.state.markers:M.state.zones,a=list.find(x=>x.id===d.get('id'));if(!a)throw Error('Объект не найден.');if(d.get('kind')==='marker'&&(!Number.isFinite(Number(d.get('x')))||!Number.isFinite(Number(d.get('z')))||Number(d.get('x'))< -512||Number(d.get('x'))>511||Number(d.get('z'))< -512||Number(d.get('z'))>511))throw Error('Координаты за пределами снимка.');checkpoint();a.name=String(d.get('name')).trim();if(!a.name)throw Error('Добавь название.');a.description=String(d.get('description')||'').trim();a.color=d.get('color');a.visible=d.has('visible');if(d.get('kind')==='marker'){a.x=Number(d.get('x'));a.z=Number(d.get('z'));a.type=d.get('type');}M.audit('Изменение карты',a.name,'Черновик');paint();M.toast('Черновик сохранён. Публичная карта не изменилась.');};
function pos(e){const s=document.getElementById('map-svg'),p=s.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(s.getScreenCTM().inverse());return [Math.round(Math.max(-512,Math.min(511,q.x))),Math.round(Math.max(-512,Math.min(511,q.y)))];}
function init(edit=false){editor=edit;tool='move';points=[];selected=null;showMarkers=showZones=true;view={x:-512,y:-512,w:1024,h:1024};const svg=document.getElementById('map-svg');if(!svg)return;const ratio=svg.clientWidth/svg.clientHeight;view.w=Math.max(1024,1024*ratio);view.h=view.w/ratio;view.x=-512+(1024-view.w)/2;view.y=-512+(1024-view.h)/2;paint();updateTool();svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;const object=e.target.closest('[data-object]');drag={startX:e.clientX,startY:e.clientY,view:{...view},moved:false,obj:object?.dataset.object,kind:object?.dataset.kind,vertex:e.target.dataset.vertex};if(editor&&drag.obj&&tool==='move')checkpoint();svg.setPointerCapture(e.pointerId);});svg.addEventListener('pointermove',e=>{const [x,z]=pos(e);document.getElementById('map-coords').innerHTML=`X ${x} · Z ${z} <span class="quiet">/ XZ мира</span>`;if(!drag)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(!drag.moved||tool!=='move')return;if(editor&&drag.obj){if(drag.kind==='marker'){const a=M.state.markers.find(a=>a.id===drag.obj);a.x=x;a.z=z;}else if(drag.vertex!==undefined){const a=M.state.zones.find(a=>a.id===drag.obj);a.points[Number(drag.vertex)]=[x,z];}else{const factor=drag.view.w/svg.getBoundingClientRect().width;view.x=drag.view.x-dx*factor;view.y=drag.view.y-dy*factor;}}else{const factor=Math.max(drag.view.w/svg.clientWidth,drag.view.h/svg.clientHeight);view.x=drag.view.x-dx*factor;view.y=drag.view.y-dy*factor;}paint();});svg.addEventListener('pointerup',e=>{if(!drag)return;const d=drag;drag=null;const p=pos(e);if(d.moved){if(editor&&d.obj){if(d.kind==='zone'&&d.vertex!==undefined){const a=M.state.zones.find(a=>a.id===d.obj);if(!C.validPolygon(a.points)){if(lastUndo){M.state.zones=lastUndo.zones;M.state.markers=lastUndo.markers;}paint();M.toast('Граница пересекает сама себя. Изменение отменено.',true);return;}}M.save();selected={id:d.obj,kind:d.kind};inspector();}return;}if(tool==='marker'&&editor){checkpoint();const a={id:'marker-'+Date.now(),name:'Новая метка',description:'',x:p[0],z:p[1],visible:true,color:'green',type:'pin'};M.state.markers.push(a);M.audit('Новая метка',a.name,'Черновик');selected={id:a.id,kind:'marker'};tool='move';updateTool();paint();inspector();}else if(tool==='zone'&&editor){points.push(p);updateTool();paint();}else if(d.obj){selected={id:d.obj,kind:d.kind};paint();inspector();}else{selected=null;inspector();paint();}});svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.17:1/1.17);},{passive:false});svg.addEventListener('keydown',e=>{if(e.key==='Escape')setTool('move');if(e.key==='Enter'&&tool==='zone')finish();if(e.key==='+')zoom(.8);if(e.key==='-')zoom(1.25);});const file=document.getElementById('map-image-file');if(file)file.addEventListener('change',async()=>{const f=file.files[0];if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>2*1024*1024){M.toast('Нужен PNG, JPEG или WebP до 2 МБ.',true);return;}const r=new FileReader();r.onload=()=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=1024;const ctx=canvas.getContext('2d');ctx.fillStyle='#10261e';ctx.fillRect(0,0,1024,1024);const k=Math.min(1024/image.width,1024/image.height);ctx.drawImage(image,(1024-image.width*k)/2,(1024-image.height*k)/2,image.width*k,image.height*k);M.state.mapImage=canvas.toDataURL('image/webp',.86);M.audit('Импорт карты',f.name,'Черновик');paint();M.toast('Изображение загружено в черновик. Проверь границы X/Z в настройках источника.');};image.onerror=()=>M.toast('Не удалось прочитать изображение.',true);image.src=r.result;};r.readAsDataURL(f);});}
function zoom(k){const w=Math.min(6000,Math.max(64,view.w*k)),r=w/view.w;view.x+=(view.w-w)/2;view.y+=(view.h-view.h*r)/2;view.w=w;view.h*=r;paint();}
function finish(){if(!C.validPolygon(points)){M.toast('Нужны хотя бы три точки без пересечений.',true);return;}checkpoint();const a={id:'zone-'+Date.now(),name:'Новая территория',description:'',points:M.clone(points),visible:true,color:'green'};M.state.zones.push(a);M.audit('Новая зона',a.name,'Черновик');points=[];selected={id:a.id,kind:'zone'};tool='move';updateTool();paint();inspector();}
function publish(silent=false){const p=M.state.mapPending;if(!p){if(!silent)M.toast('Сначала поставь снимок в очередь.');return false;}if(!C.eligibleSnapshot([p],now(),12)||now()<due(p)){if(!silent)M.toast('Снимок ещё свежий. Публикация после '+M.date(due(p))+'.',true);return false;}M.state.mapPublished={...M.clone(p),markers:p.markers.filter(a=>a.visible),zones:p.zones.filter(a=>a.visible),publishedAt:now()};M.state.mapPending=null;M.audit('Публикация карты',p.id,'Снимок старше 12 часов');if(!silent){M.render();M.toast('Опубликована локальная копия карты.');}return true;}
const H=M.handlers;
H['map-add']=H['map-tool-marker']=()=>setTool('marker');H['map-tool-move']=()=>setTool('move');H['map-tool-zone']=()=>setTool('zone');H['map-finish']=finish;H['map-zoom-in']=()=>zoom(.78);H['map-zoom-out']=()=>zoom(1.28);H['map-home']=()=>{view={x:-512,y:-512,w:1024,h:1024};paint();};
H['map-select']=b=>{selected={id:b.dataset.id,kind:b.dataset.kind};tool='move';points=[];updateTool();paint();inspector();};H['map-list-all']=()=>{selected=null;inspector();paint();};
H['map-delete']=()=>{if(!selected)return;M.openModal('Удалить объект карты?',`<p>Изменится только черновик. Опубликованная версия останется прежней до следующей публикации.</p><div class="actions mt">${M.btn('Отмена','close')}${M.btn('Удалить','map-delete-confirm','trash','danger-btn')}</div>`);};
H['map-delete-confirm']=()=>{checkpoint();M.state.markers=M.state.markers.filter(a=>a.id!==selected.id);M.state.zones=M.state.zones.filter(a=>a.id!==selected.id);M.audit('Удаление с карты',selected.id,'Черновик');selected=null;M.closeModal();paint();inspector();};
H['map-undo']=()=>{if(points.length){points.pop();updateTool();paint();return;}if(!lastUndo){M.toast('Нет изменений для отмены.');return;}M.state.markers=lastUndo.markers;M.state.zones=lastUndo.zones;lastUndo=null;selected=null;M.save();paint();inspector();M.toast('Последнее изменение черновика отменено.');};
H['map-toggle-markers']=b=>{showMarkers=!showMarkers;b.classList.toggle('on',showMarkers);b.setAttribute('aria-checked',showMarkers);paint();};H['map-toggle-zones']=b=>{showZones=!showZones;b.classList.toggle('on',showZones);b.setAttribute('aria-checked',showZones);paint();};
H['map-queue']=()=>{M.state.mapPending={id:'snapshot-'+Date.now(),capturedAt:now(),ready:true,markers:M.clone(M.state.markers),zones:M.clone(M.state.zones),image:M.state.mapImage};M.audit('Карта в очереди',M.state.mapPending.id,'Публикация после '+nextPublication());M.render();M.toast('Снимок зафиксирован. Новые правки не попадут в эту копию.');};
H['map-publish']=()=>publish();H['map-advance']=()=>{M.state.mapTimeOffset=(M.state.mapTimeOffset||0)+12*C.HOUR;M.save();if(!publish(true)){M.toast('Демонстрационное время сдвинуто на 12 часов. Следующая публикация: '+nextPublication());}else M.toast('Проверка задержки пройдена. Снимок опубликован.');M.render();};
H['map-export']=()=>{const d=model();const features=[...d.markers.map(a=>({type:'Feature',geometry:{type:'Point',coordinates:[a.x,a.z]},properties:{name:a.name,description:a.description,visible:a.visible,color:a.color}})),...d.zones.map(a=>({type:'Feature',geometry:{type:'Polygon',coordinates:[[...a.points,a.points[0]]]},properties:{name:a.name,visible:a.visible,color:a.color}}))];M.downloadFile('copimine-map-draft.geojson',JSON.stringify({type:'FeatureCollection',note:'Minecraft local X/Z coordinates, not geographic longitude/latitude. Origin from Снимок мира region tiles; 1 px = 1 block.',features},null,2));};
H['map-fullscreen']=()=>{const c=document.getElementById('map-canvas');if(document.fullscreenElement)document.exitFullscreen();else if(c.requestFullscreen)c.requestFullscreen().catch(()=>M.toast('Полный экран недоступен в этом режиме.'));};
window.CMMap={markup,init,publish};
setInterval(()=>{if(publish(true)&&(M.UI.page==='map'||(M.UI.page==='admin'&&M.UI.tab==='world')))M.render();},30000);
})();

/* assets/js/admin.js *//* Consolidated administration. Every mutation stays inside the local design sandbox. */
(function(){
'use strict';
const M=window.CM,C=window.CMCore,e=M.esc;
const sections=[['overview','Обзор','grid'],['players','Игроки','users'],['moderation','Модерация','shield'],['shop','Магазин','bag'],['finance','Финансы','wallet'],['world','Мир и карта','map'],['content','Сайт и файлы','file'],['access','Команда и доступ','lock'],['system','Система','server']];
const notes={overview:'Главное, что требует внимания команды.',players:'Профили, покупки и ограничения в одном месте.',moderation:'Обращения, проверка действий и решения команды.',shop:'Один каталог. Отдельные валюты. Прозрачная выдача.',finance:'Донат, игровые счета и история операций.',world:'Карта, публичные ориентиры и события сервера.',content:'Тексты, ссылки и файлы для игроков.',access:'Права команды и журнал изменений.',system:'Интеграции и состояние локального прототипа.'};
let sub={},search='';
const s=()=>M.state;
function tabs(key,values){const active=sub[key]||values[0][0];return `<div class="tabs">${values.map(([id,name])=>`<button class="${id===active?'active':''}" data-action="admin-sub" data-section="${key}" data-tab="${id}">${name}</button>`).join('')}</div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="muted" style="padding:32px">Записей пока нет.</td></tr>`}</tbody></table></div>`;}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h3>${title}</h3>${action}</div>${body}</section>`;}
function metric(label,value,small,ic){return `<div class="stat"><div class="label">${icon(ic)}${label}</div><strong class="value">${value}</strong><small>${small}</small></div>`;}
const tableSearch=(placeholder,value='',id='admin-list-search')=>`<div class="input-wrap search-box">${icon('search')}<input id="${id}" type="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${e(value)}" autocomplete="off"></div>`;
function overview(){const open=s().tickets.filter(x=>x.status!=='closed'),queue=s().orders.filter(x=>x.status==='queued');const activity=s().audit.length?s().audit.slice(0,5):[{action:'Проверка выдачи',target:'DEMO-1043',detail:'Демонстрационный заказ',at:s().orders[1].at},{action:'Обращение о постройке',target:'DEMO-021',detail:'Ожидает рассмотрения',at:s().tickets[0].at}];return `<div class="stat-row">${metric('Обращения',open.length,'Ожидают ответа','chat')}${metric('Очередь выдачи',queue.length,'Тестовые заказы','package')}${metric('Товары',s().catalog.filter(p=>p.enabled).length,'Опубликованы в каталоге','bag')}${metric('Карта',s().mapPending?'В очереди':'12 ч','Интервал публикации','clock')}</div><div class="admin-grid"><div>${panel('Требует внимания',open.map(t=>`<div class="list-row">${icon(t.priority==='high'?'alert':'chat')}<div><strong>${e(t.title)}</strong><small>${e(t.player)} · ${e(t.id)}</small></div>${M.status(t.status)}${M.iconBtn('chevron-right','Открыть обращение','ticket-detail',`data-id="${t.id}"`)}</div>`).join('')||M.empty('Всё разобрано','Новые обращения появятся здесь.','check'),M.link('Все обращения','#admin/moderation','arrow-up-right','small'))}<div class="mt">${panel('Последние заказы',table(['Заказ','Предмет','Сумма','Статус'],s().orders.slice(0,4).map(o=>[e(o.id),`<div class="row"><img src="${M.asset(M.item(o.item)?.image)}" alt=""><strong>${e(o.name)}</strong></div>`,M.money(o.total,o.currency),M.status(o.status)])),M.link('К выдаче','#admin/shop','arrow-right','small'))}</div></div><div>${panel('Последние действия',`<div class="timeline">${activity.map(a=>`<div class="timeline-row"><small>${M.date(a.at)}</small><strong>${e(a.action)}</strong><p>${e(a.target)}${a.detail?' · '+e(a.detail):''}</p></div>`).join('')}</div>`)}<div class="mt">${panel('Подключения',[['Minecraft','Команды не отправляются'],['Платежи','Только локальный сценарий'],['Карта','Снимок из твоего референса']].map(([n,t])=>`<div class="service-row"><div><strong>${n}</strong><small>${t}</small></div>${M.pill('Не подключено')}</div>`).join(''))}</div></div></div>`;}
function players(){return `<div class="table-toolbar">${tableSearch('Найти игрока',search)}<span class="hint push-right">${s().players.length} локальных аккаунта</span></div><div id="admin-table">${playerTable()}</div><p class="dev-note">Тестовые профили созданы для проверки сценариев. Это не список игроков рабочего сервера.</p>`;}
function playerTable(){const players=s().players.filter(p=>(p.name+' '+p.role).toLowerCase().includes(search.toLowerCase()));return table(['Игрок','Роль','AR','CM','Доступ',''],players.map(p=>[`<div class="row"><span class="avatar small-avatar">${e(p.name.slice(0,2).toUpperCase())}</span><div><strong>${e(p.name)}</strong><small>${e(p.id)}</small></div></div>`,e(p.role),p.AR.toLocaleString('ru-RU'),p.CM.toLocaleString('ru-RU'),M.status(p.status),M.btn('Профиль','admin-player','','small',`data-id="${p.id}"`)]));}
function moderation(){const active=sub.moderation||'tickets';let body='';if(active==='tickets'){body=table(['Обращение','Игрок','Категория','Статус',''],s().tickets.map(t=>[`<strong>${e(t.title)}</strong><small>${e(t.id)} · ${M.date(t.at)}</small>`,e(t.player),e(t.type),M.status(t.status),M.btn('Разобрать','ticket-detail','','small',`data-id="${t.id}"`)]));}else if(active==='incidents'){body=`<div class="admin-grid">${panel('Проверка постройки',`<p>Начни с обращения и истории действий. Затем выбери игрока, участок и время.</p><form data-form="investigate" class="mt"><label class="field">Игрок<select name="player">${s().players.filter(p=>p.role==='Игрок').map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></label><div class="field-row"><label class="field">Радиус, блоков<input name="radius" type="number" min="1" max="50" value="15" required></label><label class="field">Период<select name="period"><option>Последние 10 минут</option><option>Последний час</option><option>Последние сутки</option></select></label></div><p class="hint mb">История CoreProtect не подключена. Кнопка показывает последовательность проверки на тестовом случае.</p><button class="btn primary" type="submit">${icon('search')}Проверить тестовый случай</button></form>`)}${panel('Как принимается решение',`<div class="timeline"><div class="timeline-row"><strong>Собрать факты</strong><p>Жалоба, координаты, время и история блоков.</p></div><div class="timeline-row"><strong>Проверить масштаб</strong><p>Не включать в откат чужие действия и служебные блоки.</p></div><div class="timeline-row"><strong>Подтвердить решение</strong><p>Откат и блокировка — отдельные действия с причиной.</p></div><div class="timeline-row"><strong>Сохранить результат</strong><p>Ссылка на обращение и запись в журнале команды.</p></div></div>`)}</div>`;}else if(active==='sanctions'){body=table(['Игрок','Основание','Срок','Статус',''],s().players.filter(p=>p.ban).map(p=>[e(p.name),e(p.ban.reason),e(p.ban.duration),M.status(p.status),M.btn('Снять блокировку','admin-unban','','small',`data-id="${p.id}"`)]));}else{body=panel('Сигналы античита',`<div class="notice">${icon('shield')}GrimAC пока не подключён к прототипу. Отсутствие сигналов здесь не означает отсутствие нарушений.</div><p class="mt">В рабочей версии сигнал попадёт в дело игрока вместе с контекстом. Сам по себе он не должен приводить к безусловному бану.</p>`);}return tabs('moderation',[['tickets','Обращения'],['incidents','Расследования'],['sanctions','Блокировки'],['anticheat','Античит']])+body;}
function shop(){const active=sub.shop||'catalog';let body='';if(active==='catalog'){body=`<div class="table-toolbar">${tableSearch('Найти предмет',search)}<span class="hint push-right">Цены из каталога проекта</span></div><div id="admin-table">${catalogTable()}</div>`;}else{body=table(['Заказ / игрок','Предмет','Стоимость','Статус',''],s().orders.map(o=>[`<strong>${e(o.id)}</strong><small>${e(o.player)}</small>`,`<div class="row"><img src="${M.asset(M.item(o.item)?.image)}" alt=""><div>${e(o.name)}<small>${o.qty} шт.</small></div></div>`,M.money(o.total,o.currency),M.status(o.status),o.status==='queued'?M.btn('Проверить выдачу','admin-delivery','','small',`data-id="${o.id}"`):M.btn('Детали','order-detail','','small',`data-id="${o.id}"`)]))+`<p class="dev-note">Статус меняется только в браузере. Команды выдачи в Minecraft не отправляются.</p>`;}return tabs('shop',[['catalog','Каталог'],['orders','Заказы и выдача']])+body;}
function catalogTable(){return table(['Предмет','Категория','Цена','Публикация',''],s().catalog.filter(p=>(p.name+' '+p.category).toLowerCase().includes(search.toLowerCase())).map(p=>[`<div class="row"><img src="${M.asset(p.image)}" alt=""><div><strong>${e(p.name)}</strong><small>${p.ownerBound?'Привязан к владельцу':'Обычный игровой предмет'}</small></div></div>`,e(p.category),`<strong>${M.money(p.price,p.currency)}</strong>`,M.pill(p.enabled?'В магазине':'Скрыт',p.enabled?'green':''),M.iconBtn('edit','Изменить '+e(p.name),'admin-product',`data-id="${p.id}"`)]));}
function finance(){const active=sub.finance||'accounts';let body='';if(active==='accounts'){body=table(['Игрок','Игровой счёт','Донатный счёт',''],s().players.filter(p=>p.role==='Игрок').map(p=>[e(p.name),M.money(p.AR,'AR'),M.money(p.CM,'CM'),M.btn('Операция','admin-money','','small',`data-id="${p.id}"`)]));}else if(active==='ledger'){body=table(['Время','Игрок','Сумма','Основание'],s().ledger.map(l=>[M.date(l.at),e(l.player),`<span class="${l.amount<0?'muted':'green-text'}">${l.amount>0?'+':''}${M.money(l.amount,l.currency)}</span>`,e(l.reason)]));}else{body=panel('Приём платежей',`<div class="notice">${icon('lock')}Платёжный провайдер не подключён. Прототип не списывает реальные деньги.</div><p class="mt">В рабочей версии пополнения подтверждаются только сервером платёжной системы. Возвраты и спорные платежи попадут в отдельную очередь.</p><div class="actions mt">${M.btn('Проверить тестовое пополнение','admin-test-topup','plus','primary')}</div>`);}return tabs('finance',[['accounts','Счета'],['ledger','Операции'],['payments','Платежи']])+body;}
function world(){const active=sub.world||'map';if(active==='map')return tabs('world',[['map','Карта и зоны'],['events','События'],['elections','Выборы']])+`<div class="map-admin-wrap">${CMMap.markup(true)}</div><p class="dev-note">Интервал и задержка — независимые ограничения. Черновик не попадает на публичную карту автоматически.</p>`;if(active==='events')return tabs('world',[['map','Карта и зоны'],['events','События'],['elections','Выборы']])+panel('Анонсы событий',`<p>Публичный анонс хранится отдельно от игровых механик. Название, дата, короткое описание и статус.</p><div class="actions mt">${M.btn('Новый анонс','admin-new-event','plus','primary')}</div>${table(['Название','Дата','Статус',''],(s().events||[]).map(x=>[e(x.name),e(x.date),M.pill(x.published?'Опубликован':'Черновик',x.published?'green':''),M.btn(x.published?'Скрыть':'Опубликовать','admin-event-toggle','','small',`data-id="${x.id}"`)]))}`);return tabs('world',[['map','Карта и зоны'],['events','События'],['elections','Выборы']])+panel('Выборы',`<div class="notice">${icon('file')}Игровое голосование не подключено. Результаты и кандидаты не подменяются тестовыми цифрами.</div><p class="mt">Здесь будет одна кампания с вкладками «Кандидаты», «Этапы», «Результаты» и «Решения ЦИК». Казна остаётся в финансах, а служебные точки — на карте.</p>`);}
function content(){const active=sub.content||'copy';let body='';if(active==='copy'){body=`<div class="admin-grid">${panel('Главная страница',`<form data-form="site-copy"><label class="field">Заголовок<textarea name="headline" rows="3" maxlength="80" required>${e(s().config.headline)}</textarea></label><label class="field">Описание<textarea name="description" rows="3" maxlength="220" required>${e(s().config.description)}</textarea></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary">Сохранить текст</button></form>`)}${panel('Логотип и изображение',`<div class="brand-proof"><img src="${M.asset('assets/img/logo.webp')}" alt="Отдельный логотип CopiMine" style="width:200px;height:auto;margin:12px 0 24px"></div><p>Логотип — самостоятельный файл с прозрачным фоном. Игровое изображение используется отдельно.</p><img src="${M.asset('assets/img/world.webp')}" alt="Игровой кадр" class="mt" style="width:100%;border-radius:8px"><p class="hint mt12">Материалы из твоего архива. Сгенерированных иллюстраций нет.</p>`)}</div>`;}else if(active==='discord'){body=panel('Discord',`<form data-form="discord-config"><label class="field">ID сервера<input value="${e(s().config.discordGuild)}" readonly></label><label class="field">Постоянное приглашение<input name="invite" type="url" value="${e(s().config.discordInvite)}" placeholder="https://discord.gg/…"></label><p class="hint mb">ID сервера не является приглашением. Без него кнопка откроет Discord только для действующих участников.</p><div class="form-error" role="alert"></div><div class="actions"><button type="submit" class="btn primary">Сохранить</button>${M.btn('Проверить баннер','discord-widget','eye')}</div></form>`);}else{body=`<div class="admin-grid">${panel('Архив модов',releaseForm('mods','modUrl','ZIP: CopiMineClient, голосовой чат и необходимые зависимости.','application/zip,.zip'))}${panel('Лаунчер (необязательно)',releaseForm('launcher','launcherUrl','Автообновление сборки, проверка файлов и отдельная папка игры.','.exe,.msi,.zip,.AppImage,.dmg'))}</div><div class="notice mt">${icon('info')}В присланном RAR найдены графические материалы, а не готовый установщик или совместимый архив модов. Подключи настоящий релиз ссылкой или локальным файлом.</div>`;}return tabs('content',[['copy','Тексты и оформление'],['discord','Discord'],['downloads','Загрузки']])+body;}
function releaseForm(kind,key,desc,accept){return `<p class="mb">${desc}</p><form data-form="release-link"><input type="hidden" name="key" value="${key}"><label class="field">Ссылка на релиз<input name="url" type="url" value="${e(s().config[key])}" placeholder="https://…"></label><div class="form-error" role="alert"></div><button type="submit" class="btn primary small">Сохранить ссылку</button></form><div class="upload-tile mt"><label for="release-${kind}">Или выбрать файл для проверки кнопки</label><input id="release-${kind}" type="file" accept="${accept}" data-release="${kind}" class="mt12"><p id="release-name-${kind}" class="hint mt12">${window.CM_RELEASE_FILES?.[kind]?.name?e(window.CM_RELEASE_FILES[kind].name):'Файл не выбран'}</p></div><p class="hint mt12">Локальный файл доступен до перезагрузки страницы. Ссылка сохраняется.</p>`;}
function access(){const active=sub.access||'team';let body='';if(active==='team'){body=table(['Участник','Роль','Доступ',''],s().players.filter(p=>p.role!=='Игрок').map(p=>[e(p.name),e(p.role),M.status(p.status),M.btn('Права','admin-role','','small',`data-id="${p.id}"`)]))+`<div class="actions mt">${M.btn('Назначить роль','admin-role','','primary')}</div><p class="dev-note">Владелец, администратор, модератор и редактор. В HTML переключение ролей — демонстрация интерфейса, не защита.</p>`;}else if(active==='audit'){body=auditTable();}else{body=panel('Сессии команды',`<div class="notice">${icon('lock')}Настоящих серверных сессий в статическом прототипе нет.</div><div class="service-row"><div><strong>Этот браузер</strong><small>Локальное хранилище · не cookie-авторизация</small></div>${M.pill('Демо','green')}</div><p class="mt">Для рабочей версии: отдельная сессия администратора, MFA, повторное подтверждение опасных операций и отзыв доступа на сервере.</p>`);}return tabs('access',[['team','Команда'],['sessions','Сессии'],['audit','Журнал действий']])+body;}
function auditTable(){return table(['Время','Кто','Действие','Объект / подробности'],s().audit.map(a=>[M.date(a.at),e(a.actor),e(a.action),`<span class="break">${e(a.target)}</span><small class="break">${e(a.detail)}</small>`]));}
function system(){const active=sub.system||'connections';let body='';if(active==='connections'){body=`<div class="admin-grid">${panel('Источники данных',[['Каталог предметов','12 реальных записей из репозитория','Загружен'],['Локальная база','Тестовые аккаунты, операции и обращения','Работает'],['Minecraft / CoreProtect','Нет соединения с игровым сервером','Не подключено'],['Платежи','Нет провайдера в дизайн-прототипе','Не подключено'],['Рендер карты','Загружаемый снимок, не мир .mca','Не подключено']].map(([n,d,v])=>`<div class="service-row"><div><strong>${n}</strong><small>${d}</small></div>${M.pill(v,v==='Работает'||v==='Загружен'?'green':'')}</div>`).join(''))}${panel('Границы прототипа',`<p>Показываем реальные состояния интерфейса, но не выдаём демонстрацию за рабочий сервер.</p><div class="steps mt"><div><span class="step-num">01</span><strong>Без команд серверу</strong><p>Баны, выдача и откаты меняют только тестовые записи.</p></div><div><span class="step-num">02</span><strong>Без реальных денег</strong><p>В магазине расходуется тестовый баланс.</p></div></div><div class="actions mt">${M.btn('Проверить локальные данные','admin-diagnose','activity')}</div>`)}</div>`;}else if(active==='backup'){body=panel('Данные прототипа',`<p>Экспортируй свои правки перед новой версией. Сессия и хеши тестовых паролей в экспорт не попадают.</p><div class="actions mt">${M.btn('Экспорт JSON','export','download','primary')}${M.btn('Исходный набор','reset','refresh')}</div><p class="hint mt">Рабочую PostgreSQL-базу нельзя подменять этим файлом. data/prototype.sqlite приложена отдельно для разработки и просмотра схемы.</p>`);}else{body=auditTable();}return tabs('system',[['connections','Подключения'],['backup','Экспорт и резервные копии'],['logs','Локальный журнал']])+body;}
const views={overview,players,moderation,shop,finance,world,content,access,system};
window.CMLegacyAdmin={views,sub,table,panel,sections,setSearch(v){search=v;},playerTable,catalogTable};
M.renderers.admin=(key='overview')=>{if(!views[key])key='overview';const name=sections.find(x=>x[0]===key)[1];return `<div class="admin-shell"><aside class="admin-sidebar"><a class="brand" href="#home" aria-label="На сайт CopiMine"><img class="brand-mark" src="${M.asset('assets/img/icon.webp')}" alt=""><img class="wordmark" src="${M.asset('assets/img/logo.webp')}" alt="CopiMine"></a><div class="label">УПРАВЛЕНИЕ</div><nav class="admin-nav" aria-label="Разделы администрации">${sections.map(([id,n,ic])=>`<a href="#admin/${id}" title="${n}" class="${id===key?'active':''}">${icon(ic)}<span>${n}</span></a>`).join('')}</nav><div class="admin-profile"><div class="avatar">DA</div><div><strong>DemoAdmin</strong><small>Тестовый владелец</small></div></div></aside><div class="admin-main"><header class="admin-top"><div class="breadcrumb"><span>CopiMine</span>${icon('chevron-right')}<strong>${name}</strong></div><div class="row">${M.pill('Локальная среда','green')}${M.link('На сайт','#home','arrow-up-right','small')}</div></header><main class="admin-content" id="view"><div class="admin-heading"><div><h1>${name}</h1><p>${notes[key]}</p></div><div class="actions">${key==='world'?M.link('Публичная карта','#map','eye','small'):key==='shop'?M.link('Открыть магазин','#shop','arrow-up-right','small'):M.btn('Экспорт','export','download','small')}</div></div>${views[key]()}</main></div></div>`;};
window.bindAdmin=(key)=>{const input=document.getElementById('admin-list-search');if(input)input.addEventListener('input',()=>{search=input.value;document.getElementById('admin-table').innerHTML=key==='players'?playerTable():catalogTable();});if(key==='world'&&(!sub.world||sub.world==='map'))CMMap.init(true);document.querySelectorAll('[data-release]').forEach(input=>input.addEventListener('change',()=>{const file=input.files[0];if(!file)return;window.CM_RELEASE_FILES=window.CM_RELEASE_FILES||{};window.CM_RELEASE_FILES[input.dataset.release]=file;document.getElementById('release-name-'+input.dataset.release).textContent=file.name;M.toast('Файл доступен через «Играть» до перезагрузки страницы.');}));};
const H=M.handlers,F=M.forms;
H['admin-sub']=b=>{sub[b.dataset.section]=b.dataset.tab;search='';M.render();};
H['admin-player']=b=>{const p=s().players.find(p=>p.id===b.dataset.id);M.openModal(e(p.name),`<div class="row mb">${M.status(p.status)}${M.pill(p.role)}</div><div class="balance-pair"><div class="balance-cell"><div class="label">AR</div><div class="value">${p.AR}</div></div><div class="balance-cell"><div class="label">CM</div><div class="value">${p.CM}</div></div></div><h3 class="mt">Покупки игрока</h3>${M.orderRows(s().orders.filter(o=>o.player===p.name))||'<p class="hint mt12">Покупок нет.</p>'}<p class="hint mt">Живой инвентарь не загружается. Здесь показаны только покупки в тестовой базе.</p><div class="actions mt">${M.btn('Операция со счётом','admin-money','wallet','',`data-id="${p.id}"`)}${p.status==='banned'?M.btn('Снять блокировку','admin-unban','shield','',`data-id="${p.id}"`):M.btn('Заблокировать','admin-ban','lock','danger-btn',`data-id="${p.id}"`)}</div>`);};
H['admin-ban']=b=>{const p=s().players.find(p=>p.id===b.dataset.id);if(p.role==='Владелец'){M.toast('Владелец не блокируется из обычного профиля.',true);return;}M.openModal('Блокировка '+e(p.name),`<form data-form="ban"><input type="hidden" name="id" value="${p.id}"><label class="field">Причина<textarea name="reason" minlength="5" maxlength="300" required placeholder="Что нарушено и по какому обращению"></textarea></label><label class="field">Срок<select name="duration"><option>1 день</option><option>7 дней</option><option>30 дней</option><option>До пересмотра</option></select></label><label class="radio-line"><input type="checkbox" name="confirmed" required>Факты проверены, игрок выбран правильно</label><p class="hint mb">Это тестовая блокировка. Minecraft не получит команду.</p><div class="form-error" role="alert"></div><button type="submit" class="btn danger-btn wide">Подтвердить блокировку</button></form>`);};
F.ban=(f,d)=>{const p=s().players.find(p=>p.id===d.get('id'));if(!p||p.role==='Владелец'||!d.has('confirmed'))throw Error('Операция недоступна.');p.status='banned';p.ban={reason:String(d.get('reason')).trim(),duration:d.get('duration'),at:Date.now()};M.audit('Тестовая блокировка',p.name,p.ban.reason);M.render();M.toast('Локальный аккаунт заблокирован.');};
H['admin-unban']=b=>{const p=s().players.find(p=>p.id===b.dataset.id);M.openModal('Снять блокировку?',`<p>Аккаунт ${e(p.name)} снова сможет войти в прототип.</p><form class="mt" data-form="unban"><input type="hidden" name="id" value="${p.id}"><label class="field">Причина пересмотра<input name="reason" minlength="5" required></label><button type="submit" class="btn primary">Снять блокировку</button></form>`);};F.unban=(f,d)=>{const p=s().players.find(p=>p.id===d.get('id'));p.status='active';p.ban=null;M.audit('Снятие блокировки',p.name,d.get('reason'));M.render();M.toast('Доступ восстановлен в прототипе.');};
F.investigate=(f,d)=>{const p=s().players.find(p=>p.id===d.get('player'));M.openModal('Проверка тестового случая',`<div class="notice">${icon('info')}Это учебный сценарий, не результат запроса CoreProtect.</div><div class="mt">${table(['Проверка','Выбранное значение'],[['Игрок',e(p.name)],['Радиус',e(d.get('radius'))+' блоков'],['Время',e(d.get('period'))],['Затронутые блоки','Нет данных сервера']])}</div><p class="mt">Без настоящей истории нельзя подтверждать откат. Сначала подключается CoreProtect, затем показываются конкретные изменения.</p><div class="actions mt">${M.btn('К профилю игрока','admin-player','user','',`data-id="${p.id}"`)}${M.btn('Откат недоступен','unavailable','undo','', 'disabled')}</div>`);};
H['admin-product']=b=>{const p=M.item(b.dataset.id);M.openModal('Изменить предмет',`<form data-form="product-edit"><input type="hidden" name="id" value="${p.id}"><div class="row mb"><img src="${M.asset(p.image)}" style="width:58px;height:58px;image-rendering:pixelated" alt="">${M.pill(p.currency)}<p>Исходные свойства и текстура из проекта.</p></div><label class="field">Название<input name="name" value="${e(p.name)}" maxlength="55" required></label><label class="field">Короткое описание<textarea name="description" maxlength="200" required>${e(p.description)}</textarea></label><div class="field-row"><label class="field">Цена, ${p.currency}<input name="price" type="number" min="1" max="1000000" step="1" value="${p.price}" required></label><label class="field">Категория<select name="category">${['Инструменты','Оружие','Снаряжение','Путешествия'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><label class="radio-line"><input name="enabled" type="checkbox" ${p.enabled?'checked':''}>Показывать в магазине</label><div class="form-error" role="alert"></div><button type="submit" class="btn primary wide">Сохранить в прототипе</button></form>`);};
F['product-edit']=(f,d)=>{const p=M.item(d.get('id')),price=Number(d.get('price'));if(!p||!Number.isSafeInteger(price)||price<1||price>1e6)throw Error('Проверь цену.');const before=p.price;p.name=String(d.get('name')).trim();p.description=String(d.get('description')).trim();p.price=price;p.category=d.get('category');p.enabled=d.has('enabled');M.audit('Изменение товара',p.name,`${before} → ${price} ${p.currency}`);M.render();M.toast('Каталог обновлён. Корзина пересчитает стоимость.');};
H['admin-delivery']=b=>{const o=s().orders.find(o=>o.id===b.dataset.id);M.openModal('Проверка выдачи',`<p><strong>${e(o.name)}</strong> · ${e(o.player)}</p><p class="mt">В рабочей версии выдачу подтверждает плагин после проверки инвентаря. Здесь можно проверить следующий статус.</p><div class="notice mt">${icon('package')}Minecraft не подключён. Вещь в игре не появится.</div><div class="actions mt">${M.btn('Оставить в очереди','close')}${M.btn('Получен · демо','admin-delivery-confirm','check','primary',`data-id="${o.id}"`)}</div>`);};
H['admin-delivery-confirm']=b=>{const o=s().orders.find(o=>o.id===b.dataset.id);if(o.status!=='queued')return;o.status='delivered';M.audit('Тестовая выдача',o.id,o.player);M.render();M.toast('Заказ отмечен полученным в тестовой базе.');};
H['admin-money']=b=>{const p=s().players.find(p=>p.id===b.dataset.id)||s().players[0];M.openModal('Операция со счётом',`<form data-form="money"><label class="field">Игрок<select name="player">${s().players.filter(p=>p.role==='Игрок').map(a=>`<option value="${a.id}" ${a.id===p.id?'selected':''}>${e(a.name)}</option>`).join('')}</select></label><div class="field-row"><label class="field">Валюта<select name="currency"><option>AR</option><option>CM</option></select></label><label class="field">Изменение<input name="amount" type="number" min="-1000000" max="1000000" step="1" required placeholder="Например: 100 или -50"></label></div><label class="field">Основание<input name="reason" minlength="5" maxlength="150" required placeholder="Почему меняется баланс"></label><label class="radio-line"><input type="checkbox" required>Проверены игрок, валюта и сумма</label><div class="form-error" role="alert"></div><button type="submit" class="btn primary wide">Провести тестовую операцию</button></form>`);};
F.money=(f,d)=>{const p=s().players.find(p=>p.id===d.get('player')),currency=d.get('currency'),n=Number(d.get('amount'));if(!p||!['AR','CM'].includes(currency)||!Number.isSafeInteger(n)||n===0||Math.abs(n)>1e6||p[currency]+n<0)throw Error('Недопустимая сумма или недостаточно средств.');p[currency]+=n;const reason=String(d.get('reason')).trim();s().ledger.unshift({id:'ADJ-'+Date.now(),player:p.name,amount:n,currency,reason,at:Date.now()});M.audit('Корректировка счёта',p.name,M.money(n,currency)+' · '+reason);M.render();M.toast('Тестовая операция проведена и записана в журнал.');};
H['admin-test-topup']=()=>H['admin-money']({dataset:{id:s().players[0].id}});
F['site-copy']=(f,d)=>{s().config.headline=String(d.get('headline')).trim();s().config.description=String(d.get('description')).trim();M.audit('Текст главной','Сайт');M.toast('Текст обновлён. Открой главную, чтобы посмотреть.');};
F['discord-config']=(f,d)=>{const url=String(d.get('invite')).trim();if(url&&(!C.safeUrl(url)||!/^https:\/\/(discord\.gg|discord\.com)\//i.test(url)))throw Error('Используй официальную HTTPS-ссылку Discord.');s().config.discordInvite=url;M.audit('Ссылка Discord','Сайт');M.toast('Приглашение сохранено.');};
F['release-link']=(f,d)=>{const url=String(d.get('url')).trim(),key=d.get('key');if(url&&!C.safeUrl(url))throw Error('Нужна HTTPS-ссылка без логина и пароля.');if(!['modUrl','launcherUrl'].includes(key))throw Error('Неизвестный тип файла.');s().config[key]=url;M.audit('Ссылка на релиз',key);M.toast('Кнопка загрузки обновлена.');};
H['admin-role']=b=>{M.openModal('Роль в команде',`<form data-form="role"><label class="field">Аккаунт<select name="id">${s().players.map(p=>`<option value="${p.id}" ${p.id===b.dataset.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><label class="field">Роль<select name="role"><option>Игрок</option><option>Редактор</option><option>Модератор</option><option>Администратор</option><option>Владелец</option></select></label><label class="field">Причина<input name="reason" minlength="5" required></label><div class="form-error" role="alert"></div><p class="hint mb">Макет назначения прав. В production решение всегда проверяет сервер.</p><button class="btn primary wide" type="submit">Сохранить роль</button></form>`);};
F.role=(f,d)=>{const p=s().players.find(p=>p.id===d.get('id'));if(p.role==='Владелец'&&d.get('role')!=='Владелец'&&s().players.filter(a=>a.role==='Владелец').length<2)throw Error('Нельзя убрать последнего владельца.');p.role=d.get('role');M.audit('Изменение роли',p.name,p.role+' · '+d.get('reason'));M.render();M.toast('Тестовая роль сохранена.');};
H['admin-new-event']=()=>M.openModal('Анонс события',`<form data-form="event"><label class="field">Название<input name="name" maxlength="65" required></label><label class="field">Дата<input name="date" type="date" required></label><label class="field">Описание без спойлеров<textarea name="description" maxlength="250" required></textarea></label><button class="btn primary wide" type="submit">Сохранить черновик</button></form>`);
F.event=(f,d)=>{s().events=s().events||[];s().events.push({id:'event-'+Date.now(),name:String(d.get('name')).trim(),date:d.get('date'),description:String(d.get('description')).trim(),published:false});M.audit('Черновик события',d.get('name'));M.render();M.toast('Анонс сохранён без игровых механик.');};
H['admin-event-toggle']=b=>{const a=s().events.find(a=>a.id===b.dataset.id);a.published=!a.published;M.audit('Публикация анонса',a.name,a.published?'Опубликован':'Скрыт');M.render();};
H['admin-diagnose']=()=>{const bad=s().catalog.filter(p=>!Number.isSafeInteger(p.price)||p.price<1),badZones=s().zones.filter(z=>!C.validPolygon(z.points));M.openModal('Локальная проверка',table(['Проверка','Результат'],[['Цены каталога',bad.length?'Есть ошибки':'12 записей: целые положительные цены'],['Геометрия зон',badZones.length?'Есть ошибки':'Без пересечений'],['Публичный снимок',s().mapPublished?'Отделён от черновика':'Не создан'],['Задержка карты','Минимум 12 часов'],['Источники аккаунтов','Демонстрационные, не production'],['Подключение Minecraft','Отсутствует']])+`<p class="hint mt">Это проверка данных макета, не аудит безопасности сайта.</p>`);};
})();

/* assets/js/domain-v4.js *//* Pure domain rules for the offline UX prototype; not an authorization server. */
(function(root){
'use strict';
const cp=x=>JSON.parse(JSON.stringify(x));
function verifyChallenge(c,code,now){
 if(!c||c.used)return{ok:false,reason:'used'};
 if(now>=c.expiresAt)return{ok:false,reason:'expired'};
 if(c.attempts>=5)return{ok:false,reason:'locked'};
 c.attempts++;
 if(String(code)!==c.code)return{ok:false,reason:c.attempts>=5?'locked':'invalid'};
 c.used=true;return{ok:true};
}
function launcherState(r,now){if(!r)return'missing';if(['used','denied','revoked'].includes(r.status))return r.status;if(now>=r.expiresAt)return'expired';return r.status;}
function confirmPayment(p,a,now){if(!p||p.player!==a.name)throw Error('Получатель платежа не совпадает.');if(p.status==='paid')return false;if(p.status!=='pending'||now>=p.expiresAt)throw Error('Этот платёж уже недоступен. Создай новый.');if(!Number.isSafeInteger(p.amount)||p.amount<1)throw Error('Некорректная сумма.');if(!Number.isSafeInteger(a.CM+p.amount))throw Error('Лимит баланса превышен.');a.CM+=p.amount;p.status='paid';p.paidAt=now;return true;}
function publishPage(p,expected,now){if(p.revision!==expected)throw Error('Запись изменилась. Обнови редактор.');if(!p.draft.title?.trim()||!p.draft.body?.trim())throw Error('Нужны заголовок и текст.');p.history=p.history||[];if(p.published)p.history.unshift({...cp(p.published),at:p.publishedAt,revision:p.publishedRevision});p.published=cp(p.draft);p.publishedAt=now;p.publishedRevision=p.revision;p.status='published';return p;}
function escape(s){return String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));}
function markdown(s){const inline=s=>escape(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');return String(s||'').split(/\n\s*\n/).map(block=>{if(/^### /.test(block))return'<h3>'+inline(block.slice(4))+'</h3>';if(/^## /.test(block))return'<h2>'+inline(block.slice(3))+'</h2>';if(/^# /.test(block))return'<h2>'+inline(block.slice(2))+'</h2>';if(block.split('\n').every(l=>/^[-*] /.test(l)))return'<ul>'+block.split('\n').map(l=>'<li>'+inline(l.slice(2))+'</li>').join('')+'</ul>';return'<p>'+inline(block).replace(/\n/g,'<br>')+'</p>';}).join('');}
function statistics(orders,tickets,payments,from,to){const o=orders.filter(x=>x.at>=from&&x.at<=to&&!['cancelled','refunded'].includes(x.status)),t=tickets.filter(x=>x.at>=from&&x.at<=to),p=payments.filter(x=>x.status==='paid'&&x.paidAt>=from&&x.paidAt<=to);const revenue={AR:0,CM:0};let tops={};for(const r of o){revenue[r.currency]=(revenue[r.currency]||0)+r.total;tops[r.name]=(tops[r.name]||0)+r.qty;}const response=t.filter(x=>x.firstReplyAt>x.at).map(x=>(x.firstReplyAt-x.at)/3600000);return {revenue,count:o.length,paid:p.reduce((a,x)=>a+x.amount,0),tickets:t.length,open:t.filter(x=>x.status!=='closed').length,responseHours:response.length?response.reduce((a,n)=>a+n,0)/response.length:null,tops:Object.entries(tops).sort((a,b)=>b[1]-a[1]),orders:o};}
function series(rows,days,now,value){const day=86400000,end=new Date(now);end.setUTCHours(23,59,59,999);const result=[];for(let i=days-1;i>=0;i--){const hi=end.getTime()-i*day,lo=hi-day+1;const rr=rows.filter(x=>x.at>=lo&&x.at<=hi);result.push({at:hi,value:rr.reduce((a,r)=>a+(value?value(r):1),0)});}return result;}
function safeLocalRoute(path){return typeof path==='string'&&/^(account|cart|donate|launcher-link|settings)(\/[^?#]*)?(\?.*)?$/.test(path)?path:'account';}
const api={verifyChallenge,launcherState,confirmPayment,publishPage,markdown,statistics,series,safeLocalRoute};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.CMDomain=api;
})(globalThis);

