/* assets/js/catalog-v73.js *//* Source-derived catalog, v7.3. Closed definitions are fetched only after admin login.
   The standalone HTML embeds them explicitly for offline UI review, NOT production. */
(function(){
'use strict';
const M=CM,V=CMV4,X=CM6,W=CM5,Q=CMReview,E=M.esc,H=M.handlers,F=M.forms;
const C=window.CM73=window.CM73||{};C.sourceCommit='13e8f2a4bb9baf65136d0f374324b5f7fc8e402f';
let privateRows=[],lastRows=null,lastRole=null,requested='',loading=false,query='',scope='all';
const state=()=>M.state, publicRows=()=>window.CM6_CATALOG_SOURCE||[];
function syncCatalog(){
 const admin=X.canAdmin();if(lastRows===state().catalog&&lastRole===admin)return;
 const supplied=admin&&privateRows.length?privateRows:publicRows();
 const edits=new Map((state().catalog||[]).filter(p=>p.sourceCommit===C.sourceCommit).map(p=>[p.id,p]));
 state().catalog=supplied.map(p=>{const edit=edits.get(p.id);return edit?{...p,...edit,visibility:p.visibility,grantable:p.grantable,sourceType:p.sourceType,provider:p.provider}:M.clone(p);});
 // IDs removed from the verified source are retained only in order history, not offers.
 state().cart=state().cart.filter(x=>state().catalog.some(p=>p.id===x.id&&p.enabled&&p.visibility==='public'));
 for(const p of state().players||[])for(const limit of p.purchaseLimits||[]){delete limit.period;delete limit.expiresAt;}
 lastRows=state().catalog;lastRole=admin;
}
const prevBefore=V.beforeRender;V.beforeRender=function(){prevBefore?.();syncCatalog();};
async function loadPrivate(){
 if(!Q.ready||!X.canAdmin()||loading)return;
 const uid=M.me()?.id;if(requested===uid)return;loading=true;requested=uid;
 try{const packet=Q.offline?window.CM73_OFFLINE_CATALOG:await Q.request('catalog');
  if(!X.canAdmin()||M.me()?.id!==uid)return;
  if(packet?.items){privateRows=packet.items;lastRows=null;loading=false;syncCatalog();M.render();}
 }catch(err){requested='';C.catalogError=err.message;}finally{loading=false;}
}
V.after.push(()=>{if(!X.canAdmin()){privateRows=[];requested='';lastRole=null;}else void loadPrivate();});
C.catalogReady=()=>privateRows.length>0;
function list(){
 const source=state().catalog;
 const found=source.filter(p=>(scope==='all'||scope==='public'&&p.visibility==='public'||scope==='private'&&p.visibility!=='public')&&CM73Domain.rank(query,[p.name,p.id,p.material,p.category,p.adminSubtitle||'',...(p.aliases||[])])<Infinity);
 // Blank query means all rows here, unlike command search.
 const rows=query.trim()?found:source.filter(p=>scope==='all'||(scope==='public')===(p.visibility==='public'));
 if(!rows.length)return M.empty('Предмет не найден','Проверь название, ID или выбранный раздел.','search');
 return '<div class="cm73-catalog-table">'+V.table(['Предмет','Источник','Ограничения','Доступ',''],rows.map(p=>[
  `<div class="cm73-catalog-item" data-search-target="${E(p.id)}">${W.texture(p.id,38)}<span><strong>${E(p.name)}</strong><small>${E(p.adminSubtitle||p.id)}</small></span></div>`,
  `<span>${E(p.provider||'CopiMineArtifacts')}</span><small>${p.sourceType==='DONATION_SHOP'?'Донат':p.sourceType==='AR_SHOP'?'АР-лавка':p.grantable===false?'Награда':'Закрытый каталог'}</small>`,
  p.sourceType==='AR_SHOP'?`<span>${p.limit>0?p.limit+' на игрока':'Без лимита на игрока'}</span><small>${p.supplyLimit>0?'Тираж: '+p.supplyLimit:'Тираж не ограничен'}</small>`:'<span class="muted">—</span>',
  M.pill(p.visibility!=='public'?'Закрытый':p.enabled?'В магазине':'Скрыт',p.visibility==='public'&&p.enabled?'green':''),
  M.btn(p.visibility==='public'?'Изменить':'Сведения',p.visibility==='public'?'admin-product':'v73-item-info',p.visibility==='public'?'edit':'info','small ghost',`data-id="${E(p.id)}"`)
 ]))+'</div>';
}
const oldShop=W.adminExtensions.shop;
W.adminExtensions.shop=sub=>{
 if(!X.canAdmin())return '';
 const requestedScope=M.UI.params.get('scope');if(['all','public','private'].includes(requestedScope))scope=requestedScope;
 if(sub==='materials'||sub==='delivery')return oldShop(sub);
 const all=state().catalog.length,closed=state().catalog.filter(p=>p.visibility!=='public').length;
 return `<nav class="tabs"><a href="#admin/shop" class="active">Каталог CopiMine</a><a href="#admin/shop?sub=materials">Предметы Minecraft</a><a href="#admin/shop?sub=delivery">Выдача заказов</a></nav><section class="panel cm73-catalog"><div class="panel-head"><div><strong>Предметы проекта</strong><p class="hint">Источник · <code>13e8f2a</code></p></div><label class="input-wrap">${icon('search')}<input id="v73-catalog-query" type="search" value="${E(query)}" placeholder="Название, ID или плагин" aria-label="Найти предмет"></label></div><div class="cm73-catalog-filters" role="group" aria-label="Доступ к предметам">${[['all','Все',all],['public','Магазин',all-closed],['private','Закрытые',closed]].map(([id,label,count])=>`<button type="button" data-action="v73-catalog-filter" data-scope="${id}" data-search-target="${id}" aria-pressed="${scope===id}" class="${scope===id?'active':''}">${label}<span>${count}</span></button>`).join('')}</div><div id="v73-catalog-rows">${list()}</div><div class="cm73-source-foot">${icon('lock')}Закрытые позиции не показываются игрокам. Награды нельзя выдать через магазин.<span>${loading?'Загружаем закрытые определения…':''}</span></div></section>`;
};
H['v73-catalog-filter']=b=>{scope=b.dataset.scope;query='';M.navTo('admin/shop?scope='+scope);};
H['v73-item-info']=b=>{const p=M.item(b.dataset.id);if(!p||!X.canAdmin())return;
 M.openModal(E(p.name),`<div class="cm73-item-detail-head">${W.texture(p.id,64)}<div><strong>${E(p.adminSubtitle||p.provider)}</strong><code>${E(p.id)}</code></div></div><p>${E(p.description||'Закрытое определение игрового плагина.')}</p><dl class="detail-specs"><div><dt>Материал</dt><dd>${E(p.material)}</dd></div><div><dt>Модель</dt><dd>${p.customModelData||'Обычная текстура'}</dd></div><div><dt>Перезарядка способности</dt><dd>${p.cooldown?p.cooldown+' с':'Нет'}</dd></div><div><dt>Доступ</dt><dd>Только администрация</dd></div></dl>${p.grantable===false?`<div class="cm73-hint">${icon('lock')}Только сервис наград ивента. Ручная выдача и продажа недоступны.</div>`:`<div class="cm73-hint">${icon('info')}Параметры берутся из ${E(p.source)}. Изменения в игре потребуют подключения соответствующего плагина.</div>`}<div class="v71-dialog-actions">${M.btn('Закрыть','close','','primary')}</div>`,'cm73-item-dialog');
};
V.after.push((page,tab)=>{if(page!=='admin'||tab!=='shop')return;
 document.getElementById('v73-catalog-query')?.addEventListener('input',e=>{query=e.target.value;document.getElementById('v73-catalog-rows').innerHTML=list();});
 const focus=M.UI.params.get('focus');if(focus){const item=M.item(focus);if(item){scope=item.visibility==='public'?'public':'private';query='';document.getElementById('v73-catalog-rows').innerHTML=list();}}
});
// Do not offer reward-only/removed definitions through the give picker either.
const giveHandler=H['v6-item-select'];H['v6-item-select']=b=>{const item=M.item(b.dataset.id);if(item?.grantable===false)return M.toast('Этот предмет выдаётся только сервисом наград.',true);return giveHandler?.(b);};
// Public product metadata now uses permanent counts, never rolling purchase periods.
syncCatalog();
})();

/* assets/js/inventory-v73.js *//* Visual inventory editor for local review snapshots. No Minecraft command is sent.
   Codex: apply through the authenticated bridge using an expected snapshot fingerprint;
   reject stale item/NBT/quantity before altering the server inventory. */
(function(){
'use strict';
const M=CM,V=CMV4,X=CM6,W=CM5,D=CM73Domain,E=M.esc,H=M.handlers,F=M.forms;
const state=()=>M.state;let selected={player:'',kind:'inventory',slot:null},pending=null;
const getPlayer=id=>state().players.find(p=>p.id===id);
const permitted=p=>X.canAdmin()&&CM6Domain.canManage(M.me(),p);
const slotName=(i,kind)=>kind==='ender'?'Ячейка '+(i+1):({36:'Ботинки',37:'Поножи',38:'Нагрудник',39:'Шлем',40:'Левая рука'}[i]|| (i<9?'Быстрый доступ '+(i+1):'Ячейка '+(i+1)));
const itemName=item=>item?.name||W.materialName(item?.customId||item?.id)||'Предмет';
const snapshot=(p,kind)=>X.snapshot(p,kind);
function cell(p,kind,list,index){const it=list[index],active=selected.player===p.id&&selected.kind===kind&&selected.slot===index;
 return `<button type="button" class="cm73-slot ${it?'occupied':''} ${active?'selected':''}" data-action="v73-inv-slot" data-player="${E(p.id)}" data-kind="${kind}" data-slot="${index}" aria-label="${E(slotName(index,kind)+(it?': '+itemName(it)+', '+it.qty+' шт.':': пусто'))}" aria-pressed="${active}" title="${E(it?itemName(it):slotName(index,kind))}">${it?W.texture(it.customId||it.id,34):''}${it&&it.qty>1?`<b>${it.qty}</b>`:''}${it?.durability!=null?`<i class="cm73-durability" style="--durability:${Math.max(0,Math.min(1,it.durability))*100}%"></i>`:''}${index<9&&kind==='inventory'?`<small>${index+1}</small>`:''}</button>`;
}
function inspector(p,kind){const snap=snapshot(p,kind),it=D.slots(snap,kind)[selected.player===p.id&&selected.kind===kind?selected.slot:-1];
 if(!it)return `<div class="cm73-inspector-empty">${icon('mouse-pointer')}<strong>Выбери предмет</strong><p>Нажми на ячейку, чтобы увидеть свойства. ПКМ открывает действия.</p><small>На телефоне достаточно обычного нажатия.</small></div>`;
 return `<div class="cm73-inspector-title">${W.texture(it.customId||it.id,52)}<div><strong>${E(itemName(it))}</strong><span>${E(slotName(it.slot,kind))}</span></div></div><dl class="detail-specs"><div><dt>Количество</dt><dd>${it.qty} шт.</dd></div>${it.durability!=null?`<div><dt>Прочность</dt><dd>${Math.round(it.durability*100)}%</dd></div>`:''}</dl><code class="cm73-item-id">${E(it.customId||it.id)}</code>${Object.keys(it.enchantments||{}).length?`<div class="cm73-enchantments">${Object.entries(it.enchantments).map(([key,lvl])=>`<span>${E(({efficiency:'Эффективность',unbreaking:'Прочность',mending:'Починка',sharpness:'Острота',protection:'Защита',power:'Сила'})[key]||key)} ${E(lvl)}</span>`).join('')}</div>`:''}<div class="cm73-inspector-actions">${M.btn('Изъять предметы','v73-inv-remove','minus','cm73-danger',`data-player="${E(p.id)}" data-kind="${kind}" data-slot="${it.slot}" ${permitted(p)?'':'disabled'}`)}<button type="button" class="btn ghost small" data-action="v73-copy-item" data-id="${E(it.customId||it.id)}">${icon('copy')}Копировать ID</button></div>`;
}
function view(p,kind='inventory',compact=false){
 if(!X.canAdmin())return '';kind=kind==='ender'?'ender':'inventory';const snap=snapshot(p,kind),list=D.slots(snap,kind),n=list.filter(Boolean).length;
 return `<section class="cm73-inventory ${compact?'compact':''}" data-player="${E(p.id)}" data-kind="${kind}" data-search-target="inventory"><div class="cm73-inventory-head"><div><h2>Инвентари</h2><small>${E(p.name)} · ${snap?'Снимок от '+M.date(snap.at,true):'Снимок не получен'}</small></div>${M.btn('JSON','v73-inv-export','download','small ghost',`data-player="${E(p.id)}" data-kind="${kind}"`)}</div><div class="cm73-inventory-tabs" role="group" aria-label="Контейнер игрока">${[['inventory','Инвентарь','bag'],['ender','Эндер-сундук','package']].map(([key,name,ic])=>`<button type="button" data-action="v73-inv-tab" data-kind="${key}" data-player="${E(p.id)}" class="${kind===key?'active':''}" aria-pressed="${kind===key}">${icon(ic)}${name}</button>`).join('')}</div><div class="cm73-inventory-body"><div class="cm73-inventory-board">${kind==='inventory'?`<div class="cm73-gear"><span class="cm73-grid-label">Снаряжение</span><div>${[39,38,37,36,40].map(i=>`<label>${cell(p,kind,list,i)}<span>${slotName(i,kind)}</span></label>`).join('')}</div></div><span class="cm73-grid-label">Основной инвентарь</span><div class="cm73-slot-grid" role="group" aria-label="27 основных ячеек">${Array.from({length:27},(_,i)=>cell(p,kind,list,i+9)).join('')}</div><span class="cm73-grid-label">Быстрый доступ</span><div class="cm73-slot-grid">${Array.from({length:9},(_,i)=>cell(p,kind,list,i)).join('')}</div>`:`<span class="cm73-grid-label">Личный сундук · 27 ячеек</span><div class="cm73-slot-grid" role="group" aria-label="Эндер-сундук">${Array.from({length:27},(_,i)=>cell(p,kind,list,i)).join('')}</div>`}<p class="cm73-inventory-caption"><span>${n} / ${kind==='ender'?27:41} занято</span><span>${icon('mouse-pointer')}ПКМ — действия</span></p>${!snap?'<p class="cm73-hint">Пустая сетка не означает пустой инвентарь: снимок ещё не получен.</p>':''}</div><aside class="cm73-inspector" aria-live="polite">${inspector(p,kind)}</aside></div><div class="cm73-inventory-foot">${icon('shield')}Изменения требуют причины и сохраняются в журнале. Снимок приходит с игрового сервера.</div></section>`;
}
function refreshSelection(){const p=getPlayer(selected.player);if(!p)return;document.querySelectorAll('.cm73-inventory').forEach(host=>{if(host.dataset.player!==p.id||host.dataset.kind!==selected.kind)return;host.querySelectorAll('.cm73-slot').forEach(b=>{const on=Number(b.dataset.slot)===selected.slot;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});host.querySelector('.cm73-inspector').innerHTML=inspector(p,selected.kind);});}
function open(p,kind='inventory',slot=null){closeContext();selected={player:p.id,kind,slot};M.openModal('Инвентарь · '+E(p.name),view(p,kind,true),'cm73-inventory-dialog');}
function select(b){selected={player:b.dataset.player,kind:b.dataset.kind,slot:Number(b.dataset.slot)};refreshSelection();}
H['v73-inv-slot']=b=>{closeContext();select(b);};
H['v73-inv-tab']=b=>{closeContext();const p=getPlayer(b.dataset.player),host=b.closest('.cm73-inventory');selected={player:p.id,kind:b.dataset.kind,slot:null};host.outerHTML=view(p,b.dataset.kind,host.classList.contains('compact'));};
H['v73-inv-export']=b=>{const p=getPlayer(b.dataset.player),snap=snapshot(p,b.dataset.kind);if(snap)M.downloadFile('inventory-'+p.name+'-'+b.dataset.kind+'.json',JSON.stringify(snap,null,2));else M.toast('Снимок ещё не получен.',true);};
H['v73-copy-item']=b=>M.copyText(b.dataset.id);
H['v73-inv-remove']=b=>{
 closeContext();const p=getPlayer(b.dataset.player),kind=b.dataset.kind||'inventory',slot=Number(b.dataset.slot),snap=snapshot(p,kind),it=D.slots(snap,kind)[slot];
 if(!p||!it||!permitted(p))return M.toast('Нельзя изменить эту ячейку.',true);
 pending={player:p.id,kind,slot,expected:D.fingerprint(snap,kind)};
 M.openModal('Изъять предметы',`<div class="cm73-item-detail-head">${W.texture(it.customId||it.id,56)}<div><strong>${E(itemName(it))}</strong><span>${E(p.name)} · ${E(slotName(slot,kind))}</span></div></div><div class="cm-danger-note" role="alert">${icon('alert')}<div><strong>Изъятие из живой игры</strong><p>Предметы спишутся из инвентаря игрока сразу. Вернуть их можно только восстановлением из снимка, если он есть.</p></div></div><form data-form="v73-inv-remove">${V.field('Сколько изъять','qty',it.qty,'number',`required min="1" max="${it.qty}" step="1"`)}<p class="hint">В стопке ${it.qty} шт. Остальные ячейки не изменятся.</p>${V.area('Причина — только для администрации','reason','',2,'required minlength="3" maxlength="240"')}${V.field('Введите «ИЗЪЯТЬ» для подтверждения','confirmWord','','text','required autocomplete="off" spellcheck="false" placeholder="ИЗЪЯТЬ"')}<div class="form-error" role="alert"></div><div class="v71-dialog-actions">${M.btn('К инвентарю','v73-inv-back','arrow-left','ghost')}<button type="submit" class="btn cm73-danger">${icon('minus')}Изъять из снимка</button></div></form>`,'cm73-remove-dialog');
};
H['v73-inv-back']=()=>{if(pending)open(getPlayer(pending.player),pending.kind,pending.slot);};
F['v73-inv-remove']=async(f,data)=>{
 if(!pending)throw Error('Сначала выберите предмет.');const p=getPlayer(pending.player);if(!permitted(p))throw Error('Недостаточно прав.');
 if(String(data.get('confirmWord')||'').trim().toUpperCase()!=='ИЗЪЯТЬ')throw Error('Для подтверждения введите «ИЗЪЯТЬ».');
 const snap=snapshot(p,pending.kind),reason=String(data.get('reason')||'').trim();
 const result=await X.request('/admin/players/'+encodeURIComponent(p.id)+'/inventory/remove',{method:'POST',body:{kind:pending.kind,slot:pending.slot,quantity:Number(data.get('qty')),expectedVersion:snap?.version||'',reason,key:f.dataset.key||(f.dataset.key=X.uid('inventory'))}});
 const back={...pending};pending=null;await window.CMProduction.refreshInventory(p.id);M.closeModal();M.render();open(p,back.kind,back.slot);M.toast('Minecraft подтвердил удаление предмета.');
};
function closeContext(){document.getElementById('cm73-slot-menu')?.remove();}
function context(b,x,y){
 closeContext();select(b);const p=getPlayer(b.dataset.player),it=D.slots(snapshot(p,b.dataset.kind),b.dataset.kind)[Number(b.dataset.slot)];if(!it)return;
 const menu=document.createElement('div');menu.id='cm73-slot-menu';menu.className='cm73-slot-menu';menu.setAttribute('role','menu');
 menu.innerHTML=`<strong>${E(itemName(it))}</strong><small>${it.qty} шт. · ${E(slotName(it.slot,b.dataset.kind))}</small><button type="button" role="menuitem" data-action="v73-inv-remove" data-player="${E(p.id)}" data-kind="${b.dataset.kind}" data-slot="${it.slot}" ${permitted(p)?'':'disabled'}>${icon('minus')}Изъять предметы…</button><button type="button" role="menuitem" data-action="v73-copy-item" data-id="${E(it.customId||it.id)}">${icon('copy')}Копировать ID</button>`;
 // Native dialogs are in the top layer; keep this menu in that layer too.
 const dialog=b.closest('dialog');(dialog||document.body).append(menu);menu.style.left=Math.max(8,Math.min(x,innerWidth-252))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-175))+'px';menu.querySelector('button:not(:disabled)')?.focus({preventScroll:true});
}
document.addEventListener('contextmenu',e=>{const b=e.target.closest('.cm73-slot');if(!b)return;e.preventDefault();context(b,e.clientX,e.clientY);});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#cm73-slot-menu')&&!e.target.closest('.cm73-slot'))closeContext();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeContext();const b=e.target.closest?.('.cm73-slot');if(!b)return;
 if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10'){e.preventDefault();const r=b.getBoundingClientRect();context(b,r.left,r.bottom);}
 else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const list=[...b.closest('.cm73-inventory-board').querySelectorAll('.cm73-slot')],i=list.indexOf(b),step={ArrowLeft:-1,ArrowRight:1,ArrowUp:-9,ArrowDown:9}[e.key];list[Math.max(0,Math.min(list.length-1,i+step))].focus();}
});
const action=H['v6-player-action'];H['v6-player-action']=(b,e)=>{if(['inventory.remove','ender.remove'].includes(b.dataset.id)){const p=getPlayer(b.dataset.player)||X.player();if(p)open(p,b.dataset.id==='ender.remove'?'ender':'inventory');return;}return action?.(b,e);};
H['v6-slot-detail']=b=>{const p=getPlayer(b.dataset.player)||X.player();if(X.canAdmin()&&p)open(p,b.dataset.kind||'inventory',Number(b.dataset.slot));};
H['v6-remove-slot']=H['v6-slot-detail'];
W.inventoryView=p=>view(p,'inventory');
window.CM73Inventory={view,open};
})();

/* assets/js/recovery-v73.js *//* Review recovery UX. No password, PIN or authenticator secret is ever displayed.
   pin.reset / mfa.reset / minecraft.relink are explicit preview requests until Codex
   attaches the authenticated account and EconomyCore services. */
(function(){
'use strict';
const M=CM,V=CMV4,X=CM6,A=CM71,Q=CMReview,E=M.esc,H=M.handlers,F=M.forms,C=window.CM73;
const actions=[
 ['password.reset','Сменить пароль','key','Новый пароль действует сразу. Все старые сеансы завершатся.','Сменить пароль'],
 ['sessions.revoke','Завершить все сеансы','monitor','Выход со всех устройств этого аккаунта. Сам пароль остаётся прежним.','Завершить сеансы'],
 ['login.unlock','Снять блокировку попыток','refresh','Снять ограничение после неверных попыток входа. Это не отменяет блокировку аккаунта.','Снять ограничение']
];
let chosen='',accounts=[],accountsOwner='',accountsLoading=false;
const pby=id=>M.state.players.find(p=>p.id===id);
const sessionOwner=()=>X.live?X.sessionUser?.id||null:M.me()?.id||null;
const actorName=()=>X.live?X.sessionUser?.name||'Администратор':M.me()?.name||'Администратор';
function availableAccounts(){return Q.offline?[{id:'demo-001',username:'1',display_name:'DemoBuilder'}]:accounts;}
function accountPlayer(record){const p=pby(record.id)||{id:record.id,name:record.username,AR:0,CM:0,role:'Игрок',status:'active',purchaseLimits:[],provenance:'local-demo'};if(!pby(record.id))M.state.players.push(p);p.displayName=record.display_name;delete p.email;delete p.emailVerified;p.webBlocked=record.blocked;return p;}
function user(){const list=availableAccounts();list.forEach(accountPlayer);const selected=M.UI.params.get('player')||chosen,record=list.find(x=>x.id===selected)||list[0];if(record){chosen=record.id;return accountPlayer(record);}return pby(selected)||null;}
async function loadAccounts(){const owner=sessionOwner();if(!Q.ready||Q.offline||!X.can('recovery.manage')||!owner||accountsLoading||accountsOwner===owner)return;accountsLoading=true;try{const result=await Q.request('recovery-accounts');if(sessionOwner()!==owner)return;accounts=Array.isArray(result.accounts)?result.accounts:[];accountsOwner=owner;accounts.forEach(accountPlayer);if(M.UI.page==='admin'&&M.UI.tab==='recovery')M.render();}catch(err){M.toast(err.message,true);}finally{accountsLoading=false;}}
const label=status=>({preview:'Не выполнено',completed:'Выполнено',awaiting_player:'Ждём игрока',queued:'В очереди'}[status]||status);
C.recoveryView=()=>{
 if(!X.can('recovery.manage'))return `<div class="cm73-recovery">${M.empty('Нет доступа','Этот раздел доступен владельцу сайта.','lock')}</div>`;
 const p=user(),options=availableAccounts().map(accountPlayer);
 if(!p)return `<div class="cm73-recovery">${M.empty('Нет аккаунтов для восстановления','Список аккаунтов пока пуст.','user')}</div>`;
 return `<div class="cm73-recovery"><section class="cm73-recovery-person"><div>${CM5.head(p,48)}<span><strong>${E(p?.displayName||p?.name||'Аккаунт')}</strong><small>${E(p?.name||'')}</small></span></div><label class="field">Выбрать аккаунт<select id="cm73-recovery-player">${options.map(x=>`<option value="${E(x.id)}" ${x.id===p?.id?'selected':''}>${E(x.displayName||x.name)}</option>`).join('')}</select></label><dl class="detail-specs"><div><dt>Minecraft</dt><dd>${p?.linked||p?.gameLinkVerified?'Привязан':'Не привязан'}</dd></div><div><dt>Статус</dt><dd>${p?.webBlocked?'Заблокирован':'Активен'}</dd></div></dl></section><div class="cm73-recovery-actions">${actions.map(([id,title,ic,desc])=>`<section class="cm73-recovery-action" data-search-target="${id}"><span class="cm73-action-icon">${icon(ic)}</span><div><h2>${({"password.reset":"Пароль","sessions.revoke":"Сеансы","login.unlock":"Вход"})[id]}</h2><p>${desc}</p></div>${M.btn(title,'v73-recovery-action','arrow-right','ghost small',`data-id="${id}" data-player="${E(p?.id||'')}"`)}</section>`).join('')}</div></div><section class="panel mt"><div class="panel-head"><h2>История действий</h2><span class="hint">Действие · причина · результат</span></div>${(M.state.reviewRecoveryLog||[]).length?V.table(['Время','Аккаунт','Действие','Причина','Результат'],M.state.reviewRecoveryLog.map(r=>[M.date(r.at,true),E(pby(r.player)?.name||r.player),E(actions.find(a=>a[0]===r.action)?.[1]||r.action),E(r.reason),M.pill(label(r.status),r.status==='completed'?'green':'')])):M.empty('Пока нет действий','','history')}</section>`;
};
H['v73-recovery-action']=b=>{const a=actions.find(a=>a[0]===b.dataset.id),p=pby(b.dataset.player);if(!a||!p||!X.can('recovery.manage'))return;
 M.openModal(a[1],`<div class="cm73-item-detail-head">${CM5.head(p,48)}<div><strong>${E(p.displayName||p.name)}</strong><small>${E(p.name)}</small></div></div><p>${a[3]}</p><form data-form="v73-recovery"><input type="hidden" name="player" value="${E(p.id)}"><input type="hidden" name="action" value="${a[0]}">${a[0]==='password.reset'?V.field('Новый пароль','newPassword','','password','required minlength="10" maxlength="256" autocomplete="new-password"')+V.field('Повтори пароль','repeatPassword','','password','required minlength="10" maxlength="256" autocomplete="new-password"'):''}${V.area('Причина','reason','',3,'required minlength="3" maxlength="240"')}<label class="radio-line"><input type="checkbox" name="verified" required>Аккаунт проверен, действие выбрано верно</label><div class="form-error" role="alert"></div><div class="v71-dialog-actions">${M.btn('Отмена','close','','ghost')}<button type="submit" class="btn ${a[0]==='password.reset'?'cm73-danger':'primary'}">${a[4]}</button></div></form>`,'cm73-recovery-dialog');
};
F['v73-recovery']=async(f,d)=>{
 if(!d.get('verified'))throw Error('Подтверди действие.');const body={player:d.get('player'),action:d.get('action'),reason:String(d.get('reason')||'').trim()};
 if(body.action==='password.reset'){if(d.get('newPassword')!==d.get('repeatPassword'))throw Error('Пароли не совпадают.');body.newPassword=String(d.get('newPassword')||'');}
 if(body.reason.length<3)throw Error('Укажи причину.');let result;
 if(Q.offline){result={...body,id:X.uid('recovery'),status:'preview',review_only:true};}
 else result=await Q.request('recovery',body);
 (M.state.reviewRecoveryLog||=[]).unshift({...body,...result,at:Date.now(),actor:actorName()});M.audit('Восстановление доступа',pby(body.player)?.name,body.reason);M.save();M.closeModal();M.render();
 M.toast(result.message||'Действие выполнено.');
};
V.after.push((page,tab)=>{if(page==='admin'&&tab==='recovery')void loadAccounts();if(!X.can('recovery.manage')){accounts=[];accountsOwner='';}if(page==='admin'&&tab==='recovery')document.getElementById('cm73-recovery-player')?.addEventListener('change',e=>{chosen=e.target.value;M.navTo('admin/recovery?player='+encodeURIComponent(chosen));});});
})();

