/* assets/js/production.js *//* Production bindings for the approved v7.3.2 presentation. */
(function(){
'use strict';
const M=CM,V=CMV4,X=CM6,W=CM5,Q=CMReview,E=M.esc,H=M.handlers,F=M.forms;
const P=window.CMProduction={health:null};
const field=V.field,button=(label,action,iconName='refresh',className='')=>M.btn(label,action,iconName,className);
M.audit=()=>{};Q.scheduleSave=()=>{};Q.offline=false;
const allowedForms=new Set(['v7-login','v7-register','v7-code','v7-reset','v7-confirm-code','v7-link-email','v7-profile','v7-password','v7-maintenance','v7-site-ban','v73-recovery','v73-inv-remove','v71-transfer','v6-reauth','v6-profile','v6-password','v6-totp-setup','v6-totp-confirm','v6-cookie-settings','v6-player-action','v6-server-action','ticket','reply','v6-map-settings','catalog-save','v6-role','ticket-answer','ticket-message','production-account','production-account-edit','production-mc-code','production-mc-confirm','production-checkout','production-content','production-totp-disable','production-release','production-release-apply','production-release-rollback','production-release-report','production-monitor-interval']);
for(const key of Object.keys(F))if(!allowedForms.has(key))F[key]=()=>{throw Error('Действие недоступно. Изменения не сохранены.');};
for(const key of Object.keys(H))if(/^(demo|v6-demo|v7-test|payment-(success|simulate)|balance-|mark-delivered|delivery-|recipe-(save|publish|delete|import)|v7-feedback|v7-inbox|reset)/.test(key))H[key]=()=>M.toast('Операция недоступна.',true);
Q.request=(function(original){return async(path,body)=>{

 try{return await original(path,body);}catch(error){
   if(/Подтвердите пароль/.test(error.message))M.toast('Подтвердите вход в настройках безопасности и повторите действие.',true);
   throw error;
 }
};})(Q.request);
H['v7-vk']=undefined;
H['v7-totp']=()=>H['v6-totp-setup']();
H['v7-game-link']=()=>M.openModal('Связать Minecraft','<p>Зайдите на сервер и войдите через AuthMe. Код появится в личном сообщении в игре.</p><form data-form="production-mc-code">'+field('Ник Minecraft','name','','text','required pattern="[A-Za-z0-9_]{3,16}" autocomplete="off"')+V.actions('Получить код в игре')+'</form>');
F['production-mc-code']=async(f,d)=>{await X.request('/account/minecraft/request',{method:'POST',body:{name:d.get('name')}});M.openModal('Введите код из Minecraft','<form data-form="production-mc-confirm">'+field('Код из личного сообщения','code','','text','required minlength="6" maxlength="12" autocomplete="one-time-code"')+V.actions('Подтвердить привязку')+'</form>');};
F['production-mc-confirm']=async(f,d)=>{await X.request('/account/minecraft/confirm',{method:'POST',body:{code:d.get('code')}});await Q.reload();M.closeModal();M.toast('Профиль Minecraft подтверждён.');};

P.refreshInventory=async id=>{
 const r=await X.request('/admin/players/'+encodeURIComponent(id)+'/inventory'),p=M.state.players.find(p=>p.id===id),snap=r.snapshot;
 M.state.playerSnapshots=M.state.playerSnapshots.filter(x=>x.playerId!==id);
 for(const [kind,key,version] of [['inventory','inventory','inventoryVersion'],['ender','enderChest','enderVersion']]){
  M.state.playerSnapshots.push({id:snap.id+'-'+kind,playerId:id,player:p?.name||snap.player,kind,at:snap.capturedAt,source:'live',version:snap[version],slots:(snap[key]||[]).filter(x=>x.amount>0&&x.material!=='AIR').map(x=>({...x,id:'minecraft:'+x.material.toLowerCase(),qty:x.amount}))});
 }
 return snap;
};
H['production-inventory-refresh']=async b=>{
 try{await P.refreshInventory(b.dataset.player);M.render();M.toast('Получен снимок Minecraft.');}
 catch(e){M.toast(e.message,true);}
};
H['v6-inventory-refresh']=H['production-inventory-refresh'];
const originalInventory=window.CM73?.inventory;

const beforeAdminOverview=W.adminExtensions.overview;
function metric(label,value){return '<section class="panel"><span class="label">'+label+'</span><strong class="production-metric">'+E(value)+'</strong></section>';}
P.refreshHealth=async()=>{P.health=await X.request('/admin/health');};
function gameStatus(game,health=P.health){
 if(health?.error)return 'Нет доступа к проверке';
 if(!health)return 'Проверяется';
 if(game.ready)return 'Подключён';
 if(game.online&&game.adapter)return 'Не все плагины готовы';
 if(game.online)return 'Игровой мост не отвечает';
 return 'Игровой сервер не отвечает';
}
function databaseStatus(health){
 if(health?.error)return 'Нет доступа к проверке';
 if(!health)return 'Проверяется';
 if(health.database==='postgresql')return 'Работает · PostgreSQL';
 if(health.database==='sqlite-test')return 'Тестовая база';
 return 'Нет данных';
}
W.adminExtensions.overview=()=>{
 const game=P.health?.game||M.state.game||{},owner=X.can('accounts.manage');
 return '<div class="v6-server-summary">'+metric('Игровой сервер',gameStatus(game))+metric('Онлайн',game.players??'—')+metric('База сайта',databaseStatus(P.health))+'</div><section class="panel mt"><h2>Управление</h2><div class="v6-actions-grid mt">'+[['players','Игроки и инвентари'],['shop','Каталог'],['world','Карта и расписание'],['requests','Обращения'],['moderation','Наказания'],['audit','Журнал действий'],['system','Подключения и аккаунты']].map(([id,text])=>M.link(text,'#admin/'+id,'arrow-right','')).join('')+'</div></section><section class="panel mt"><h2>Последние действия</h2>'+((M.state.audit||[]).length?V.table(['Время','Действие','Кто','Объект'],M.state.audit.slice(0,10).map(r=>[M.date(r.at,true),E(r.action),E(r.actor),E(r.target)])):M.empty('Записей пока нет','Здесь появятся подтверждённые действия.','history'))+'</section>';
};
W.adminExtensions.system=()=>{
 const h=P.health,g=h?.game||{};
 return '<section class="panel"><h2>Подключения</h2>'+V.table(['Сервис','Состояние'],[['База сайта',E(databaseStatus(h))],['Minecraft',E(gameStatus(g,h))],['Платежи','Не подключены']])+'<div class="actions mt">'+button('Проверить подключения','production-health','refresh','ghost small')+'</div></section>'+(X.can('accounts.manage')?'<section class="panel mt"><h2>Аккаунты сайта</h2><p class="hint">Создай аккаунт или измени роль и доступ. Все изменения записываются в журнал.</p>'+button('Создать аккаунт','production-account-new','plus','primary mt')+V.table(['Аккаунт','Роль','Доступ',''],M.state.players.filter(p=>!p.gameOnly).map(p=>[E(p.displayName||p.name),E(p.serverRole||p.role),p.enabled?'Открыт':'Закрыт',p.id!==M.me()?.id?button('Изменить','production-account-edit','edit','small').replace('data-action="production-account-edit"','data-action="production-account-edit" data-id="'+E(p.id)+'"'):'Текущий аккаунт']))+'</section>':'');
};
H['production-health']=async()=>{await P.refreshHealth();M.render();};
H['production-account-new']=()=>M.openModal('Создать аккаунт','<div class="cm-danger-note" role="alert">'+icon('alert')+'<div><strong>Обрати внимание</strong><p>Аккаунт получит доступ сразу после создания с выбранной ролью. Пароль передайте лично: сменить его владелец сможет только через восстановление доступа.</p></div></div><form data-form="production-account">'+field('Логин','name','','text','required pattern="[A-Za-z0-9_]{3,32}"')+field('Временный пароль','password','','password','required minlength="10" autocomplete="new-password"')+V.select('Роль','role',[['player','Игрок'],['helper','Помощник'],['moderator','Модератор'],['admin','Администратор']],'player')+field('Причина','reason','','text','required minlength="3"')+V.actions('Создать аккаунт')+'</form>');
F['production-account']=async(f,d)=>{await X.request('/admin/accounts',{method:'POST',body:Object.fromEntries(d)});await Q.reload();M.closeModal();M.toast('Аккаунт создан.');};
H['production-account-edit']=b=>{const p=M.state.players.find(x=>x.id===b.dataset.id);if(!p)return;M.openModal('Доступ: '+E(p.name),'<div class="cm-danger-note" role="alert">'+icon('alert')+'<div><strong>Изменение доступа</strong><p>Новая роль и закрытие доступа применяются сразу, а все сеансы этого аккаунта завершаются — человеку придётся войти заново. Роль «Администратор» даёт доступ почти ко всей админке.</p></div></div><form data-form="production-account-edit"><input type="hidden" name="id" value="'+E(p.id)+'">'+V.select('Роль','role',[['player','Игрок'],['helper','Помощник'],['moderator','Модератор'],['admin','Администратор']],p.serverRole||p.role)+'<label class="check-row"><input type="checkbox" name="enabled" '+(p.enabled?'checked':'')+'>Доступ к сайту открыт</label>'+field('Причина','reason','','text','required minlength="3"')+field('Введите имя «'+E(p.name)+'» для подтверждения','confirmName','','text','required autocomplete="off" spellcheck="false" placeholder="'+E(p.name)+'"')+V.actions('Сохранить доступ')+'</form>');};
F['production-account-edit']=async(f,d)=>{const p=M.state.players.find(x=>x.id===d.get('id'));const name=String(d.get('confirmName')||'').trim();if(!p||name.toLowerCase()!==String(p.name).toLowerCase())throw Error('Для подтверждения введите имя аккаунта: '+((p&&p.name)||''));await X.request('/admin/accounts/'+encodeURIComponent(d.get('id')),{method:'PATCH',body:{role:d.get('role'),enabled:!!d.get('enabled'),reason:d.get('reason')}});await Q.reload();M.closeModal();M.toast('Доступ обновлён.');};

H['checkout']=()=>{
 if(!M.me())return M.navTo('auth/login');
 const items=M.state.cart.map(x=>({id:x.id,qty:x.qty}));
 if(!items.length)return M.toast('Корзина пуста.',true);
 M.openModal('Подтвердить покупку','<p>Покупка проводится игровым банком. Предметы будут доступны через выдачу артефактов на сервере.</p><form data-form="production-checkout">'+field('PIN игрового банка','pin','','password','required pattern="[0-9]{4,8}" inputmode="numeric" autocomplete="off"')+V.actions('Купить')+'</form>');
};
F['production-checkout']=async(f,d)=>{const items=M.state.cart.map(x=>({id:x.id,qty:x.qty}));const total=items.reduce((n,x)=>n+(M.item(x.id)?.price||0)*x.qty,0);await X.request('/checkout',{method:'POST',body:{items,pin:d.get('pin'),expectedTotal:total,idempotencyKey:f.dataset.key||(f.dataset.key=X.uid('checkout'))}});M.state.cart=[];await X.refresh();M.closeModal();M.toast('Игровой банк подтвердил покупку.');};
F['v6-totp-confirm']=async(f,d)=>{const r=await X.request('/auth/totp/confirm',{method:'POST',body:{totp:d.get('totp')}});await Q.reload();M.openModal('Резервные коды 2FA','<p>Сохраните эти одноразовые коды. Повторно они показаны не будут.</p><pre class="production-codes">'+E((r.backupCodes||[]).join('\n'))+'</pre>'+button('Сохранил коды','close','check','primary'));};

const bytes=n=>{if(n==null)return '—';const units=['Б','КБ','МБ','ГБ','ТБ'];let v=Number(n),i=0;while(v>=1024&&i<units.length-1){v/=1024;i++;}return v.toFixed(v>=10||i===0?0:1)+' '+units[i];};
const can=permission=>!X.live?X.canAdmin():X.can(permission);
const releaseStatus={prepared:'Подготовлен',backed_up:'Копия создана',checked:'Проверен',blocked:'Есть ошибки',armed:'Ждёт установки',rollback_armed:'Ждёт отката'};
const ciStatus={pass:'Пройден',fail:'Ошибка',running:'Выполняется',skipped:'Не запускался'};
function spark(points){
 if(!points.length)return '';
 const step=100/Math.max(1,points.length-1);
 // Шкала 15–20 TPS: иначе ровные 20 рисуют линию по самому краю и график выглядит пустым.
 const y=t=>{const v=Math.min(20,Math.max(15,Number(t.tps)||0));return (8+(20-v)/5*20).toFixed(2);};
 const line=points.map((p,i)=>(i?'L':'M')+(i*step).toFixed(2)+' '+y(p)).join(' ');
 const tps=points.map(p=>Number(p.tps)||0),last=tps[tps.length-1];
 const lows=points.map(p=>p.low!=null?Number(p.low):Number(p.tps)||0);
 const cpu=points.map(p=>p.cpu).filter(v=>v!=null).map(Number);
 // CPU игры рисуем по его собственной шкале: 8% и 80% надо различать глазом.
 const cpuMax=cpu.length?Math.max(10,Math.ceil(Math.max(...cpu)/10)*10):0;
 const cpuLine=cpuMax?points.map((p,i)=>(i?'L':'M')+(i*step).toFixed(2)+' '+(28-Math.min(cpuMax,Math.max(0,Number(p.cpu)||0))/cpuMax*20).toFixed(2)).join(' '):'';
 return '<svg class="v6-spark" viewBox="0 0 100 30" preserveAspectRatio="none" width="100%" height="90" role="img" aria-label="TPS за последние '+points.length+' минут: от '+Math.min(...lows).toFixed(1)+' до '+Math.max(...tps).toFixed(1)+'">'
  +'<line x1="0" y1="8" x2="100" y2="8" class="v6-spark-grid" vector-effect="non-scaling-stroke"/>'
  +'<line x1="0" y1="28" x2="100" y2="28" class="v6-spark-grid" vector-effect="non-scaling-stroke"/>'
  +(cpuLine?'<path d="'+cpuLine+'" fill="none" stroke="#7aa6c9" stroke-width="1.2" opacity=".9" vector-effect="non-scaling-stroke"/>':'')
  +'<path d="'+line+'" fill="none" stroke="currentColor" stroke-width="1.8" vector-effect="non-scaling-stroke"/>'
  +'</svg>'
  +'<p class="hint v6-spark-legend">TPS сейчас '+last.toFixed(1)+' · минимум '+Math.min(...lows).toFixed(1)+' · максимум '+Math.max(...tps).toFixed(1)
  +(cpuMax?' · <span class="v6-spark-cpu">CPU игры</span> до '+Math.max(...cpu).toFixed(0)+'% из '+cpuMax+'% на шкале':'')+' за '+points.length+' минут</p>';
}
P.refreshMonitor=async()=>{P.monitor=await X.request('/admin/monitor');};
P.refreshReleases=async()=>{P.releases=await X.request('/admin/releases');};

W.adminExtensions.monitor=()=>'<div id="v6-monitor-body">'+monitorBody()+'</div>';

function monitorBody(){
 if(!can('server.monitor'))return M.empty('Нужны права администратора','Мониторинг доступен администраторам и владельцу.','lock');
 const r=P.monitor;
 if(!r)return '<section class="panel" role="status"><h2>Мониторинг сервера</h2><p>Загружаем последний замер. Сборщик пишет его раз в полминуты, а панель подставляет свежие данные без перезагрузки страницы.</p></section>';
 if(r.error)return '<section class="panel"><h2>Мониторинг сервера</h2><p class="hint">'+E(r.error)+'</p><div class="actions mt">'+button('Повторить','production-monitor-refresh','refresh','ghost small')+'</div></section>';
 const s=r.sample;
 if(!s)return '<section class="panel"><h2>Замеров пока нет</h2><p class="hint">Сборщик запускается вместе с сайтом. Первый замер появится в течение тридцати секунд.</p><div class="actions mt">'+button('Обновить','production-monitor-refresh','refresh','ghost small')+'</div></section>';
 const process=s.host?.process||{},system=s.host?.system||{},db=s.database||{},errors=s.errors||{};
 const worlds=s.worlds||[],history=r.history||[];
 const ages=r.stale==null?'—':r.stale<120?r.stale+' сек назад':Math.round(r.stale/60)+' мин назад';
 return '<div class="v6-server-summary v6-server-summary-4">'
  +metric('TPS',s.tps==null?'—':Number(s.tps).toFixed(1))
  +metric('MSPT',s.mspt==null?'—':Number(s.mspt).toFixed(2)+' мс')
  +metric('Игроков онлайн',s.players)
  +metric('Служба',process.activeState==='active'?'Работает':E(process.activeState||'Нет данных'))
  +'</div>'
  +'<section class="panel mt"><div class="panel-head"><div><h2>TPS и задержка тика</h2><p class="hint">Замер '+(s.sampled_s?M.date(s.sampled_s*1000,true):'—')+' · обновляется на месте, замер раз в '+Math.round(r.intervalSeconds||3)+' сек · '+'<span id="v6-monitor-age">'+ages+'</span>'+(r.stale>300?' · сборщик молчит':'')+' · зелёная линия — TPS, синяя — загрузка игры</p></div>'+button('Обновить','production-monitor-refresh','refresh','ghost small')+'</div>'+spark(history)+'</section>'
  +'<div class="admin-grid mt">'
  +'<section class="panel"><h2>Память и диск</h2>'+V.table(['Показатель','Значение'],[
    ['Память сервера, всего',bytes(system.memoryTotal)],
    ['Занято на сервере',bytes(system.memoryUsed)+(system.memoryPercent!=null?' · '+system.memoryPercent+'%':'')],
    ['Процесс Minecraft',bytes(process.memoryBytes)],
    ['Свободно на диске',bytes(system.disk?.free)+(system.disk?' · занято '+system.disk.percent+'%':'')],
    ['Загрузка CPU',(system.load||[]).map(x=>x.toFixed(2)).join(' / ')||'—'],
    ['Ядер',system.cpuCount??'—'],
    ['Аптайм сервера',system.uptimeSeconds!=null?Math.floor(system.uptimeSeconds/86400)+' д '+Math.floor(system.uptimeSeconds%86400/3600)+' ч':'—'],
    ['Перезапусков службы',process.restarts??'—'],
    ['Служба запущена',E(process.startedAt||'—')]
  ])+'</section>'
  +'<section class="panel"><h2>База сайта</h2>'+V.table(['Показатель','Значение'],[
    ['Движок',db.engine==='postgresql'?'PostgreSQL':'SQLite (тест)'],
    ['Доступна',db.ok===false?'Нет':db.engine==='postgresql'?'Да':'—'],
    ['Соединений',db.connections!=null?db.connections+' из '+(db.maxConnections??'—'):'—'],
    ['Самое старое соединение',db.oldestSeconds!=null?db.oldestSeconds+' сек':'—'],
    ['Размер',bytes(db.bytes)]
  ])+'</section></div>'
  +'<section class="panel mt"><h2>Нагрузка по мирам</h2>'+(worlds.length?V.table(['Мир','Измерение','Загружено чанков'],worlds.map(w=>[E(w.name||'—'),E(w.dimension||'—'),w.chunks??'—'])):M.empty('Нет данных по мирам','Ответ игрового моста не содержит списка миров.','map'))+'<p class="hint mt">Количество сущностей игровой сервер пока не отдаёт: плагин-мост его не считает. Показаны загруженные чанки.</p></section>'
  +'<section class="panel mt"><h2>Ошибки плагинов</h2>'+(errors.available?(errors.count?V.table(['Источник','Предупреждений и ошибок'],Object.entries(errors.bySource||{}).sort((a,b)=>b[1]-a[1]).map(([k,v])=>[E(k),v]))+(errors.samples||[]).length?'<pre class="v6-log-samples">'+errors.samples.map(l=>E(l)).join('\n')+'</pre>':'':'<p class="hint">В последних '+errors.tail+' строках журнала предупреждений нет.</p>'):'<p class="hint">Журнал игры недоступен для чтения.</p>')+'</section>'
  +'<section class="panel mt"><h2>Плагины</h2><p class="hint">Версии читаются из установленных jar при каждом замере: '+s.plugins+' шт. Полный список с контрольными суммами — в разделе «Релизы».</p></section>'
  +'<section class="panel mt"><div class="panel-head"><div><h2>Журнал нагрузки</h2><p class="hint">Просадки TPS ниже 18 или тик дольше 40 мс. Рядом — что было в этот момент.</p></div></div>'+incidentsTable(r.incidents||[])+'</section>'
  +'<section class="panel mt"><div class="panel-head"><div><h2>Интервал замера</h2><p class="hint">Сборщик пишет замер с этой частотой, панель подтягивает его без перезагрузки страницы.</p></div></div>'
  +'<form data-form="production-monitor-interval" class="v6-inline-form">'+field('Секунды','seconds',String(r.intervalSeconds||3),'number','min="2" max="300" required step="1"')+V.actions('Сохранить интервал')+'</form></section>';
}

function incidentsTable(list){
 if(!list.length)return '<p class="hint">За сутки просадок не было.</p>';
 return V.table(['Начало','Длительность','TPS','Тик','Игроков','CPU игры'],list.slice().reverse().map(x=>[
  M.date(x.from*1000,true),
  Math.max(1,x.to-x.from)+' сек',
  x.tps==null?'—':Number(x.tps).toFixed(1),
  x.mspt==null?'—':Number(x.mspt).toFixed(0)+' мс',
  x.players??'—',
  x.cpu==null?'—':Number(x.cpu).toFixed(0)+'%'
 ]));
}

W.adminExtensions.releases=()=>{
 if(!can('release.manage'))return M.empty('Нужен доступ владельца','Управление релизами доступно только владельцу: установка меняет игровой сервер.','lock');
 const r=P.releases;
 if(!r)return '<section class="panel" role="status"><h2>Центр управления релизами</h2><p>Читаем установленные плагины и контрольные суммы.</p></section>';
 if(r.error)return '<section class="panel"><h2>Центр управления релизами</h2><p class="hint">'+E(r.error)+'</p><div class="actions mt">'+button('Повторить','production-release-refresh','refresh','ghost small')+'</div></section>';
 const i=r.installed||{},plugins=i.plugins||[],staging=r.staging||[],ci=i.ci||null;
 const rows=(r.releases||[]).map(x=>{
  const id=E(x.id),state=releaseStatus[x.status]||x.status;
  const actions=(x.status==='blocked'?'':M.btn('Копия','production-release-backup','package','small','data-id="'+id+'"'))+(x.status==='prepared'||x.status==='blocked'?M.btn('Проверить','production-release-check','check','small','data-id="'+id+'"'):'')+(x.status==='checked'?M.btn('Установить','production-release-apply','server','small','data-id="'+id+'"'):'')+(x.backup?.jars?M.btn('Откатить','production-release-rollback','undo','small','data-id="'+id+'"'):'');
  return [E(x.version)+'<small>'+M.date(x.created_s*1000,true)+'</small>',M.pill(state,x.status==='blocked'?'danger':x.status==='armed'||x.status==='rollback_armed'?'':'green'),E(x.actor_name),E(x.reason||''),actions||'—'];
 });
 return '<section class="panel"><h2>Что установлено</h2>'+V.table(['Показатель','Значение'],[
   ['Коммит GitHub',i.commit?E(i.commit)+(i.commitSource?' <small>'+E(i.commitSource)+'</small>':''):'<span class="hint">не указан</span>'],
   ['Результат CI',ci?M.pill(ciStatus[ci.status]||ci.status,ci.status==='pass'?'green':ci.status==='fail'?'danger':'')+(ci.url?' '+M.link('Сборка',''+E(ci.url),'arrow-up-right','small'):''):'<span class="hint">не указан</span>'],
   ['Paper',E(i.paper||'—')],
   ['Minecraft',E(i.minecraft||'—')],
   ['Плагинов',plugins.length]
  ])+'<div class="actions mt">'+button('Обновить','production-release-refresh','refresh','ghost small')+button('Указать коммит и CI','production-release-report','edit','ghost small')+'</div><p class="hint mt">Коммит и CI берутся из данных деплоя: сайт не является git-репозиторием на сервере и не может узнать их сам.</p></section>'
  +'<section class="panel mt"><div class="panel-head"><div><h2>Установленные плагины</h2><p class="hint">Версии и SHA-256 читаются с диска.</p></div></div>'
  +V.table(['Плагин','Версия','API','Размер','SHA-256'],plugins.map(p=>[E(p.name)+'<small>'+E(p.file)+'</small>',E(p.version||'—'),E(p.apiVersion||'—'),bytes(p.size),'<code>'+E((p.sha256||'').slice(0,16))+'</code>']))+'</section>'
  +'<section class="panel mt"><div class="panel-head"><div><h2>Заготовка обновления</h2><p class="hint">Файлы из '+E(r.stagingPath||'')+'</p></div>'+button('Подготовить обновление','production-release-new','plus','primary small')+'</div>'
  +(staging.length?V.table(['Файл','Плагин','Версия','Проверка'],staging.map(p=>[E(p.file),E(p.name),E(p.version||'—'),p.expected?(p.verified?M.pill('Совпадает','green'):M.pill('Не совпадает','danger')):M.pill('Нет .sha256','')])):'<p class="hint">Каталог пуст. Положи новые jar в каталог заготовки на сервере — тогда кнопка соберёт из них релиз.</p>')+'</section>'
  +'<section class="panel mt"><h2>Релизы</h2>'+(rows.length?V.table(['Версия','Статус','Автор','Причина','Действия'],rows):M.empty('Релизов ещё не было','Подготовка, резервная копия и проверка выполняются по шагам.','history'))+'</section>'
  +'<section class="panel mt"><h2>Как применяется установка</h2><p class="hint">Кнопка «Установить» требует ввести слово подтверждения и создаёт задание. Файлы плагинов меняет отдельная команда на сервере от root — веб-приложение не имеет права писать в каталог плагинов, поэтому одно нажатие не может ничего сломать. Перед заменой команда сохраняет прежние jar и проверяет SHA-256.</p><pre class="v6-log-samples">'+E(r.installCommand||'')+'&lt;id&gt;</pre></section>';
};

H['production-monitor-refresh']=async()=>{try{await P.refreshMonitor();paintMonitor();M.toast('Данные обновлены.');}catch(e){M.toast(e.message,true);}};
F['production-monitor-interval']=async(f,d)=>{
 await X.request('/admin/monitor/interval',{method:'POST',body:{seconds:Number(d.get('seconds'))}});
 await P.refreshMonitor();
 paintMonitor();
 P.monitorLive();
 M.toast('Интервал сохранён: '+(P.monitor?.intervalSeconds||d.get('seconds'))+' сек.');
};

// Метрики обновляются на месте: страница не перерисовывается целиком.
let monitorTimer=0,ageTimer=0;
function paintMonitor(){
 const host=document.getElementById('v6-monitor-body');
 if(!host)return false;
 host.innerHTML=monitorBody();
 return true;
}
P.monitorStop=()=>{clearInterval(monitorTimer);clearInterval(ageTimer);monitorTimer=0;ageTimer=0;};
P.monitorLive=()=>{
 clearInterval(monitorTimer);clearInterval(ageTimer);
 // «N сек назад» тикает каждую секунду, но сам блок не перерисовывается.
 ageTimer=setInterval(()=>{
  const node=document.getElementById('v6-monitor-age'),stamp=P.monitor?.sample?.sampled_s;
  if(!node)return clearInterval(ageTimer);
  if(stamp)node.textContent=Math.max(0,Math.round(Date.now()/1000-stamp))+' сек назад';
 },1000);
 const tick=async()=>{
  if(document.hidden||!document.getElementById('v6-monitor-body'))return;
  // Перерисовываем только когда пришёл новый замер, чтобы блок не мигал.
  const before=P.monitor?.sample?.id;
  try{await P.refreshMonitor();if(P.monitor?.sample?.id!==before)paintMonitor();}catch{}
 };
 // Опрос с той же частотой, с какой сборщик пишет замер.
 const seconds=Math.max(2,Number(P.monitor?.intervalSeconds)||3);
 monitorTimer=setInterval(tick,seconds*1000);
};
H['production-release-refresh']=async()=>{try{await P.refreshReleases();M.render();M.toast('Данные обновлены.');}catch(e){M.toast(e.message,true);}};
H['production-release-new']=()=>M.openModal('Подготовить обновление','<p>Шаги выполнятся по порядку: релиз → резервная копия плагинов и базы → проверка совместимости. Установка запускается отдельно и только словом подтверждения.</p><form data-form="production-release">'+field('Версия','version','','text','required pattern="[0-9A-Za-z._-]{3,40}" placeholder="2026.10.28-1"')+field('Причина','reason','','text','required minlength="3" maxlength="240"')+V.actions('Подготовить, сохранить копию и проверить')+'</form>');
F['production-release']=async(f,d)=>{
 await X.request('/admin/releases',{method:'POST',body:{version:d.get('version'),reason:d.get('reason')}});
 const list=await X.request('/admin/releases'),latest=(list.releases||[])[0];
 if(!latest)throw Error('Релиз не создан.');
 await X.request('/admin/releases/'+encodeURIComponent(latest.id)+'/backup',{method:'POST',body:{}});
 const check=await X.request('/admin/releases/'+encodeURIComponent(latest.id)+'/check',{method:'POST',body:{}});
 await P.refreshReleases();M.closeModal();M.render();
 M.toast(check.ok?'Обновление проверено. Можно устанавливать.':'Проверка нашла проблемы: установка заблокирована.',!check.ok);
};
H['production-release-backup']=async b=>{try{await X.request('/admin/releases/'+encodeURIComponent(b.dataset.id)+'/backup',{method:'POST',body:{}});await P.refreshReleases();M.render();M.toast('Резервная копия создана.');}catch(e){M.toast(e.message,true);}};
H['production-release-check']=async b=>{try{const r=await X.request('/admin/releases/'+encodeURIComponent(b.dataset.id)+'/check',{method:'POST',body:{}});await P.refreshReleases();M.render();M.toast(r.ok?'Совместимость подтверждена.':'Установка заблокирована: есть ошибки проверки.',!r.ok);}catch(e){M.toast(e.message,true);}};
H['production-release-apply']=b=>M.openModal('Установить обновление','<p>Будут заменены файлы плагинов и перезапущен игровой сервер. Перед заменой сохраняются прежние jar, откат доступен в этом же списке.</p><form data-form="production-release-apply"><input type="hidden" name="id" value="'+E(b.dataset.id)+'">'+field('Введите УСТАНОВИТЬ','confirm','','text','required autocomplete="off" placeholder="УСТАНОВИТЬ"')+field('Причина','reason','','text','required minlength="3" maxlength="240"')+V.actions('Создать задание на установку')+'</form>');
F['production-release-apply']=async(f,d)=>{const r=await X.request('/admin/releases/'+encodeURIComponent(d.get('id'))+'/apply',{method:'POST',body:{confirm:d.get('confirm'),reason:d.get('reason')}});await P.refreshReleases();M.closeModal();M.render();M.toast('Задание создано. Запуск: '+r.command);};
H['production-release-rollback']=b=>M.openModal('Откатить релиз','<p>Плагины вернутся к резервной копии этого релиза. Файлы и база не удаляются.</p><form data-form="production-release-rollback"><input type="hidden" name="id" value="'+E(b.dataset.id)+'">'+field('Введите ОТКАТИТЬ','confirm','','text','required autocomplete="off" placeholder="ОТКАТИТЬ"')+field('Причина','reason','','text','required minlength="3" maxlength="240"')+V.actions('Создать задание на откат')+'</form>');
F['production-release-rollback']=async(f,d)=>{const r=await X.request('/admin/releases/'+encodeURIComponent(d.get('id'))+'/rollback',{method:'POST',body:{confirm:d.get('confirm'),reason:d.get('reason')}});await P.refreshReleases();M.closeModal();M.render();M.toast('Задание на откат создано. Запуск: '+r.command);};
H['production-release-report']=()=>{const i=P.releases?.installed||{},ci=i.ci||{};M.openModal('Коммит и результат CI','<form data-form="production-release-report">'+field('Коммит GitHub','commit',i.commit||'','text','pattern="[0-9a-fA-F]{7,40}" autocomplete="off" placeholder="a90108f"')+V.select('Результат CI','status',[['pass','Пройден'],['fail','Ошибка'],['running','Выполняется'],['skipped','Не запускался']],ci.status||'skipped')+field('Ссылка на сборку','url',ci.url||'','url','maxlength="500"')+field('Кто сообщил','source',i.commitSource||'deploy','text','maxlength="40"')+V.actions('Сохранить')+'</form>');};
F['production-release-report']=async(f,d)=>{const ci={status:d.get('status'),url:d.get('url')||''};await X.request('/admin/releases/report',{method:'POST',body:{commit:d.get('commit'),source:d.get('source')||'deploy',ci}});await P.refreshReleases();M.closeModal();M.render();M.toast('Данные о коммите сохранены.');};

V.after.push((page,tab)=>{
 document.querySelectorAll('.v7-reviewbar,.v7-test-hint,.v7-local-mail-note,[data-action="v7-feedback"],[data-action="v7-review-options"]').forEach(n=>n.remove());
 const send=document.getElementById('v71-send-error');
 if(send&&!document.getElementById('production-bank-pin'))send.insertAdjacentHTML('beforebegin',field('PIN игрового банка','pin','','password','id="production-bank-pin" inputmode="numeric" pattern="[0-9]{4,8}" autocomplete="off" required'));
 if(page==='admin'&&tab==='players'){
  document.querySelectorAll('.cm73-inventory').forEach(n=>{if(!n.querySelector('[data-action="production-inventory-refresh"]'))n.querySelector('.cm73-inventory-head')?.insertAdjacentHTML('beforeend',button('Обновить из игры','production-inventory-refresh','refresh','small').replace('data-action="production-inventory-refresh"','data-action="production-inventory-refresh" data-player="'+E(n.dataset.player)+'"'));});
 }
 // Каждая из этих загрузок заканчивается M.render(), поэтому повторный запрос
 // запускается только когда данных ещё нет — иначе страница рендерится по кругу.
 if(page==='admin'&&!P.health&&!P.loading){P.loading=true;P.refreshHealth().then(()=>M.render()).catch(e=>{P.health={error:e.message};}).finally(()=>P.loading=false);}
 if(page==='admin'&&tab==='monitor'&&!P.monitor&&!P.monitorLoad){P.monitorLoad=true;P.refreshMonitor().then(()=>{if(!paintMonitor())M.render();}).catch(e=>{P.monitor={sample:null,history:[],error:e.message};M.render();}).finally(()=>P.monitorLoad=false);}
 if(page==='admin'&&tab==='monitor')P.monitorLive();else P.monitorStop();
 if(page==='admin'&&tab==='releases'&&!P.releases&&!P.releasesLoad){P.releasesLoad=true;P.refreshReleases().then(()=>M.render()).catch(e=>{P.releases={error:e.message,installed:{},staging:[],releases:[]};}).finally(()=>P.releasesLoad=false);}
});
})();

/* assets/js/bluemap.js *//* Same-origin BlueMap viewer. Native controls own zoom, camera and coordinates. */
(function(){
'use strict';
const M=CM,V=CMV4,X=CM6,W=CM5,E=M.esc,H=M.handlers,F=M.forms;
// Initial view targets the explored area (-112..255, -176..191); re-tune if the world grows.
const home=':64:0:8:'+(innerWidth<640?80:65)+':0:0:0:1:flat';
let info=null,admin=null,scope='private',timer=null,busy=false,loaded=false,error='',dimension='overworld',camera=home;
const labels={queued:'В очереди',waiting_for_resources:'Ожидаем свободных ресурсов',running:'Рендер карты',validating:'Проверка файлов',publishing:'Публикация',completed:'Новый снимок опубликован',failed:'Обновление не выполнено'};
const errors={game_unavailable:'Minecraft не ответил.',bluemap_unavailable:'BlueMap ещё не готов.',low_disk_space:'Недостаточно свободного места.',invalid_publication:'Файлы карты не прошли проверку.',missing_map_metadata:'Нет метаданных одного из измерений.',resource_wait_timeout:'Сервер был занят более 30 минут. Повторите позже.',renderer_flush_failed:'Не удалось сохранить файлы BlueMap.'};
const date=value=>value?new Date(value*1000).toLocaleString('ru-RU'):'Ещё не было';
const btn=(label,action,icon='refresh',cls='',extra='')=>M.btn(label,action,icon,cls,extra);
function activeJob(){return admin?.job&&['queued','waiting_for_resources','running','validating','publishing'].includes(admin.job.status);}
// Hash BlueMap: map:x:y:z:distance:rotation:angle:tilt:ortho:state. Флаг ortho=1
// возвращает плоскую проекцию, поэтому вместе со state переключаем и его.
function cameraMode(cam,on){const p=cam.split(':');if(p.length!==10)return cam;p[6]=on?(Number(p[6])>0.05?p[6]:'0.62'):'0';p[8]=on?'0':'1';p[9]=on?'perspective':'flat';return p.join(':');}
function viewerUrl(isAdmin){const url=isAdmin&&scope==='private'?admin?.viewerUrl:info?.viewerUrl;if(!url)return null;const privateView=isAdmin&&scope==='private';const mode=privateView?camera:cameraMode(camera,!!info?.perspective);return url+'?v='+(info?.publishedAt||0)+(info?.perspective?'p':'f')+(info?.firstPerson?'1':'0')+'#'+(privateView?'admin_':'public_')+dimension+mode;}
function rememberCamera(){try{const hash=document.getElementById('production-map-frame')?.contentWindow.location.hash;if(hash&&hash.includes(':'))camera=hash.slice(hash.indexOf(':'));}catch{}}
function stateHtml(){const j=admin?.job;return '<div class="production-map-state" role="status" aria-live="polite">'+(j?M.pill(labels[j.status]||j.status,j.status==='completed'?'green':j.status==='failed'?'red':''):'Обновление ещё не запускалось')+(j?.error?'<span>'+E(errors[j.error]||j.error)+'</span>':'')+'</div><dl class="detail-specs"><div><dt>Последняя публикация</dt><dd>'+E(date(info?.publishedAt))+'</dd></div><div><dt>Следующее по расписанию</dt><dd>'+E(admin?.settings?.autoRefresh?date(admin.nextScheduledAt):'Расписание выключено')+'</dd></div></dl>';}
function settingsHtml(){const c=admin?.settings||{};return '<section class="panel production-map-settings mt"><h2>Публикация и обновление</h2><p class="hint mt12">Сайт переключается на новый снимок только после успешной проверки. До этого доступна предыдущая карта.</p><form data-form="v6-map-settings"><div class="v6-form-grid three"><label class="check-row"><input type="checkbox" name="enabled" '+(c.enabled!==false?'checked':'')+'>Показывать публичную карту</label><label class="check-row"><input type="checkbox" name="autoRefresh" '+(c.autoRefresh?'checked':'')+'>Обновлять по расписанию</label><label class="check-row"><input type="checkbox" name="perspective" '+(c.perspective?'checked':'')+'>Разрешить 3D-обзор (перспектива)</label><label class="check-row"><input type="checkbox" name="firstPerson" '+(c.firstPerson?'checked':'')+'>Разрешить вид от первого лица</label><label class="check-row"><input type="checkbox" disabled>Метки игроков отключены</label>'+V.field('Интервал публикации, минуты','intervalMinutes',c.intervalMinutes||720,'number','required min="60" max="10080"')+V.field('Задержка публикации, минуты','minAgeMinutes',c.minAgeMinutes||0,'number','required min="0" max="1440"')+'</div>'+V.field('Причина изменения','reason','','text','required minlength="5" maxlength="500"')+V.actions('Сохранить настройки')+'</form><p class="hint">Метки останутся выключены до проверки приватности, vanish и задержки позиций в Minecraft.</p></section>';}
function view(isAdmin){
 const url=viewerUrl(isAdmin),title=isAdmin?'Карта сервера':'Карта мира';
 return '<div class="v6-map-page"><div class="section-head"><div><div class="kicker">Мир CopiMine</div><h1>'+title+'</h1><p class="muted mt12">'+(isAdmin?'Полная карта сохранённых чанков и публикация для игроков.':'Общая карта освоенных территорий сервера.')+'</p></div></div>'+(error?'<div class="notice" role="alert">'+E(error)+' '+btn('Повторить','production-map-retry','refresh','small')+'</div>':'')+'<div class="production-map-controls">'+(isAdmin?'<div class="tabs">'+[['private','Полная · администратор'],['public','Как видят игроки']].map(([id,label])=>btn(label,'production-map-scope','map',scope===id?'active':'','data-scope="'+id+'" aria-pressed="'+(scope===id)+'"')).join('')+'</div>':'<p class="hint">Обычный мир · Незер · Энд</p>')+'<div class="tabs" aria-label="Измерение">'+[['overworld','Обычный мир'],['nether','Незер'],['end','Энд']].map(([id,name])=>btn(name,'production-map-dimension','map',dimension===id?'active':'','data-dimension="'+id+'" aria-pressed="'+(dimension===id)+'"')).join('')+'</div>'+btn('На весь экран','v6-map-fullscreen','expand','ghost')+'</div><div class="v6-map-layout"><section class="v6-map-main"><div class="production-map-stage" id="production-map-stage">'+(url?'<iframe class="production-map-frame" id="production-map-frame" src="'+E(url)+'" title="BlueMap — '+(isAdmin&&scope==='private'?'полная карта':'освоенные территории')+'" allow="fullscreen" referrerpolicy="same-origin"></iframe>':'<div class="v6-map-empty"><h2>'+(!loaded?'Загружаем карту…':info?.enabled===false&&!isAdmin?'Карта временно скрыта':'Карта ещё не опубликована')+'</h2><p>'+(isAdmin?'Запустите обновление. На сайт попадут только проверенные файлы BlueMap.':'Снимок появится после публикации администратором.')+'</p></div>')+'</div><p class="production-map-caption">Масштаб, перемещение, координаты и выбор измерения — в панели BlueMap. На телефоне карта работает с касаниями.</p></section><aside class="panel v6-map-sidebar"><h2>'+(isAdmin&&scope==='private'?'Полная карта':'Освоенные территории')+'</h2><p class="hint mt12">'+(isAdmin&&scope==='private'?'Здесь видны все уже сохранённые чанки. Доступ проверяется для каждого файла карты.':'Показываются чанки, где накопилось заданное время игры. Это фильтр по чанкам, а не точная карта перемещений.')+'</p><dl class="detail-specs mt">'+(info?.dimensions||[]).map(d=>'<div><dt>'+E(d.name)+'</dt><dd>'+M.pill(d.available?'Подключено':'Нет публикации',d.available?'green':'')+'</dd></div>').join('')+'</dl><p class="hint mt">В новом мире ещё может не быть чанков. Карта пополняется после обычного исследования игроками.</p>'+(isAdmin?'<div id="production-map-job">'+stateHtml()+'</div>'+btn(activeJob()?'Обновление выполняется':'Обновить карту сейчас','v6-map-refresh','refresh','primary wide mt',activeJob()?'disabled':''):'<p class="hint mt">Опубликовано: <span id="production-map-time">'+E(date(info?.publishedAt))+'</span></p>')+'</aside></div>'+(isAdmin?settingsHtml():'')+'</div>';
}
async function refresh(force=false){
 if(busy)return;busy=true;
 const oldUrl=viewerUrl(M.UI.page==='admin'),first=!loaded;
 try{info=await X.request('/map');if(M.UI.page==='admin'&&M.UI.tab==='world')admin=await X.request('/admin/map');error='';loaded=true;
  const url=viewerUrl(M.UI.page==='admin');
  if(first||force||url!==oldUrl)M.render();
  else{const node=document.getElementById('production-map-job');if(node)node.innerHTML=stateHtml();const refresh=document.querySelector('[data-action="v6-map-refresh"]');if(refresh){refresh.disabled=!!activeJob();refresh.textContent=activeJob()?'Обновление выполняется':'Обновить карту сейчас';}}
 }catch(e){error=e.message;loaded=true;if(first||force)M.render();}finally{busy=false;}
}
M.renderers.map=()=>view(false);W.adminExtensions.world=()=>view(true);
X.refreshMap=refresh;
window.CMBlueMap={state:()=>({info,loaded,error,dimension,viewerUrl:viewerUrl(false)})};
H['production-map-dimension']=b=>{rememberCamera();dimension=['overworld','nether','end'].includes(b.dataset.dimension)?b.dataset.dimension:'overworld';M.render();};
H['production-map-scope']=b=>{rememberCamera();scope=b.dataset.scope==='private'?'private':'public';M.render();};
H['production-map-retry']=()=>refresh(true);
H['v6-map-fullscreen']=async()=>{const n=document.getElementById('production-map-stage');if(document.fullscreenElement)await document.exitFullscreen();else if(n?.requestFullscreen)await n.requestFullscreen();else M.toast('Этот браузер не поддерживает полноэкранный режим.');};
H['v6-map-refresh']=()=>M.openModal('Обновить карту','<p>Ручное обновление работает и при выключенном расписании. Предыдущая карта останется доступна во время обработки.</p><form data-form="production-map-refresh">'+V.field('Причина','reason','Ручное обновление карты','text','required minlength="5" maxlength="500"')+V.actions('Поставить в очередь')+'</form>');
F['production-map-refresh']=async(f,d)=>{const r=await X.request('/admin/map/refresh',{method:'POST',body:{reason:d.get('reason'),key:f.dataset.key||(f.dataset.key=X.uid('map'))}});M.closeModal();M.toast(r.message);await refresh(true);};
F['v6-map-settings']=async(f,d)=>{await X.request('/admin/map/settings',{method:'POST',body:{enabled:!!d.get('enabled'),autoRefresh:!!d.get('autoRefresh'),perspective:!!d.get('perspective'),firstPerson:!!d.get('firstPerson'),intervalMinutes:Number(d.get('intervalMinutes')),minAgeMinutes:Number(d.get('minAgeMinutes')),showPlayers:false,reason:d.get('reason')}});await refresh(true);M.toast('Настройки карты сохранены.');};
V.after.push((page,tab)=>{
 clearInterval(timer);timer=null;
  if(page==='home'&&!loaded){if(!busy)void refresh();return;}
 if(page==='map'||page==='admin'&&tab==='world'){
  if(!busy)void refresh();
  timer=setInterval(()=>{if(!document.hidden)void refresh();},5000);
 }
});
})();

/* assets/js/cms-production-v8.js *//* Live website editor. Drafts and publication are always server-owned. */
(function(){
'use strict';
const M=CM,V=CMV4,X=CM6,Q=CMReview,E=M.esc,H=M.handlers,F=M.forms,s=()=>M.state;
const previous=window.CMCMS.render;
const cache={owner:'',data:null,versions:null,settings:null,settingsVersion:'',loading:false,error:'',loadedAt:0};
const textField=(label,name,value,attrs='')=>V.field(label,name,value,'text',attrs);
const reasonField=()=>V.field('Причина изменения','reason','','text','required minlength="3" maxlength="500" placeholder="Например: исправил инструкцию"');
const note=(copy)=>`<div class="cm-cms-note">${icon('info')}<p>${copy}</p></div>`;
const failPanel=()=>`<section class="panel cm-cms-state"><h2>Не удалось загрузить содержимое</h2><p>${E(cache.error||'Проверь подключение и права на контент.')}</p>${M.btn('Повторить','cm-cms-retry','refresh','small')}</section>`;
function reload(){cache.loadedAt=0;cache.error='';M.render();}
async function load(force=false){
 const owner=Q.user?.id||'';if(owner!==cache.owner){cache.owner=owner;cache.data=null;cache.versions=null;cache.settings=null;cache.settingsVersion='';cache.loadedAt=0;}
 if(cache.loading||(!force&&cache.loadedAt&&Date.now()-cache.loadedAt<30000))return;
 cache.loading=true;cache.error='';
 try{const result=await X.request('/admin/content');if(owner!==Q.user?.id)return;cache.data=result.data;cache.versions=result.versions;cache.loadedAt=Date.now();}
 catch(error){cache.error=error.message;}
 finally{cache.loading=false;M.render();}
}
async function loadSettings(){
 const owner=Q.user?.id||'';if(owner!==cache.owner){cache.owner=owner;cache.data=null;cache.versions=null;cache.settings=null;cache.settingsVersion='';cache.loadedAt=0;}
 if(cache.settings||cache.loading)return;
 cache.loading=true;cache.error='';
 try{const result=await X.request('/admin/site-settings');if(owner!==Q.user?.id)return;cache.settings=result.data;cache.settingsVersion=result.version;}
 catch(error){cache.error=error.message;}
 finally{cache.loading=false;M.render();}
}
function publicPage(p){return typeof p.published==='object'?p.published:(p.publishedContent||null);}
function isPublished(p){return p.published===true||typeof p.published==='object'||!!p.publishedContent;}
function draftPage(p){return p.draft||publicPage(p)||{title:'',body:'',description:'',nav:false};}
function pageTabs(active=M.UI.params.get('sub')||'pages'){const settings=Q.user?.permissions?.includes('settings.manage');return `<div class="cm-cms-tabs" role="tablist" aria-label="Материалы сайта"><a href="#admin/content?sub=pages" class="${active==='pages'?'active':''}">Страницы</a><a href="#admin/content?sub=faq" class="${active==='faq'?'active':''}">Вопросы</a><a href="#admin/content?sub=gallery" class="${active==='gallery'?'active':''}">Галерея</a>${settings?`<a href="#admin/content?sub=settings" class="${active==='settings'?'active':''}">Главная и ссылки</a>`:''}</div>`;}
function pagesView(){
 const list=cache.data.pages||[],id=M.UI.params.get('id'),selected=list.find(p=>p.id===id)||list[0];
 if(!selected)return pageTabs()+`<section class="panel cm-cms-state"><h2>Страниц пока нет</h2><p>Создай первую страницу или проверь настройки содержимого.</p>${M.btn('Создать страницу','cm-cms-new-page','plus','primary')}</section>`;
 const draft=draftPage(selected),live=publicPage(selected);
 return pageTabs()+`<div class="cm-cms-layout"><aside class="panel cm-cms-list"><div class="cm-cms-list-head"><div><h2>Страницы</h2><p>${list.length} ${list.length===1?'материал':list.length<5?'материала':'материалов'}</p></div>${M.btn('Новая','cm-cms-new-page','plus','small')}</div><nav aria-label="Выбрать страницу">${list.map(p=>`<a href="#admin/content?sub=pages&id=${encodeURIComponent(p.id)}" class="cm-cms-page-link ${p.id===selected.id?'active':''}"><span>${icon('file')}<span><strong>${E(draftPage(p).title||p.slug)}</strong><small>${E(p.slug)}</small></span></span><i class="${isPublished(p)?'is-live':''}">${isPublished(p)?'На сайте':'Черновик'}</i></a>`).join('')}</nav></aside><section class="cm-cms-editor panel"><div class="cm-cms-editor-head"><div><span class="cm-cms-overline">/${E(selected.slug)}</span><h2>${E(draft.title||'Новая страница')}</h2><p>${live?'Опубликованный текст останется на сайте, пока не выйдет новая версия.':'Эту страницу увидят посетители после публикации.'}</p></div><span class="cm-cms-status ${live?'is-live':''}">${live?'Опубликована':'Черновик'}</span></div><form id="cm-cms-page-form"><input type="hidden" name="id" value="${E(selected.id)}"><div class="cm-cms-fields">${textField('Заголовок','title',draft.title,'required maxlength="100"')}${textField('Короткое описание','description',draft.description||'','maxlength="220"')}</div><label class="field cm-cms-body-field">Текст страницы<textarea name="body" rows="14" required maxlength="16000" aria-describedby="cm-cms-markdown-help">${E(draft.body)}</textarea></label><p id="cm-cms-markdown-help" class="cm-cms-help">Поддерживаются заголовки с #, списки с - и выделение **жирным**. HTML-код не принимается.</p><label class="cm-cms-checkbox"><input type="checkbox" name="nav" ${draft.nav?'checked':''}><span>Показывать ссылку в верхнем меню</span></label>${reasonField()}<div class="form-error cm-cms-error" role="alert"></div><div class="cm-cms-actions">${M.btn('Сохранить черновик','cm-cms-save-page','save','primary')}<span class="cm-cms-actions-note">${live?'На сайте останется текущая версия.':'Сайт пока не изменится.'}</span>${live?M.btn('Снять с сайта','cm-cms-unpublish-page','eye','ghost'):''}${M.btn('Опубликовать','cm-cms-publish-page','send',live?'ghost':'primary')}</div></form>${live?`<details class="cm-cms-preview"><summary>Текст на сайте</summary><article class="prose">${CMDomain.markdown(live.body||'')}</article></details>`:''}</section></div>`;
}
function faqView(){
 const list=cache.data.faq||[];
 return pageTabs()+`<section class="panel cm-cms-collection"><div class="cm-cms-collection-head"><div><h2>Частые вопросы</h2><p>На главной показываются только опубликованные ответы.</p></div>${M.btn('Добавить вопрос','cm-cms-edit-faq','plus','primary')}</div>${list.length?`<div class="cm-cms-faq-list">${list.map(q=>`<article><div><span class="cm-cms-status ${q.published?'is-live':''}">${q.published?'На сайте':'Скрыт'}</span><h3>${E(q.question)}</h3><p>${E(q.answer)}</p></div>${M.btn('Изменить','cm-cms-edit-faq','edit','small','data-id="'+E(q.id)+'"')}</article>`).join('')}</div>`:M.empty('Вопросов пока нет','Добавь ответ, который часто нужен игрокам.','message')}</section>`;
}
function galleryImageSrc(item){
 if(String(item.src||'').startsWith('/api/v6/gallery/'))return item.published?item.src:'/api/v6/admin/content/gallery/image/'+encodeURIComponent(item.id);
 return M.asset(item.src);
}
function galleryView(){
 const list=cache.data.gallery||[];
 return pageTabs()+`<section class="panel cm-cms-collection"><div class="cm-cms-collection-head"><div><h2>Галерея</h2><p>Подписи и публикация снимков на главной странице.</p></div>${M.btn('Загрузить изображение','cm-cms-upload-gallery','upload','primary')}</div>${note('Загруженные снимки хранятся закрыто, пока ты не опубликуешь их. Поддерживаются PNG, JPEG, WebP и GIF до 4 МБ.')}${list.length?`<div class="cm-cms-gallery">${list.map(g=>`<article><img src="${E(galleryImageSrc(g))}" alt="${E(g.alt)}" loading="lazy"><div><span class="cm-cms-status ${g.published?'is-live':''}">${g.published?'На сайте':'Скрыто'}</span><h3>${E(g.title)}</h3><p>${E(g.caption)}</p><span class="cm-cms-file">${E(g.src)}</span><div class="cm-cms-card-actions">${M.btn('Подпись','cm-cms-edit-gallery','edit','small','data-id="'+E(g.id)+'"')}${M.btn(g.published?'Скрыть':'Опубликовать','cm-cms-toggle-gallery','eye',g.published?'ghost small':'primary small','data-id="'+E(g.id)+'"')}</div></div></article>`).join('')}</div>`:M.empty('Изображений пока нет','Загрузи первый снимок в галерею.','image')}</section>`;
}
function settingsView(active='settings'){
 if(!Q.user?.permissions?.includes('settings.manage'))return pageTabs(active)+`<section class="panel cm-cms-state"><h2>Настройки сайта недоступны</h2><p>Изменять заголовок и ссылки может только владелец сайта.</p></section>`;
 if(!cache.settings){if(!cache.loading&&!cache.error)loadSettings();return cache.error?failPanel():pageTabs(active)+`<section class="panel cm-cms-state"><span class="cm-cms-spinner" aria-hidden="true"></span><p>Загружаем текст главной страницы…</p></section>`;}
 const c=cache.settings;
 return pageTabs(active)+`<div class="cm-cms-settings-grid"><section class="panel"><div class="cm-cms-collection-head"><div><h2>Первый экран</h2><p>Заголовок, короткое описание и данные для входа в игру.</p></div></div><form id="cm-cms-settings-form">${textField('Название сайта','siteTitle',c.siteTitle||'CopiMine','required maxlength="50"')}${V.area('Заголовок','headline',c.headline||'',3,'required maxlength="80"')}${V.area('Описание','description',c.description||'',3,'required maxlength="220"')}<div class="cm-cms-fields">${textField('Адрес сервера','serverIp',c.serverIp||'copimine.ru','required maxlength="253"')}${textField('Версия Minecraft','gameVersion',c.gameVersion||'26.3','required maxlength="24"')}</div>${V.field('Приглашение Discord','discordInvite',c.discordInvite||'','url','placeholder="https://discord.gg/…" maxlength="180"')}${reasonField()}<div class="form-error cm-cms-error" role="alert"></div><div class="cm-cms-actions">${M.btn('Сохранить','cm-cms-save-settings','save','primary')}<span class="cm-cms-actions-note">Параметры сохраняются на сервере.</span></div></form></section><aside class="panel cm-cms-settings-note"><h2>Как это увидят игроки</h2><div class="cm-cms-copy-preview"><span class="cm-cms-overline">Minecraft · ${E(c.siteTitle||'CopiMine')}</span><strong>${E(c.headline||'')}</strong><p>${E(c.description||'')}</p><span>${E(c.serverIp||'')}</span><small>Minecraft ${E(c.gameVersion||'')}</small></div><p>Проверь адрес сервера перед сохранением. Платёжные данные и секреты здесь не нужны.</p></aside></div>`;
}
function render(sub='pages'){
 if(!X.live)return previous(sub);
 if(!Q.user?.permissions?.includes('content.manage'))return cache.error?failPanel():`<section class="panel cm-cms-state"><h2>Нет доступа к содержимому</h2><p>Обратись к владельцу сайта, чтобы проверить свою роль.</p></section>`;
 if(cache.owner!==Q.user.id||!cache.data){if(!cache.loading&&!cache.error)load();return cache.error?failPanel():`<section class="panel cm-cms-state"><span class="cm-cms-spinner" aria-hidden="true"></span><p>Загружаем сохранённые материалы…</p></section>`;}
 return sub==='faq'?faqView():sub==='gallery'?galleryView():sub==='settings'?settingsView():pagesView();
}
window.CMCMS.render=render;
window.CMCMS.siteSettingsView=()=>settingsView('settings').replace(pageTabs('settings'),'');
const previousAdminContent=CM5.adminExtensions.content;
CM5.adminExtensions.content=sub=>X.live?render(sub||'pages'):previousAdminContent(sub);
H['cm-cms-retry']=()=>{cache.data=null;cache.settings=null;reload();};
function pageItem(form,old,action){
 const d=new FormData(form),draft={title:String(d.get('title')||'').trim(),body:String(d.get('body')||'').trim(),description:String(d.get('description')||'').trim(),nav:!!d.get('nav')};
 if(!draft.title||!draft.body)throw Error('Заполни заголовок и текст страницы.');
 return{id:old.id,slug:old.slug,draft,published:isPublished(old),...(action==='publish'?{publish:true}:action==='unpublish'?{unpublish:true}:{})};
}
async function persist(section,item,reason){
 if(String(reason||'').trim().length<3)throw Error('Укажи причину изменения.');
 const r=await X.request('/admin/content/'+section,{method:'PATCH',body:{item,reason:String(reason).trim(),expectedVersion:cache.versions[section]}});
 const rows=cache.data[section],i=rows.findIndex(x=>x.id===item.id);if(i<0)rows.push(r.item);else rows[i]=r.item;
 cache.versions[section]=r.version;cache.loadedAt=Date.now();syncPublic(section,r.item);return r.item;
}
function syncPublic(section,item){
 const rows=s()[section]||(s()[section]=[]),index=rows.findIndex(row=>row.id===item.id);let publicRow=null;
 if(section==='pages'){
  const content=item.published===true?item.publishedContent:typeof item.published==='object'?item.published:null;
  if(content)publicRow={id:item.id,slug:item.slug,published:content,publishedRevision:item.publishedRevision,publishedAt:item.publishedAt};
 }else if(item.published===true){
  publicRow=section==='gallery'?{id:item.id,src:item.src,title:item.title,caption:item.caption,alt:item.alt,position:item.position,published:true}:{id:item.id,question:item.question,answer:item.answer,published:true};
 }
 if(index>=0)rows.splice(index,1);
 if(publicRow)rows.push(publicRow);
}
async function savePage(action){
 const form=document.getElementById('cm-cms-page-form'),old=cache.data?.pages?.find(p=>p.id===new FormData(form||document.createElement('form')).get('id'));
 if(!form||!old)throw Error('Страница изменилась. Обнови редактор.');
 const reason=new FormData(form).get('reason');await persist('pages',pageItem(form,old,action),reason);
 if(action==='unpublish')M.toast('Страница снята с сайта.');else if(action==='publish')M.toast('Новая версия опубликована.');else M.toast('Черновик сохранён. На сайте осталась опубликованная версия.');
 M.render();
}
H['cm-cms-save-page']=()=>savePage('save');H['cm-cms-publish-page']=()=>savePage('publish');H['cm-cms-unpublish-page']=()=>savePage('unpublish');
H['cm-cms-new-page']=()=>M.openModal('Новая страница',`<form data-form="cm-cms-create-page">${textField('Заголовок','title','','required maxlength="100"')}${textField('Адрес страницы','slug','','required pattern="[a-z0-9][a-z0-9-]{1,39}" placeholder="about-us"')}<p class="cm-cms-help">Латинские буквы, цифры и дефис.</p><label class="field">Текст страницы<textarea name="body" rows="8" required maxlength="16000"></textarea></label>${reasonField()}<div class="form-error" role="alert"></div>${V.actions('Создать черновик')}</form>`);
F['cm-cms-create-page']=async(f,d)=>{
 const slug=String(d.get('slug')||'').trim(),title=String(d.get('title')||'').trim(),body=String(d.get('body')||'').trim();if(!/^[a-z0-9][a-z0-9-]{1,39}$/.test(slug))throw Error('Проверь адрес страницы: только латинские буквы, цифры и дефис.');
 const item={id:'page-'+slug,slug,published:false,draft:{title,body,description:'',nav:false}},r=await X.request('/admin/content/pages',{method:'PATCH',body:{item,reason:d.get('reason'),expectedVersion:cache.versions.pages}});
 cache.data.pages.push(r.item);cache.versions.pages=r.version;cache.loadedAt=Date.now();M.closeModal();M.navTo('admin/content?sub=pages&id='+encodeURIComponent(r.item.id));M.toast('Черновик создан.');
};
H['cm-cms-edit-faq']=b=>{
 const q=cache.data.faq.find(x=>x.id===b.dataset.id)||{id:'',question:'',answer:'',published:false};
 M.openModal(q.id?'Изменить вопрос':'Добавить вопрос',`<form data-form="cm-cms-save-faq"><input type="hidden" name="id" value="${E(q.id)}">${textField('Вопрос','question',q.question,'required maxlength="150"')}${V.area('Ответ','answer',q.answer,5,'required maxlength="1800"')}<label class="cm-cms-checkbox"><input type="checkbox" name="published" ${q.published?'checked':''}><span>Показывать на главной</span></label>${reasonField()}<div class="form-error" role="alert"></div>${V.actions('Сохранить')}</form>`);
};
F['cm-cms-save-faq']=async(f,d)=>{
 const id=String(d.get('id')||'')||'faq-'+(crypto.randomUUID?crypto.randomUUID():Date.now()),item={id,question:String(d.get('question')||'').trim(),answer:String(d.get('answer')||'').trim(),published:!!d.get('published')};
 await persist('faq',item,d.get('reason'));M.closeModal();M.render();M.toast('Ответ сохранён.');
};
H['cm-cms-edit-gallery']=b=>{
 const g=cache.data.gallery.find(x=>x.id===b.dataset.id);if(!g)return;
 M.openModal('Подпись изображения',`<form data-form="cm-cms-save-gallery"><input type="hidden" name="id" value="${E(g.id)}">${textField('Название','title',g.title,'required maxlength="80"')}${textField('Подпись','caption',g.caption||'','maxlength="180"')}${textField('Описание для экранного диктора','alt',g.alt,'required maxlength="200"')}<label class="field">Порядок показа<input name="position" type="number" min="0" max="1000" step="1" value="${Number(g.position)||0}" required></label><p class="cm-cms-file">${E(g.src)}</p>${reasonField()}<div class="form-error" role="alert"></div>${V.actions('Сохранить')}</form>`);
};
F['cm-cms-save-gallery']=async(f,d)=>{
 const old=cache.data.gallery.find(x=>x.id===d.get('id'));if(!old)throw Error('Изображение уже удалено.');
 const item={...old,title:String(d.get('title')||'').trim(),caption:String(d.get('caption')||'').trim(),alt:String(d.get('alt')||'').trim(),position:Number(d.get('position'))};
 await persist('gallery',item,d.get('reason'));M.closeModal();M.render();M.toast('Описание изображения сохранено.');
};
 H['cm-cms-upload-gallery']=()=>M.openModal('Загрузить изображение',`<form data-form="cm-cms-upload-gallery"><label class="field">Файл изображения<input type="file" name="image" data-cm-gallery-upload accept="image/png,image/jpeg,image/webp,image/gif" required></label><p class="cm-cms-help">PNG, JPEG, WebP или GIF. Не больше 4 МБ и 8 000 × 8 000 пикселей. Файл сохраняется в WebP, у анимированного GIF берётся первый кадр.</p>${textField('Название','title','','required maxlength="80"')}${textField('Подпись','caption','','maxlength="180"')}${textField('Описание для экранного диктора','alt','','required maxlength="200"')}<label class="field">Порядок показа<input name="position" type="number" min="0" max="1000" step="1" value="0" required></label><label class="cm-cms-checkbox"><input type="checkbox" name="published"><span>Опубликовать сразу</span></label>${reasonField()}<div class="form-error" role="alert"></div>${V.actions('Загрузить')}</form>`);
function readGalleryFile(file){
 if(!file)throw Error('Выбери файл изображения.');
 if(file.size>4*1024*1024)throw Error('Размер файла не должен превышать 4 МБ.');
 if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Поддерживаются PNG, JPEG, WebP и GIF.');
 return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Не удалось прочитать файл.'));reader.onload=()=>{const value=String(reader.result||'');const comma=value.indexOf(',');if(comma<0)return reject(Error('Не удалось прочитать изображение.'));resolve(value.slice(comma+1));};reader.readAsDataURL(file);});
}
F['cm-cms-upload-gallery']=async(f,d)=>{
 const file=f.querySelector('[name="image"]')?.files?.[0],image=await readGalleryFile(file),reason=String(d.get('reason')||'').trim();
 if(reason.length<3)throw Error('Укажи причину изменения.');
 const r=await X.request('/admin/content/gallery/image',{method:'POST',body:{image,title:String(d.get('title')||'').trim(),caption:String(d.get('caption')||'').trim(),alt:String(d.get('alt')||'').trim(),position:Number(d.get('position')),published:!!d.get('published'),reason,expectedVersion:cache.versions.gallery}});
 cache.data.gallery.push(r.item);cache.data.gallery.sort((a,b)=>(a.position||0)-(b.position||0));cache.versions.gallery=r.version;cache.loadedAt=Date.now();syncPublic('gallery',r.item);M.closeModal();M.render();M.toast(r.item.published?'Изображение загружено и опубликовано.':'Изображение загружено. Теперь его можно опубликовать.');
};
H['cm-cms-toggle-gallery']=async b=>{
 const old=cache.data.gallery.find(x=>x.id===b.dataset.id);if(!old)return;
 M.openModal(old.published?'Скрыть изображение?':'Опубликовать изображение?',`<p>${E(old.title)} будет ${old.published?'скрыто':'показано'} на главной странице.</p><form data-form="cm-cms-toggle-gallery"><input type="hidden" name="id" value="${E(old.id)}"><input type="hidden" name="published" value="${old.published?'0':'1'}">${reasonField()}<div class="form-error" role="alert"></div>${V.actions(old.published?'Скрыть':'Опубликовать')}</form>`);
};
F['cm-cms-toggle-gallery']=async(f,d)=>{const old=cache.data.gallery.find(x=>x.id===d.get('id'));if(!old)throw Error('Изображение уже удалено.');await persist('gallery',{...old,published:d.get('published')==='1'},d.get('reason'));M.closeModal();M.render();M.toast('Видимость изображения обновлена.');};
H['cm-cms-save-settings']=async()=>{
 const form=document.getElementById('cm-cms-settings-form');if(!form)throw Error('Форма уже закрыта.');const d=new FormData(form),values={};for(const k of ['siteTitle','headline','description','serverIp','gameVersion','discordInvite'])values[k]=String(d.get(k)||'').trim();if(values.headline.length<1||values.description.length<1)throw Error('Заполни заголовок и описание.');if(!cache.settingsVersion)throw Error('Настройки не загружены. Обнови раздел.');
 const r=await X.request('/admin/site-settings',{method:'PATCH',body:{values,reason:d.get('reason'),expectedVersion:cache.settingsVersion}});cache.settings=r.data;cache.settingsVersion=r.version;Object.assign(s().config,r.data);M.render();M.toast('Тексты сайта сохранены.');
};
V.after.push((page,tab)=>{
 if(page!=='admin'||tab!=='content'||!X.live)return;
 const sub=M.UI.params.get('sub')||'pages';
 if(sub==='settings'&&!cache.settings&&!cache.loading&&!cache.error)loadSettings();
 else if(sub!=='settings'&&!cache.data&&!cache.loading&&!cache.error)load();
});
function renderPublicContentPage(slug){
 const row=(s().pages||[]).find(item=>item?.slug===slug&&item.published&&typeof item.published==='object');
 if(!row)return `<div class="page-head"><div><h1>Страница не найдена</h1><p>Этот материал не опубликован или был удалён.</p></div></div>${M.link('На главную','#home','arrow-left','ghost small')}`;
 const published=row.published;
 return `<div class="page-head"><div><h1>${E(published.title||'Информация')}</h1>${published.description?`<p>${E(published.description)}</p>`:''}</div></div><article class="panel cm-public-page help-copy">${CMDomain.markdown(published.body||'')}</article>`;
}
M.renderers.rules=()=>renderPublicContentPage('rules');
M.renderers.privacy=()=>`<div class="page-head"><div><span class="kicker">Документы</span><h1>Политика конфиденциальности</h1><p>Как CopiMine обращается с данными посетителей и игроков. Версия от 27 октября 2026 года.</p></div></div><article class="panel cm-public-page cm-legal">
<p>Эта политика описывает, какие данные получает сайт copimine.ru, зачем они нужны, сколько хранятся и как ты можешь управлять своим выбором. Мы собираем минимум данных: всё, что можно посчитать обезличенно, считается обезличенно.</p>
<h2>1. Кто отвечает за обработку</h2>
<p>Сайт copimine.ru администрирует команда проекта CopiMine. Вопросы о данных, доступе, исправлении и удалении принимаются через раздел «Помощь» в личном кабинете и через Discord-сервер проекта. Почтовый домен пока не подключён, поэтому переписка ведётся в этих каналах.</p>
<h2>2. Какие данные мы обрабатываем</h2>
<ul>
<li><strong>Аккаунт:</strong> логин сайта, отображаемое имя, почта, хэш пароля, роль, привязка Minecraft, даты создания и последнего входа, настройки интерфейса.</li>
<li><strong>Безопасность:</strong> сессии входа, время создания и срок действия, IP-адрес и user-agent на момент входа, журнал действий администрации.</li>
<li><strong>Покупки и баланс:</strong> заказы, выданные предметы, балансы AR и CM, история переводов, обращения в поддержку. Платёжный сервис пока не подключён, поэтому данные банковских карт сайт не получает и не хранит.</li>
<li><strong>Статистика сайта:</strong> просмотры публичных страниц, действия в магазине, тип устройства, браузер, операционная система, язык, размер экрана, домен предыдущей страницы и utm-метки. Подробный состав указан ниже.</li>
<li><strong>Согласие на cookie:</strong> какие категории разрешены, время выбора, версия политики, источник выбора и строка браузера.</li>
</ul>
<p>Мы не собираем в статистике IP-адрес, точное местоположение, содержимое полей форм, поисковые запросы, имена игроков и данные других сайтов.</p>
<h2>3. Cookie и локальное хранилище</h2>
<div class="cm-legal-table"><table>
<thead><tr><th>Название</th><th>Категория</th><th>Зачем</th><th>Срок</th></tr></thead>
<tbody>
<tr><td><code>cm_site_session</code></td><td>Обязательные</td><td>Вход в аккаунт и защита запросов</td><td>12 часов или 30 дней, если включено «Оставаться в аккаунте»</td></tr>
<tr><td><code>cm_site_anon</code></td><td>Обязательные</td><td>Защита форм до входа</td><td>24 часа</td></tr>
<tr><td><code>cm_consent</code></td><td>Обязательные</td><td>Твой выбор категорий cookie</td><td>1 год</td></tr>
<tr><td><code>cm_consent_id</code></td><td>Обязательные</td><td>Номер записи о согласии</td><td>1 год</td></tr>
<tr><td><code>cm_visitor</code></td><td>Аналитика</td><td>Случайный псевдоним посетителя для подсчёта уникальных и вернувшихся</td><td>1 год</td></tr>
<tr><td><code>localStorage: copimine.consent.v2</code></td><td>Обязательные</td><td>Копия выбора cookie в браузере</td><td>1 год</td></tr>
<tr><td><code>localStorage: copimine.*</code></td><td>Настройки</td><td>Тема, анимации, корзина, последние разделы</td><td>До очистки данных сайта</td></tr>
</tbody>
</table></div>
<p>Корзина хранится в браузере и не передаётся на сервер до оформления заказа. Отключить аналитику и настройки можно в любой момент через кнопку «Настройки cookies» в подвале сайта. После отказа удаляется псевдоним <code>cm_visitor</code> и очередь неотправленных событий.</p>
<h2>4. Что именно попадает в статистику</h2>
<div class="cm-legal-table"><table>
<thead><tr><th>Поле</th><th>Пример</th><th>Зачем</th></tr></thead>
<tbody>
<tr><td>Страница</td><td>home, shop, cart, donate, map, rules, support</td><td>Понимать, какие разделы нужны людям</td></tr>
<tr><td>Событие</td><td>page_view, product_view, add_to_cart</td><td>Улучшать каталог и оформление</td></tr>
<tr><td>Предмет и количество</td><td>arena_pass, 1</td><td>Понимать спрос без привязки к аккаунту</td></tr>
<tr><td>Время</td><td>дата и время в UTC</td><td>Строить отчёты по дням</td></tr>
<tr><td>Псевдоним посетителя</td><td>случайный идентификатор в cookie</td><td>Считать уникальных и вернувшихся</td></tr>
<tr><td>Сеанс</td><td>случайный идентификатор вкладки</td><td>Считать глубину визита</td></tr>
<tr><td>Устройство</td><td>компьютер, телефон, планшет</td><td>Проверять адаптивность</td></tr>
<tr><td>Браузер и система</td><td>Chrome, Firefox; Windows, Android</td><td>Исправлять совместимость</td></tr>
<tr><td>Язык и экран</td><td>ru-RU; 1920x1080</td><td>Проверять вёрстку и тексты</td></tr>
<tr><td>Источник</td><td>домен предыдущей страницы, utm_source, utm_medium, utm_campaign</td><td>Оценивать эффективность ссылок</td></tr>
</tbody>
</table></div>
<p>Идентификатор посетителя на сервере хранится только как необратимый хэш. По нему нельзя восстановить имя, почту или IP-адрес. Статистика принимается только при явном согласии и не связывает просмотры с аккаунтом.</p>
<h2>5. Зачем мы это делаем</h2>
<ul>
<li>Вход, защита аккаунта, покупки и поддержка — исполнение соглашения с пользователем.</li>
<li>Статистика посещений и настройки интерфейса — твоё согласие, которое можно отозвать.</li>
<li>Журналы безопасности и аудит действий администрации — защита сайта и законные требования.</li>
<li>Ответы на обращения и исправление ошибок — законный интерес в поддержке проекта.</li>
</ul>
<h2>6. Сколько храним</h2>
<ul>
<li>События статистики — до 400 дней, затем удаляются автоматически.</li>
<li>Записи о согласии — 3 года, чтобы подтвердить выбор или его отзыв.</li>
<li>Сессии входа — 12 часов, с «Оставаться в аккаунте» — 30 дней; отозванные сессии не действуют.</li>
<li>Аккаунт, покупки и обращения — пока существует аккаунт и пока это нужно для расчётов и защиты.</li>
<li>Локальные настройки и cookie — до истечения срока или очистки данных сайта в браузере.</li>
</ul>
<h2>7. Кому передаём</h2>
<p>Данные не продаются и не передаются рекламным сетям. Доступ к серверу имеют только администраторы проекта. Хостинг-провайдер обрабатывает технические данные для работы сервера. Если платёжный сервис будет подключён, данные платежа будет обрабатывать выбранный провайдер по своим правилам — об этом появится отдельное уведомление.</p>
<h2>8. Твои права</h2>
<ul>
<li>Узнать, какие данные о тебе хранятся, и получить копию.</li>
<li>Исправить неточные данные в настройках аккаунта или через поддержку.</li>
<li>Удалить аккаунт и связанные данные, если нет законных оснований их хранить.</li>
<li>Отозвать согласие на аналитику и настройки в любой момент.</li>
<li>Обратиться с жалобой в уполномоченный орган по защите прав субъектов персональных данных.</li>
</ul>
<p>Запросы обрабатываются через раздел «Помощь» в личном кабинете или Discord. Мы отвечаем в разумный срок и можем попросить подтвердить, что запрос исходит от владельца аккаунта.</p>
<div class="cm-legal-actions">${M.btn('Настройки cookies','v6-cookies','settings','ghost')}${M.link('Мои данные и удаление аккаунта','#settings/privacy','arrow-right','ghost')}</div>
<h2>9. Безопасность</h2>
<p>Сайт работает по HTTPS. Пароли хранятся только в виде стойкого хэша, сессионные cookie помечены HttpOnly и SameSite, идентификаторы статистики хэшируются на сервере. Доступ администраторов ограничен ролями и записывается в журнал.</p>
<h2>10. Дети</h2>
<p>Сайт не предназначен для детей младше 13 лет. Если аккаунт создан ребёнком, данные обрабатываются только с согласия законного представителя.</p>
<h2>11. Изменения политики</h2>
<p>Актуальная версия всегда доступна по адресу <a href="#privacy">copimine.ru/#privacy</a>. Дата версии указана в начале страницы. Существенные изменения отражаются в тексте и, когда это требуется, сопровождаются новым запросом согласия.</p>
<h2>12. Контакты</h2>
<p>Поддержка: раздел «Помощь» в личном кабинете. Сообщество: Discord-сервер CopiMine. Для вопросов о данных укажи логин сайта и суть запроса — так мы быстрее найдём нужные записи.</p>
</article>`;
M.renderers.page=slug=>renderPublicContentPage(slug);
})();

/* assets/js/ux-v8.js *//* Session-only route state and navigation restoration for the production UI. */
(function () {
  'use strict';
  const M = window.CM;
  if (!M?.UI) return;

  const KEY = 'copimine.site.route-state.v1';
  const currentRoute = () => location.hash.slice(1) || 'home';
  let scrollTimer, controlTimer;
  let pendingRestoreRoute = '';

  function readAll() {
    try {
      const value = JSON.parse(sessionStorage.getItem(KEY) || '{}');
      return value && typeof value === 'object' ? value : {};
    } catch { return {}; }
  }

  function matches(node) {
    if (node.matches('input[type="search"],input[id*="search" i],input[name*="search" i],.search-box input')) return true;
    if (!(node instanceof HTMLSelectElement)) return false;
    const key = `${node.id} ${node.name}`.toLowerCase();
    return /sort|filter|scope|currency|category/.test(key) || Boolean(node.closest('.filter-nav,.v71-history-filters,.v71-directory-controls,[aria-label*="Фильтр"]'));
  }

  function captureControls() {
    const root = document.getElementById('view');
    if (!root) return [];
    const matchesList = [...root.querySelectorAll('input[type="search"],input[id*="search" i],input[name*="search" i],.search-box input,select')].filter(matches);
    const fields = matchesList.map((node, index) => ({
      id: node.id || '',
      name: node.name || '',
      index,
      value: String(node.value || '').slice(0, 500),
    }));
    const filterGroups = [...root.querySelectorAll('.filter-nav,#currency-nav,.v71-history-filters,.v71-action-categories,[role="group"][aria-label*="Фильтр"],.v6-filter-bar')];
    const buttons = filterGroups.flatMap((group, groupIndex) => {
      const selected = group.querySelector('button[aria-pressed="true"],button.active');
      return selected ? [{ groupIndex, action: selected.dataset.action || '', key: selected.dataset.key || '', id: selected.dataset.id || '', unit: selected.dataset.unit || '', category: selected.dataset.category || '', value: selected.dataset.value || '' }] : [];
    });
    return { fields, buttons };
  }

  function save(route = currentRoute()) {
    try {
      const state = readAll();
      state[route] = {
        y: Math.max(0, Math.round(window.scrollY)),
        adminY: Math.max(0, Math.round(document.querySelector('.v71-admin-nav')?.scrollTop || 0)),
        controls: captureControls(),
      };
      const keys = Object.keys(state);
      for (const stale of keys.slice(0, Math.max(0, keys.length - 20))) delete state[stale];
      sessionStorage.setItem(KEY, JSON.stringify(state));
    } catch { /* Route restoration is a convenience and must never block navigation. */ }
  }

  function scheduleSave() {
    clearTimeout(controlTimer);
    controlTimer = setTimeout(() => save(), 0);
  }

  function restore(route = currentRoute()) {
    const saved = readAll()[route];
    if (!saved) {
      if (pendingRestoreRoute === route) pendingRestoreRoute = '';
      return;
    }
    const root = document.getElementById('view');
    if (!root) return;
    const nodes = [...root.querySelectorAll('input[type="search"],input[id*="search" i],input[name*="search" i],.search-box input,select')].filter(matches);
    const fields = Array.isArray(saved.controls) ? saved.controls : saved.controls?.fields || [];
    for (const entry of fields) {
      const node = entry.id
        ? nodes.find(item => item.id === entry.id)
        : nodes.filter(item => item.name === entry.name)[entry.index];
      if (!node) continue;
      if (node instanceof HTMLSelectElement && ![...node.options].some(option => option.value === entry.value)) continue;
      if (node.value === entry.value) continue;
      node.value = entry.value;
      node.dispatchEvent(new Event(node instanceof HTMLSelectElement ? 'change' : 'input', { bubbles: true }));
    }
    const filterGroups = [...root.querySelectorAll('.filter-nav,#currency-nav,.v71-history-filters,.v71-action-categories,[role="group"][aria-label*="Фильтр"],.v6-filter-bar')];
    for (const entry of saved.controls?.buttons || []) {
      const group = filterGroups[entry.groupIndex];
      const button = group && [...group.querySelectorAll('button')].find(item =>
        !(item.getAttribute('aria-pressed') === 'true' || item.classList.contains('active')) &&
        (item.dataset.action || '') === entry.action && (item.dataset.key || '') === entry.key && (item.dataset.id || '') === entry.id && (item.dataset.unit || '') === entry.unit && (item.dataset.category || '') === entry.category && (item.dataset.value || '') === entry.value
      );
      button?.click();
    }
    const adminNav = document.querySelector('.v71-admin-nav');
    if (adminNav && Number.isFinite(saved.adminY)) adminNav.scrollTop = saved.adminY;
    requestAnimationFrame(() => {
      window.scrollTo({ top: Number(saved.y) || 0, behavior: 'instant' });
      if (pendingRestoreRoute === route) pendingRestoreRoute = '';
    });
  }

  document.addEventListener('click', event => {
    const anchor = event.target.closest('a[href^="#"]');
    if (anchor && anchor.getAttribute('href') !== `#${currentRoute()}`) save();
    if (event.target.closest('.filter-nav button,#currency-nav button,.v71-history-filters button,.v71-action-categories button,[role="group"][aria-label*="Фильтр"] button,.v6-filter-bar button')) scheduleSave();
  }, true);

  document.addEventListener('input', event => { if (matches(event.target)) scheduleSave(); }, true);
  document.addEventListener('change', event => { if (matches(event.target)) scheduleSave(); }, true);

  window.addEventListener('scroll', () => {
    clearTimeout(scrollTimer);
    scrollTimer = setTimeout(() => save(), 140);
  }, { passive: true });

  window.addEventListener('hashchange', () => requestAnimationFrame(() => restore()));
  window.addEventListener('beforeunload', () => save());

  const originalRender = M.render;
  if (typeof originalRender === 'function') {
    M.render = function (...args) {
      const route = currentRoute();
      const previousRoute = M.UI.renderedRoute || route;
      const hasView = Boolean(document.getElementById('view'));
      const enteringRoute = !hasView || previousRoute !== route;
      if (enteringRoute) pendingRestoreRoute = route;
      if (hasView && pendingRestoreRoute !== previousRoute) save(previousRoute);
      const result = originalRender.apply(this, args);
      requestAnimationFrame(() => restore(route));
      return result;
    };
  }

  const originalNavigate = M.navTo;
  if (typeof originalNavigate === 'function') {
    M.navTo = function (path) {
      save();
      const result = originalNavigate.call(this, path);
      if (`#${path}` === location.hash) requestAnimationFrame(() => restore());
      return result;
    };
  }

  document.addEventListener('DOMContentLoaded', () => requestAnimationFrame(() => restore()), { once: true });
})();

/* assets/js/account-v9.js *//* Account, FAQ and support workflows backed by the production API. */
(function () {
  'use strict';

  const M = window.CM, V = window.CMV4, Q = window.CMReview, A = window.CM71 || {}, W = window.CM5 || {};
  if (!M || !V || !Q) return;
  const R = M.renderers, F = M.forms, H = M.handlers, E = M.esc, state = () => M.state;
  const oldSettings = R.settings, oldPage = R.page, oldAccount = R.account;
  const authReturnKey = 'copimine.auth.return.v1';
  const pendingLinkKey = 'copimine.minecraft-link.pending.v1';
  const linkedCabinetKey = 'copimine.minecraft-link.complete.v1';
  let minecraftPoll = 0, pendingMinecraftLink = null;

  const currentAccountUser = () => Q.user || M.me() || null;
  function syncLinkedUser(user) {
    if (!user?.id || !user.gameLinkVerified) return;
    Q.user = user;
    const players = state().players || (state().players = []);
    let player = players.find(item => item.id === user.id);
    if (!player) {
      player = { id: user.id, name: user.name, AR: null, CM: null, role: 'Игрок', status: 'active', purchaseLimits: [] };
      players.push(player);
    }
    Object.assign(player, {
      name: user.name,
      displayName: user.displayName || user.name,
      minecraftName: user.minecraftName,
      minecraftUuid: user.minecraftUuid,
      gameUuid: user.gameUUID || user.minecraftUuid,
      gameLinkVerified: true,
      linked: true
    });
    state().session = { ...(state().session || {}), id: user.id };
  }
  function loadPendingLink(user) {
    if (!user?.id || user.gameLinkVerified) return null;
    try {
      const saved = JSON.parse(sessionStorage.getItem(pendingLinkKey) || 'null');
      if (saved?.userId === user.id && /^[A-Za-z0-9_]{3,16}$/.test(saved.name || '') && Number.isFinite(Number(saved.expiresAt))) {
        return { name: saved.name, expiresAt: Number(saved.expiresAt), userId: user.id };
      }
      if (saved) sessionStorage.removeItem(pendingLinkKey);
    } catch { /* The saved step is optional; the player can request another code. */ }
    return null;
  }
  function savePendingLink(user, pending) {
    if (!user?.id || !pending) return;
    pendingMinecraftLink = { ...pending, userId: user.id };
    try { sessionStorage.setItem(pendingLinkKey, JSON.stringify(pendingMinecraftLink)); } catch { /* The flow still works without session storage. */ }
  }
  function clearPendingLink() {
    pendingMinecraftLink = null;
    try { sessionStorage.removeItem(pendingLinkKey); } catch { /* Optional state. */ }
  }
  function motionEnabled() { return document.documentElement.dataset.motion !== 'off'; }
  function animateLinkStep() {
    requestAnimationFrame(() => window.CMSiteMotion?.linkStep?.(document.querySelector('[data-link-panel]'), motionEnabled()));
  }
  function finishLinkTransition() {
    return new Promise(resolve => {
      const root = document.querySelector('[data-link-gate]');
      const complete = () => resolve();
      if (root && window.CMSiteMotion?.completeLink) window.CMSiteMotion.completeLink(root, complete, motionEnabled());
      else complete();
    });
  }
  async function openLinkedCabinet() {
    await finishLinkTransition();
    try { sessionStorage.setItem(linkedCabinetKey, '1'); } catch { /* Animation is optional. */ }
    M.toast('Minecraft привязан.');
    M.navTo('account');
  }
  const previousLogoutCommit = H['logout-commit'];
  H['logout-commit'] = async (...args) => {
    stopMinecraftPoll(); clearPendingLink();
    try { sessionStorage.removeItem(linkedCabinetKey); } catch { /* Optional state. */ }
    return previousLogoutCommit?.(...args);
  };

async function api(path, body, method) {
    const headers = { Accept: 'application/json' };
    const options = { method: method || (body === undefined ? 'GET' : 'POST'), credentials: 'same-origin', headers };
    if (body !== undefined) {
      headers['Content-Type'] = 'application/json';
      headers['X-CSRF-Token'] = Q.csrf;
      options.body = JSON.stringify(body);
    }
    const response = await fetch('/api/v6/' + path, options);
    const result = await response.json();
    if (!response.ok) throw Error(result.error?.message || result.message || 'Не удалось выполнить запрос.');
    return result;
  }

  // Файл уходит base64 в JSON: сервер проверяет тип, размер и антивирус.
  async function uploadAttachment(form, id) {
    const input = form.querySelector('input[type="file"][data-ticket-file]');
    const file = input?.files?.[0];
    if (!file) return;
    if (file.size > 8 * 1024 * 1024) throw Error('Файл больше 8 МБ.');
    const data = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result).split(',')[1] || '');
      reader.onerror = () => reject(Error('Не удалось прочитать файл.'));
      reader.readAsDataURL(file);
    });
    await api(`tickets/${encodeURIComponent(id)}/files`, { name: file.name, mime: file.type || 'application/octet-stream', data });
  }

  function authReturn() {
    try {
      const route = sessionStorage.getItem(authReturnKey) || '';
      sessionStorage.removeItem(authReturnKey);
      return /^account(?:\/[a-z-]+)?(?:\?ticket=[a-f0-9]+)?$/i.test(route) ? route : 'account/link';
    } catch { return 'account/link'; }
  }

  function saveAuthReturn(route) {
    try { sessionStorage.setItem(authReturnKey, route); } catch { /* Optional navigation convenience. */ }
  }

  function passField(label, name, autocomplete, placeholder, minlength = 0, hint = '') {
    return `<label class="field">${label}<span class="v7-pass-wrap"><input name="${name}" type="password" required${minlength ? ` minlength="${minlength}"` : ''} maxlength="256" autocomplete="${autocomplete}" placeholder="${placeholder}"${hint ? ` aria-describedby="auth-${name}-hint"` : ''}><button type="button" class="v7-pass-toggle" data-action="v7-pass-toggle" aria-label="Показать пароль" aria-pressed="false">${icon('eye')}</button></span>${hint ? `<small class="field-hint" id="auth-${name}-hint">${hint}</small>` : ''}<em class="v7-caps" data-caps-lock role="status" hidden>Caps Lock включён</em></label>`;
  }

  function authMarkup(tab) {
    const registering = tab === 'register';
    const title = registering ? 'Создать аккаунт' : 'Войти';
    const intro = registering ? 'Создай логин и пароль. Затем привяжи Minecraft, чтобы видеть баланс и покупки.' : 'Введи логин и пароль.';
    return `<div class="v7-auth-layout v9-auth-layout"><aside class="v7-auth-aside"><img src="${M.asset('assets/img/world.webp')}" alt="" decoding="async"></aside><section class="v7-auth-main"><h1>${title}</h1><p class="v7-auth-lead">${intro}</p><nav class="v7-auth-tabs" aria-label="Вход или регистрация"><a class="${registering ? '' : 'active'}" href="#auth/login"${registering ? '' : ' aria-current="page"'}>Вход</a><a class="${registering ? 'active' : ''}" href="#auth/register"${registering ? ' aria-current="page"' : ''}>Регистрация</a></nav><form data-form="${registering ? 'v7-register' : 'v7-login'}"><label class="field">Логин сайта<input name="username" type="text" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_]{3,32}" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="Логин сайта" value=""></label>${registering ? passField('Пароль', 'password', 'new-password', 'Пароль', 10, 'Минимум 10 символов.') + passField('Повтори пароль', 'repeat', 'new-password', 'Ещё раз', 10) + '<label class="check-row"><input type="checkbox" name="terms" required><span>Принимаю <a href="#rules">правила сервера</a></span></label>' : passField('Пароль', 'password', 'current-password', 'Пароль аккаунта') + '<label class="check-row"><input type="checkbox" name="remember" checked><span>Оставаться в аккаунте на этом устройстве<small class="v7-remember-hint">30 дней без повторного входа. Без галочки сеанс завершится при закрытии браузера.</small></span></label>' + '<details class="v7-2fa"><summary>Включена двухфакторная защита</summary><label class="field">Код из приложения<input name="totp" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="8" placeholder="6 цифр"></label></details>'}<div class="form-error" role="alert"></div><button type="submit" class="btn primary wide">${title}${icon('arrow-right')}</button></form>${registering ? '<p class="v7-auth-bottom">Уже зарегистрирован? <a href="#auth/login">Войти</a></p>' : '<p class="v7-auth-bottom">Нет аккаунта? <a href="#auth/register">Создать</a></p>'}</section></div>`;
  }

  const capsHint = event => {
    const input = event.target;
    if (!(input instanceof HTMLInputElement) || !input.closest('.v7-pass-wrap')) return;
    const hint = input.closest('.field')?.querySelector('[data-caps-lock]');
    if (hint) hint.hidden = !(typeof event.getModifierState === 'function' && event.getModifierState('CapsLock'));
  };
  document.addEventListener('keydown', capsHint, true);
  document.addEventListener('keyup', capsHint, true);
  document.addEventListener('focusout', event => {
    const hint = event.target?.closest?.('.field')?.querySelector?.('[data-caps-lock]');
    if (hint) hint.hidden = true;
  }, true);
  H['v7-pass-toggle'] = button => {
    const input = button.closest('.v7-pass-wrap')?.querySelector('input');
    if (!input) return;
    const show = input.type === 'password';
    input.type = show ? 'text' : 'password';
    button.innerHTML = icon(show ? 'eye-off' : 'eye');
    button.setAttribute('aria-label', show ? 'Скрыть пароль' : 'Показать пароль');
    button.setAttribute('aria-pressed', String(show));
    input.focus({ preventScroll: true });
  };

  // Every password field gets the same reveal and Caps Lock hint, including
  // settings, recovery and admin forms that are rendered outside this file.
  function enhancePasswordFields(root = document) {
    root.querySelectorAll('input[type="password"]').forEach(input => {
      if (input.closest('.v7-pass-wrap') || input.dataset.cmPassReady) return;
      input.dataset.cmPassReady = '1';
      const wrap = document.createElement('span');
      wrap.className = 'v7-pass-wrap';
      input.parentNode.insertBefore(wrap, input);
      wrap.appendChild(input);
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'v7-pass-toggle';
      button.dataset.action = 'v7-pass-toggle';
      button.setAttribute('aria-label', 'Показать пароль');
      button.setAttribute('aria-pressed', 'false');
      button.innerHTML = icon('eye');
      wrap.appendChild(button);
      const field = input.closest('.field');
      if (field && !field.querySelector('[data-caps-lock]')) {
        const hint = document.createElement('em');
        hint.className = 'v7-caps';
        hint.dataset.capsLock = '';
        hint.setAttribute('role', 'status');
        hint.hidden = true;
        hint.textContent = 'Caps Lock включён';
        field.appendChild(hint);
      }
    });
  }
  let passEnhanceFrame = 0;
  function schedulePasswordEnhance() {
    if (passEnhanceFrame) return;
    passEnhanceFrame = requestAnimationFrame(() => { passEnhanceFrame = 0; enhancePasswordFields(document); });
  }
  new MutationObserver(schedulePasswordEnhance).observe(document.body, { childList: true, subtree: true });
  schedulePasswordEnhance();

  R.auth = tab => authMarkup(tab === 'register' ? 'register' : 'login');
  R.inbox = () => R.auth('login');
  F['v7-login'] = async (form, data) => {
    let result;
    try {
      result = await Q.request('login', { username: String(data.get('username') || '').trim(), password: data.get('password'), totp: String(data.get('totp') || '').trim(), remember: !!data.get('remember') });
    } catch (error) {
      if (/двухфактор/i.test(error.message || '') && form) {
        const block = form.querySelector('details.v7-2fa');
        if (block && !block.open) { block.open = true; block.querySelector('input')?.focus(); }
      }
      throw error;
    }
    Q.csrf = result.csrf || Q.csrf;
    await Q.reload();
    if (!Q.user) throw Error('Не удалось открыть аккаунт. Обнови страницу и войди ещё раз.');
    Q.hint = false;
    M.closeModal();
    M.navTo(authReturn());
  };
  F['v7-register'] = async (form, data) => {
    if (!data.get('terms')) throw Error('Прими правила сервера, чтобы продолжить.');
    if (data.get('password') !== data.get('repeat')) throw Error('Пароли не совпадают.');
    const result = await api('auth/register', { username: String(data.get('username') || '').trim(), password: data.get('password'), terms: true, remember: false });
    Q.csrf = result.csrf || Q.csrf;
    await Q.reload();
    if (!Q.user) throw Error('Аккаунт создан, но войти не удалось. Попробуй выполнить вход.');
    Q.hint = false;
    M.closeModal();
    M.navTo(authReturn());
  };
  F['v7-code'] = F['v7-reset'] = F['v7-confirm-code'] = async () => { throw Error('Войди по нику и паролю.'); };
  H['v7-vk'] = undefined;
  H['v7-link-email'] = H['v7-unlink'] = H['v7-unlink-confirm'] = H['v7-recovery-help'] = undefined;

  const faqRows = () => (state().faq || []).filter(row => row?.published !== false);
  R.faq = () => {
    const rows = faqRows();
    return `<section class="v9-faq"><header><span class="kicker">CopiMine</span><h1>FAQ</h1></header><div class="v9-faq-list">${rows.map(row => `<details><summary>${E(row.question || row.q || row.title || 'Вопрос')}${icon('plus')}</summary><p>${E(row.answer || row.a || row.body || '')}</p></details>`).join('') || M.empty('Ответы скоро появятся','','message')}</div><footer><span>Не нашёл ответ?</span>${M.btn('Написать в поддержку','faq-contact-support','arrow-right','primary')}</footer></section>`;
  };
  R.page = slug => slug === 'help' ? R.faq() : oldPage(slug);
  H['faq-contact-support'] = () => {
    if (M.me()) return M.navTo('account/support');
    saveAuthReturn('account/support');
    M.navTo('auth/login');
  };
  H['how-buy'] = () => M.navTo('faq');
  const oldShop = R.shop;
  if (oldShop) R.shop = (...args) => oldShop(...args).replaceAll('Как получить покупку', 'FAQ');

  R.account = tab => {
    Q.hint = false;
    if (tab === 'link' && M.me()) return A.heading('Minecraft', 'Привяжи игровой аккаунт по коду из игры.', M.link('В кабинет', '#account', 'arrow-left', 'ghost')) + M.accountTabs('link');
    if (tab !== 'support' || !M.me()) return oldAccount(tab);
    const user = M.me();
    const tickets = (state().tickets || []).filter(ticket => ticket.playerId === user.id || ticket.player === user.name);
    return `<section class="v9-account-support"><header><div><span class="kicker">Личный кабинет</span><h1>Поддержка</h1></div><div class="actions">${M.link('FAQ', '#faq', 'help-circle', 'ghost small')}${M.btn('Новое обращение', 'new-ticket', 'plus', 'primary small')}</div></header>${M.accountTabs('support')}<div class="panel">${tickets.length ? tickets.map(ticket => `<button type="button" class="v9-ticket-row" data-action="ticket-detail" data-id="${E(ticket.id)}"><span><strong>${E(ticket.title)}</strong><small>${E(ticket.id)} · ${M.date(ticket.updated_s ? ticket.updated_s * 1000 : ticket.at, true)}${ticket.messages?.length ? ` · ${ticket.messages.length} сообщений` : ''}</small></span><span>${M.status(ticket.status)}</span>${icon('arrow-right')}</button>`).join('') : M.empty('Обращений пока нет', 'Создай обращение, чтобы написать администрации.', 'chat')}</div></section>`;
  };

  H['new-ticket'] = () => {
    if (!M.me()) { saveAuthReturn('account/support'); M.navTo('auth/login'); return; }
    M.openModal('Новое обращение', `<form data-form="ticket"><label class="field">Тема<select name="type"><option>Покупка</option><option>Вход в игру</option><option>Жалоба</option><option>Другое</option></select></label>${V.field('Коротко о проблеме', 'title', '', 'text', 'required minlength="3" maxlength="160"')}${V.area('Сообщение', 'body', '', 5, 'required minlength="5" maxlength="6000" placeholder="Опиши, что произошло"')}<label class="field">Приложить фото или файл<small>Фото, PDF, лог или архив до 8 МБ. Файл проверяется антивирусом до сохранения.</small><input type="file" name="attachment" accept="image/png,image/jpeg,image/webp,image/gif,text/plain,text/csv,application/json,application/pdf,application/zip,application/gzip" data-ticket-file="new"></label><div class="form-error" role="alert"></div>${V.actions('Отправить обращение')}</form>`);
  };
  F.ticket = async (form, data) => {
    if (!M.me()) throw Error('Войди в аккаунт, чтобы написать в поддержку.');
    const title = String(data.get('title') || '').trim(), body = String(data.get('body') || '').trim();
    if (title.length < 3 || body.length < 5) throw Error('Заполни тему и сообщение.');
    const result = await api('tickets', { title, body, type: String(data.get('type') || 'support') });
    if (result?.ticket?.id) await uploadAttachment(form, result.ticket.id);
    await Q.reload();
    // navTo на текущий маршрут не меняет хеш и не вызывает render(), поэтому
    // окно закрываем сами — иначе форма висит поверх списка.
    M.closeModal();
    M.navTo('account/support');
    M.toast('Обращение отправлено.');
  };

  const filesRow = (ticket) => {
    const files = ticket.files || [];
    if (!files.length) return '';
    return `<div class="v9-ticket-files">${files.map(file => `<a class="v9-ticket-file" href="/ticket-file/${E(file.id)}" target="_blank" rel="noopener">${E(file.name)}<small>${Math.max(1, Math.round((file.bytes || 0) / 1024))} КБ</small></a>`).join('')}</div>`;
  };

  H['ticket-detail'] = button => {
    const ticket = (state().tickets || []).find(row => row.id === button.dataset.id);
    if (!ticket) return;
    const admin = M.UI.page === 'admin';
    const messages = ticket.messages?.length ? ticket.messages : [{ actor: ticket.player || 'Игрок', role: 'player', body: ticket.body, at: ticket.at }, ...(ticket.reply ? [{ actor: 'Команда', role: 'owner', body: ticket.reply, at: ticket.firstReplyAt || ticket.updated_s * 1000 }] : [])];
    const thread = `<div class="v9-ticket-thread">${messages.map(message => `<article class="v9-ticket-message ${message.role === 'player' ? 'from-player' : 'from-team'}"><small>${E(message.actor || (message.role === 'player' ? ticket.player : 'Команда'))} · ${M.date(message.at, true)}</small><p>${E(message.body)}</p></article>`).join('')}</div>${filesRow(ticket)}`;
    const actions = admin
      ? `<form data-form="ticket-answer" class="v9-ticket-reply"><input type="hidden" name="id" value="${E(ticket.id)}">${V.area('Ответ игроку', 'reply', '', 4, 'required minlength="3" maxlength="6000"')}<div class="field-row">${V.select('Статус', 'status', [['open', 'Новое'], ['review', 'В работе'], ['closed', 'Закрыть']], ticket.status)}${V.select('Приоритет', 'priority', [['normal', 'Обычный'], ['high', 'Высокий'], ['urgent', 'Срочный']], ticket.priority || 'normal')}</div><div class="form-error" role="alert"></div>${V.actions('Отправить ответ')}</form><div class="actions mt">${M.btn('Создать расследование', 'case-from-ticket', 'shield', 'ghost small', `data-id="${E(ticket.id)}"`)}</div>`
      : ticket.status === 'closed'
        ? `<p class="v9-ticket-closed">Обращение закрыто. Если вопрос остался, создай новое.</p>${M.btn('Новое обращение', 'new-ticket', 'plus', 'ghost small')}`
        : `<form data-form="ticket-message" class="v9-ticket-reply"><input type="hidden" name="id" value="${E(ticket.id)}">${V.area('Сообщение', 'body', '', 3, 'required minlength="3" maxlength="6000"')}<label class="field">Приложить фото или файл<small>Фото, PDF, лог или архив до 8 МБ. Файл проверяется антивирусом до сохранения.</small><input type="file" name="attachment" accept="image/png,image/jpeg,image/webp,image/gif,text/plain,text/csv,application/json,application/pdf,application/zip,application/gzip" data-ticket-file="${E(ticket.id)}"></label><div class="form-error" role="alert"></div>${V.actions('Отправить')}</form>`;
    M.openModal(`${E(ticket.title)} <span class="v9-ticket-id">${E(ticket.id)}</span>`, `<div class="v9-ticket-meta">${M.status(ticket.status)}${admin ? M.pill(ticket.priority === 'urgent' ? 'Срочно' : ticket.priority === 'high' ? 'Высокий приоритет' : 'Обычный') : ''}${admin ? `<span>${E(ticket.playerName || ticket.player || '')}</span>` : ''}</div>${thread}${actions}`, 'v9-ticket-dialog');
  };

  F['ticket-message'] = async (form, data) => {
    const id = String(data.get('id') || '');
    await api(`tickets/${encodeURIComponent(id)}/messages`, { body: String(data.get('body') || '').trim() });
    await uploadAttachment(form, id);
    await Q.reload();
    M.closeModal();
    M.navTo(`account/support?ticket=${encodeURIComponent(id)}`);
    M.toast('Сообщение отправлено.');
  };
  F['ticket-answer'] = async (form, data) => {
    const id = String(data.get('id') || ''), reply = String(data.get('reply') || '').trim();
    await api(`admin/tickets/${encodeURIComponent(id)}`, { reply, status: data.get('status'), priority: data.get('priority') }, 'PATCH');
    await Q.reload();
    H['ticket-detail']({ dataset: { id } });
    M.toast(reply ? 'Ответ сохранён.' : 'Изменения сохранены.');
  };

  function settingsShell(tab, content) {
    const tabs = [['profile', 'Профиль', 'user'], ['security', 'Безопасность', 'shield'], ['sessions', 'Устройства', 'monitor'], ['notifications', 'Уведомления', 'bell'], ['privacy', 'Приватность', 'eye'], ['interface', 'Интерфейс', 'sliders']];
    return `${A.heading ? A.heading('Настройки', 'Профиль, безопасность и личные предпочтения.', M.link('В кабинет', '#account', 'arrow-left', 'ghost')) : ''}<div class="v71-settings-layout"><aside class="v71-settings-side"><div class="v71-settings-identity">${W.head(M.me(), 40)}<div><strong>${E(M.me()?.displayName || M.me()?.name)}</strong><small>Твой аккаунт</small></div></div><nav aria-label="Настройки">${tabs.map(([key, label, ic]) => `<a href="#settings/${key}" class="${tab === key ? 'active' : ''}" ${tab === key ? 'aria-current="page"' : ''}>${icon(ic)}${label}${icon('chevron-right')}</a>`).join('')}</nav></aside><div class="v71-settings-content">${content}</div></div>`;
  }

  R.settings = (requested = 'profile') => {
    if (!M.me()) return R.auth('login');
    const tab = requested === 'connections' ? 'security' : requested;
    if (tab === 'profile') {
      const p = M.me();
    return settingsShell(tab, `<section class="v7-settings-section"><h2>Профиль</h2><form data-form="v7-profile" class="v7-form-narrow">${V.field('Отображаемое имя', 'displayName', p.displayName || p.name, 'text', 'required minlength="1" maxlength="32" autocomplete="nickname"')}<label class="field">Ник на сайте<input value="${E(p.name)}" readonly aria-readonly="true"></label><p class="hint">Изменение отображаемого имени не меняет игровой ник.</p><div class="form-error" role="alert"></div>${V.actions('Сохранить')}</form></section>`);
    }
    if (tab === 'security') {
      return settingsShell(tab, `<section class="v7-settings-section"><h2>Сменить пароль</h2><form data-form="v7-password" class="v7-form-narrow">${V.field('Текущий пароль', 'current', '', 'password', 'required autocomplete="current-password" maxlength="256"')}${V.field('Новый пароль', 'password', '', 'password', 'required minlength="10" maxlength="256" autocomplete="new-password"')}${V.field('Повтори новый пароль', 'repeat', '', 'password', 'required minlength="10" maxlength="256" autocomplete="new-password"')}<p class="hint">После смены остальные устройства выйдут из аккаунта.</p><div class="form-error" role="alert"></div>${V.actions('Сменить пароль')}</form></section>`);
    }
    if (tab === 'sessions') {
      const rows = state().siteSessions || [];
      return settingsShell(tab, `<section class="v7-settings-section"><div class="panel-head"><h2>Устройства</h2>${rows.some(row => !row.current) ? M.btn('Завершить остальные', 'v9-revoke-others', 'log-out', 'ghost small') : ''}</div>${rows.length ? `<div class="v9-session-list">${rows.map(row => `<article class="v9-session-row"><div>${icon('monitor')}<span><strong>${E(row.device || 'Браузер')}</strong><small>${M.date(row.createdAt, true)} · ${row.current ? 'Это устройство' : 'Активный сеанс'}</small></span></div>${row.current ? M.pill('Текущий', 'green') : M.btn('Завершить', 'v9-revoke-session', 'log-out', 'ghost small', `data-id="${E(row.id)}"`)}</article>`).join('')}</div>` : M.empty('Активных сеансов нет', '', 'monitor')}</section>`);
    }
    if (tab === 'privacy') {
      return settingsShell(tab, `<section class="v7-settings-section"><h2>Приватность</h2><p class="muted">Сайт хранит только то, что нужно для входа, покупок и обращений. Полный перечень — в <a href="#privacy">политике конфиденциальности</a>.</p><div class="v7-form-narrow"><h3>Файлы cookie</h3><p class="hint">Аналитику и настройки интерфейса можно включать и выключать в любой момент.</p>${M.btn('Изменить выбор cookie', 'v6-cookies', 'settings', 'ghost')}<h3 class="mt">Мои данные</h3><p class="hint">Выгрузим аккаунт, сеансы, историю входов, обращения и заказы одним файлом JSON.</p>${M.btn('Скачать мои данные', 'v9-export-data', 'download', 'ghost')}<h3 class="mt">Удаление аккаунта</h3><p class="hint">Аккаунт обезличивается и не может войти. Заказы и журнал действий администрации остаются — этого требует закон. Вернуть аккаунт после удаления нельзя.</p>${M.btn('Удалить аккаунт', 'v9-delete-account', 'trash', 'danger-btn')}</div></section>`);
    }
    const html = oldSettings(tab);
    const parsed = new DOMParser().parseFromString(html, 'text/html');
    const content = parsed.querySelector('.v71-settings-content')?.innerHTML || parsed.querySelector('.v7-settings-layout > div')?.innerHTML || html;
    parsed.querySelector('a[href="#settings/connections"]')?.remove();
    return settingsShell(tab, content.replace(/Профиль, связь и личные предпочтения\./g, 'Профиль, безопасность и настройки.'));
  };

  H['v9-revoke-session'] = button => M.openModal('Завершить сеанс?', `<p>На этом устройстве нужно будет войти снова.</p><div class="v71-dialog-actions">${M.btn('Отмена', 'close', '', 'ghost')}${M.btn('Завершить', 'v9-revoke-session-confirm', 'log-out', 'primary', `data-id="${E(button.dataset.id)}"`)}</div>`);
  H['v9-revoke-session-confirm'] = async button => {
    await api(`account/sessions/${encodeURIComponent(button.dataset.id)}/revoke`, {});
    M.closeModal(); await Q.reload(); M.toast('Сеанс завершён.');
  };
  H['v9-revoke-others'] = () => M.openModal('Завершить остальные сеансы?', `<p>Другие устройства выйдут из аккаунта. Это устройство останется активным.</p><div class="v71-dialog-actions">${M.btn('Отмена', 'close', '', 'ghost')}${M.btn('Завершить сеансы', 'v9-revoke-others-confirm', 'log-out', 'primary')}</div>`);
  H['v9-revoke-others-confirm'] = async () => {
    const result = await api('account/sessions/revoke-others', {});
    M.closeModal(); await Q.reload(); M.toast(`Завершено сеансов: ${result.revoked}.`);
  };

  const call = (path, body) => (window.CM6 && window.CM6.request ? window.CM6.request(path, { method: 'POST', body }) : api(path, body));

  H['v9-export-data'] = async () => {
    const result = await call('account/export', {});
    const blob = new Blob([JSON.stringify(result, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob), link = document.createElement('a');
    link.href = url; link.download = `copimine-account-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link); link.click(); link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 4000);
    M.toast('Файл с данными скачан.');
  };
  H['v9-delete-account'] = () => M.openModal('Удалить аккаунт?', `<p>Аккаунт будет обезличен и больше не сможет войти. Заказы и журнал администрации сохранятся.</p><form data-form="v9-delete-account"><label class="field">Введи слово УДАЛИТЬ<input name="confirm" required autocomplete="off" maxlength="20"></label><label class="field">Пароль<input name="password" type="password" required autocomplete="current-password" maxlength="256"></label><div class="form-error" role="alert"></div><div class="v71-dialog-actions">${M.btn('Отмена', 'close', '', 'ghost')}<button class="btn danger-btn" type="submit">Удалить аккаунт</button></div></form>`);
  F['v9-delete-account'] = async (form, data) => {
    await api('account/delete', { confirm: String(data.get('confirm') || ''), password: String(data.get('password') || '') });
    M.closeModal();
    Q.user = null;
    await Q.reload();
    M.navTo('home');
    M.toast('Аккаунт удалён.');
  };

  function stopMinecraftPoll() { clearInterval(minecraftPoll); minecraftPoll = 0; }
  function startMinecraftPoll() {
    stopMinecraftPoll();
    minecraftPoll = setInterval(async () => {
      const user = currentAccountUser();
      const onLinkPage = M.UI?.page === 'account' && (M.UI.tab === 'link' || user && !user.gameLinkVerified);
      if (!pendingMinecraftLink || !onLinkPage) { stopMinecraftPoll(); return; }
      const status = document.querySelector('[data-link-status]');
      if (Date.now() > pendingMinecraftLink.expiresAt) {
        stopMinecraftPoll();
        if (status) status.textContent = 'Код истёк. Запроси новый.';
        return;
      }
      try {
        const session = await api('session');
        if (session.user?.gameLinkVerified) {
          stopMinecraftPoll(); clearPendingLink();
          try { await Q.reload({ silent: true }); } catch { /* The authenticated session response still carries the confirmed link. */ }
          syncLinkedUser(session.user);
          await openLinkedCabinet();
        }
      } catch {
        if (status) status.textContent = 'Проверка временно недоступна. Повторяем запрос.';
      }
    }, 3000);
  }
  H['v7-game-link'] = () => {
    const user = currentAccountUser();
    if (!user) { saveAuthReturn('account/link'); M.navTo('auth/login'); return; }
    M.navTo('account/link');
  };
  F['production-mc-code'] = async (form, data) => {
    const name = String(data.get('name') || '').trim();
    const result = await api('account/minecraft/request', { name });
    savePendingLink(currentAccountUser(), { name, expiresAt: Number(result.expiresAt || Date.now() + 600000) });
    M.render();
    startMinecraftPoll();
    animateLinkStep();
  };
  F['production-mc-confirm'] = async (form, data) => {
    const result = await api('account/minecraft/confirm', { code: String(data.get('code') || '').trim() });
    try { await Q.reload({ silent: true }); } catch { /* The confirmation response still carries the linked account. */ }
    syncLinkedUser(result.user);
    if (result.user?.gameLinkVerified || currentAccountUser()?.gameLinkVerified) {
      stopMinecraftPoll(); clearPendingLink();
      await openLinkedCabinet();
    } else {
      M.render(); startMinecraftPoll(); animateLinkStep();
    }
  };
  H['production-mc-restart'] = () => { stopMinecraftPoll(); clearPendingLink(); M.render(); animateLinkStep(); };
  window.CMAccountLink = { state: () => {
    const user = currentAccountUser();
    if (pendingMinecraftLink && pendingMinecraftLink.userId !== user?.id) pendingMinecraftLink = null;
    if (!pendingMinecraftLink && user) pendingMinecraftLink = loadPendingLink(user);
    return { user, pending: pendingMinecraftLink ? { name: pendingMinecraftLink.name, expiresAt: pendingMinecraftLink.expiresAt } : null };
  } };

  V.after.push((page, tab) => {
    const user = currentAccountUser();
    const admin = !!window.CM6?.canAdmin?.();
    if (user && !user.gameLinkVerified && !admin && page === 'account') {
      document.title = 'Привязка Minecraft · CopiMine';
      if (tab !== 'link') { M.navTo('account/link'); return; }
      if (pendingMinecraftLink) startMinecraftPoll();
      return;
    }
    if (user?.gameLinkVerified && page === 'account' && tab === 'link') { M.navTo('account'); return; }
    if (page === 'account' && !tab) {
      try {
        if (sessionStorage.getItem(linkedCabinetKey) === '1') {
          sessionStorage.removeItem(linkedCabinetKey);
          requestAnimationFrame(() => window.CMSiteMotion?.accountReveal?.(document.getElementById('view'), motionEnabled()));
        }
      } catch { /* The cabinet remains available without session storage. */ }
    }
    if (page === 'faq') document.title = 'FAQ · CopiMine';
    document.querySelectorAll('.breadcrumb').forEach(crumb => {
      const root = [...crumb.children].find(node => node.tagName === 'SPAN' && ['CopiMine', 'Управление'].includes(node.textContent.trim()));
      if (root) {
        const link = document.createElement('a'); link.href = '#admin/overview'; link.className = 'v9-breadcrumb-home'; link.textContent = root.textContent.trim(); link.setAttribute('aria-label', 'Открыть обзор управления'); root.replaceWith(link);
      }
      [...crumb.children].find(node => node.tagName === 'STRONG')?.setAttribute('aria-current', 'page');
    });
  });
})();

